  --spw-component-pad: calc(var(--spw-rhythm-unit) * 0.78);
  --spw-component-pad-tight: calc(var(--spw-rhythm-unit) * 0.56);
  --spw-component-pad-loose: calc(var(--spw-rhythm-unit) * 0.92);
  --spw-component-pad-roomy: calc(var(--spw-rhythm-unit) * 1.12);
  --spw-surface-gap: calc(var(--spw-rhythm-unit) * 0.8);
  --spw-surface-padding: clamp(
    calc(var(--spw-rhythm-unit) * 0.9),
