    --spw-surface-gap: calc(var(--spw-rhythm-unit) * 0.78);
    --spw-surface-padding: calc(var(--spw-rhythm-unit) * 0.82);
    --spw-slot-gap: calc(var(--spw-rhythm-unit) * 0.56);
    --spw-slot-gap-tight: calc(var(--spw-rhythm-unit) * 0.34) calc(var(--spw-rhythm-unit) * 0.46);
    --spw-hero-gap: calc(var(--spw-rhythm-unit) * 0.92);
    --spw-shell-row-gap: 0.36rem;
    --spw-shell-trace-gap: 0.46rem;
    --spw-shell-surface-padding-block: 0.34rem;
    --spw-shell-surface-padding-inline: 0.4rem;
    --spw-shell-link-gap: 0.32rem;
    --touch-target-compact: 2.08rem;
    --spw-control-min-height: 2.02rem;
    --spw-control-padding-block: 0.2rem;
    --spw-control-padding-inline: 0.6rem;
    --spw-control-gap: 0.24rem;
    --manuscript-margin-width: clamp(1rem, 5vw, 2rem);
    --manuscript-comment-width: min(100%, 20rem);
  }
}

@media (max-width: 760px) and (orientation: landscape), (max-width: 640px) and (max-height: 520px) {
  :root {
    --spw-device-space-scale: 0.86;
    --spw-flow-space: calc(var(--spw-rhythm-unit) * 0.8);
    --spw-component-gap: calc(var(--spw-rhythm-unit) * 0.72);
    --spw-component-gap-tight: calc(var(--spw-rhythm-unit) * 0.36);
    --spw-component-pad: calc(var(--spw-rhythm-unit) * 0.7);
    --spw-component-pad-tight: calc(var(--spw-rhythm-unit) * 0.5);
    --spw-surface-gap: calc(var(--spw-rhythm-unit) * 0.72);
    --spw-surface-padding: calc(var(--spw-rhythm-unit) * 0.72);
    --spw-shell-row-gap: 0.3rem;
    --spw-shell-surface-padding-block: 0.28rem;
    --spw-shell-surface-padding-inline: 0.34rem;
    --spw-shell-link-gap: 0.28rem;
    --touch-target-compact: 1.98rem;
    --spw-control-min-height: 1.96rem;
    --spw-control-padding-block: 0.18rem;
    --spw-control-padding-inline: 0.56rem;
  }
}

@media (max-width: 420px) {
  :root {
    --spw-device-space-scale: 0.84;
    --spw-flow-space: calc(var(--spw-rhythm-unit) * 0.78);
    --spw-surface-padding: calc(var(--spw-rhythm-unit) * 0.68);
    --spw-component-pad: calc(var(--spw-rhythm-unit) * 0.68);
    --spw-shell-trace-gap: 0.38rem;
    --spw-shell-surface-padding-inline: 0.3rem;
    --spw-control-padding-inline: 0.54rem;
    --spw-control-gap: 0.22rem;
  }
}
}

/* /public/css/tokens/dimensions.css */
@layer tokens {
/* ==========================================================================
   dimensions.css
   --------------------------------------------------------------------------
   Canonical cross-dimensional vocabulary for Spw surfaces.

   File role (code as documentation)
   - Names the axes that HTML attrs, JS datasets, and CSS tokens share.
   - Provides alias routing so drifted terms (dense/spacious, soft/roomy) map
     to one teachable ladder without rewriting every route.
   - Owns pre-state / empty-state visibility and theme-diverse color stacks.
   - Does not spend layout rules; components and systems consume these tokens.

   Dimension axes
   - spatial   : packing tiers, occupancy, room, measure
   - temporal  : ecology phase, positioning phase, hydration lifecycle
   - color     : fill / ink / line / accent layering per theme pack
   - semantic  : variant, genre, resonance, succession
   - attention : salience, depth, positioning bias

   See also
   - .spw/conventions/dimension-vocabulary.spw
   - public/css/components/typography-packing.css
   - public/js/runtime/loading-ecology.js (DIMENSION_VOCABULARY)
   ========================================================================== */

:root {
  /* ------------------------------------------------------------------------
     Spatial — packing tier ladder (canonical: compact | balanced | roomy)
     ------------------------------------------------------------------------ */
  --spw-pack-tier: balanced;
  --spw-pack-occupancy-weight: 0.5;
  --spw-pack-measure-active: var(--measure-panel, 52ch);
  --spw-pack-pad-active: var(--spw-component-pad, 0.9rem);
  --spw-pack-gap-active: var(--component-gap, 0.9rem);

  /* ------------------------------------------------------------------------
     Temporal — positioning phases (salience direction + page ecology)
     ------------------------------------------------------------------------ */
  --spw-position-phase: anchor;
  --spw-position-bias-y: 0px;
  --spw-position-depth: var(--depth-settled, 10);

  /* ------------------------------------------------------------------------
     Lifecycle — pre-state / empty / hydration visibility
     subtle (0.22) → balanced (0.5) → apparent (0.82)
     ------------------------------------------------------------------------ */
  --spw-lifecycle-phase: ready;
  --spw-pre-state-visibility: 0.5;
  --spw-pre-state-fill-mix: 0.08;
  --spw-pre-state-line-mix: 0.18;
  --spw-pre-state-ink-mix: 0.62;

  /* ------------------------------------------------------------------------
     Color layering — theme-agnostic stack aliases (spend fill/ink/line/rest)
     ------------------------------------------------------------------------ */
  --spw-color-layer-fill: var(--spw-surface-fill-rest, var(--surface));
  --spw-color-layer-fill-muted: var(--spw-surface-fill-soft, var(--surface-soft));
  --spw-color-layer-ink: var(--ink, currentColor);
  --spw-color-layer-ink-muted: var(--ink-soft, color-mix(in srgb, var(--ink, currentColor) 72%, transparent));
  --spw-color-layer-line: var(--spw-surface-line-rest, var(--line));
  --spw-color-layer-accent-subtle: color-mix(
    in srgb,
    var(--active-op-color, var(--teal, #008080)) 18%,
    transparent
  );
  --spw-color-layer-accent-apparent: color-mix(
    in srgb,
    var(--active-op-color, var(--teal, #008080)) 42%,
    transparent
  );

  /* ------------------------------------------------------------------------
     Variant selection — semantic accent weight for chosen variant/genre
     ------------------------------------------------------------------------ */
  --spw-variant-selection-weight: 0;
  --spw-variant-accent: var(--component-accent, var(--active-op-color, var(--teal, #008080)));

  /* Real estate — horizontal measure + vertical stack (hypermedia 2D axes) */
  --spw-real-estate-inline: var(--measure-reading, 68ch);
  --spw-real-estate-block: var(--page-stack-gap, clamp(1rem, 2.3vw, 1.7rem));
  --spw-real-estate-section: var(--page-section-gap, clamp(1.85rem, 4vw, 3.25rem));
  --spw-typography-rank-1: 1;
  --spw-typography-rank-2: 0.88;
  --spw-typography-rank-3: 0.76;
  --spw-typography-rank-4: 0.64;

  /* Interactive medium — device + entertainment register (spent in systems layer) */
  --spw-medium-touch-min: 2.75rem;
  --spw-medium-lane-pad: 0.55rem;
  --spw-medium-layout-gap-scale: 1;
  --spw-medium-reveal-stagger-step: 72ms;
  --spw-medium-accent-weight: 1;
  --spw-medium-intensity: 0.5;
  --spw-module-style-modulator: 1;
}

/* ==========================================================================
   1. Packing tier routing
   ========================================================================== */

:where(
  [data-spw-packing-state="compact"],
  [data-spw-density="dense"],
  [data-spw-component-density="dense"],
  [data-spw-pack="compact"],
  [data-spw-pack="dense"],
  html[data-spw-design-ecology-packing="compact"]
) {
  --spw-pack-tier: compact;
  --spw-pack-occupancy-weight: 0.28;
  --spw-pack-measure-active: var(--measure-compact, 32ch);
  --spw-pack-pad-active: var(--pack-tier-compact-pad, var(--spw-component-pad-tight, 0.65rem));
  --spw-pack-gap-active: var(--pack-tier-compact-gap, var(--component-gap-tight, 0.55rem));
}

:where(
  [data-spw-packing-state="balanced"],
  [data-spw-pack="balanced"],
  [data-spw-pack-occupancy="balanced"],
  html[data-spw-design-ecology-packing="balanced"]
) {
  --spw-pack-tier: balanced;
  --spw-pack-occupancy-weight: 0.5;
  --spw-pack-measure-active: var(--measure-panel, 52ch);
  --spw-pack-pad-active: var(--pack-tier-balanced-pad, var(--spw-component-pad, 0.9rem));
  --spw-pack-gap-active: var(--pack-tier-balanced-gap, var(--component-gap, 0.9rem));
}

:where(
  [data-spw-packing-state="roomy"],
  [data-spw-packing-state="spacious"],
  [data-spw-density="soft"],
  [data-spw-density="roomy"],
  [data-spw-component-density="roomy"],
  [data-spw-pack="roomy"],
  html[data-spw-design-ecology-packing="spacious"],
  html[data-spw-design-ecology-packing="roomy"]
) {
  --spw-pack-tier: roomy;
  --spw-pack-occupancy-weight: 0.78;
  --spw-pack-measure-active: var(--measure-reading, 68ch);
  --spw-pack-pad-active: var(--pack-tier-roomy-pad, var(--spw-component-pad-loose, 1.15rem));
  --spw-pack-gap-active: var(--pack-tier-roomy-gap, var(--component-gap-loose, 1.2rem));
}

:where([data-spw-pack-occupancy="sparse"]) {
  --spw-pack-tier: compact;
  --spw-pack-occupancy-weight: 0.22;
}

:where([data-spw-pack-occupancy="full"]) {
  --spw-pack-tier: roomy;
  --spw-pack-occupancy-weight: 0.88;
}

/* ==========================================================================
   2. Positioning phase routing
   ========================================================================== */

:where(html[data-spw-loading-ecology-salience="forward"], html[data-spw-page-arrival="entering"]) {
  --spw-position-phase: approach;
  --spw-position-bias-y: var(--spw-ecology-salience-shift, var(--spw-settle-offset-start, 2px));
  --spw-position-depth: var(--depth-ambient, 1);
}

:where(html[data-spw-loading-ecology-salience="return"], html[data-spw-page-arrival="returning"]) {
  --spw-position-phase: recall;
  --spw-position-bias-y: calc(var(--spw-ecology-salience-shift, var(--spw-settle-offset-start, 2px)) * -1);
}

:where(html[data-spw-loading-ecology-salience="restore"], html[data-spw-page-arrival="restored"]) {
  --spw-position-phase: restore;
  --spw-position-depth: var(--depth-active, 50);
}

:where(html[data-spw-loading-ecology-salience="anchor"], html[data-spw-page-arrival="settled"]) {
  --spw-position-phase: anchor;
  --spw-position-bias-y: 0px;
  --spw-position-depth: var(--depth-settled, 10);
}

:where(html[data-spw-loading-ecology-salience="dormancy"], html[data-spw-page-presence="background"]) {
  --spw-position-phase: dormancy;
  --spw-position-depth: var(--depth-ambient, 1);
}

/* Ecology arrival bias spends through frames/surfaces via --spw-ecology-arrival-bias */
:where(html[data-spw-loading-ecology-phase]:not([data-spw-loading-ecology-phase="settled"])) {
  --spw-position-phase: var(--spw-loading-ecology-phase, approach);
}

/* ==========================================================================
   3. Lifecycle — pre-state, hydration, empty
   ========================================================================== */

:where([data-spw-hydration="loading"], [data-spw-component-state="pre"], [data-spw-lifecycle="pre"]) {
  --spw-lifecycle-phase: pre;
  --spw-pre-state-visibility: 0.82;
  --spw-pre-state-fill-mix: 0.12;
  --spw-pre-state-line-mix: 0.24;
}

:where([data-spw-hydration="ready"], [data-spw-lifecycle="ready"]) {
  --spw-lifecycle-phase: ready;
  --spw-pre-state-visibility: 0.5;
}

:where([data-spw-hydration="error"], [data-spw-lifecycle="error"]) {
  --spw-lifecycle-phase: error;
  --spw-pre-state-visibility: 0.72;
  --spw-color-layer-accent-apparent: color-mix(in srgb, var(--danger, #9d2f2f) 38%, transparent);
}

:where([data-spw-empty="true"], [data-spw-component-state="empty"], [data-spw-lifecycle="empty"]) {
  --spw-lifecycle-phase: empty;
  --spw-pre-state-visibility: 0.22;
  --spw-pre-state-fill-mix: 0.05;
  --spw-pre-state-line-mix: 0.14;
  --spw-pre-state-ink-mix: 0.52;
}

:where([data-spw-component-state="default"], [data-spw-lifecycle="default"]) {
  --spw-lifecycle-phase: default;
  --spw-pre-state-visibility: 0.34;
}

:where([data-spw-pre-state-visibility="subtle"]) {
  --spw-pre-state-visibility: 0.22;
}

:where([data-spw-pre-state-visibility="balanced"]) {
  --spw-pre-state-visibility: 0.5;
}

:where([data-spw-pre-state-visibility="apparent"]) {
  --spw-pre-state-visibility: 0.82;
}

/* ==========================================================================
   4. Theme-diverse pre-state / empty color stacks
   ========================================================================== */

:where(html[data-spw-theme-pack="neutral-paper"]) :where(
  [data-spw-empty="true"],
  [data-spw-component-state="empty"],
  [data-spw-hydration="loading"]
) {
  --spw-color-layer-fill-muted: color-mix(in srgb, var(--pigment-paper-cream, #f7f3ea) 88%, var(--line, #ddd) 12%);
  --spw-pre-state-fill-mix: calc(0.04 + (var(--spw-pre-state-visibility, 0.5) * 0.06));
}

:where(html[data-spw-theme-pack="electric-studio"]) :where(
  [data-spw-empty="true"],
  [data-spw-component-state="empty"],
  [data-spw-hydration="loading"]
) {
  --spw-color-layer-accent-subtle: color-mix(in srgb, var(--pigment-teal-electric, #0aa) 24%, transparent);
  --spw-pre-state-line-mix: calc(0.16 + (var(--spw-pre-state-visibility, 0.5) * 0.2));
}

:where(html[data-spw-theme-pack="ritual-vellum"], html[data-spw-theme-pack="oxide-ledger"]) :where(
  [data-spw-empty="true"],
  [data-spw-component-state="empty"]
) {
  --spw-pre-state-visibility: max(var(--spw-pre-state-visibility, 0.22), 0.28);
  --spw-color-layer-ink-muted: color-mix(in srgb, var(--pigment-copper-oxide, #8a4a2a) 18%, var(--ink-soft, currentColor) 82%);
}

:where(html[data-spw-color-mode="dark"]) :where(
  [data-spw-empty="true"],
  [data-spw-component-state="empty"],
  [data-spw-hydration="loading"]
) {
  --spw-pre-state-fill-mix: calc(0.06 + (var(--spw-pre-state-visibility, 0.5) * 0.08));
  --spw-color-layer-fill-muted: color-mix(in srgb, var(--pigment-charcoal-fiber, #1a2024) 92%, var(--active-op-color, #008080) 8%);
}

/* ==========================================================================
   5. Variant and content-variant selection
   ========================================================================== */

:where([data-spw-semantic-variant], [data-spw-content-variant]) {
  --spw-variant-selection-weight: 0.58;
}

:where([data-spw-genre], [data-spw-page-modes]) {
  --spw-variant-selection-weight: max(var(--spw-variant-selection-weight, 0), 0.42);
}

:where(html[data-spw-layout="reading"]) {
  --spw-real-estate-inline: var(--page-width-reading, 56rem);
}

:where(html[data-spw-layout="wide"], html[data-spw-layout="atlas"]) {
  --spw-real-estate-inline: var(--page-width-wide, 84rem);
}

:where(html[data-spw-layout="split"]) {
  --spw-real-estate-inline: min(var(--page-width-wide, 84rem), 100%);
}

:where(main, [data-spw-page-role="content"]) {
  --flow-space: var(--spw-real-estate-block);
}

:where(html[data-spw-hydration-pass="lex"]) {
  --spw-real-estate-block: calc(var(--page-stack-gap, 1rem) * 0.94);
}

:where(html[data-spw-hydration-pass="pragmatic"]) {
  --spw-real-estate-block: var(--page-stack-gap, clamp(1rem, 2.3vw, 1.7rem));
}

:where(html[data-spw-settings-momentum="pulse"]) {
  --spw-variant-selection-weight: max(var(--spw-variant-selection-weight, 0), 0.62);
  --spw-site-rhythm-tempo: min(calc(var(--spw-site-rhythm-tempo, 1) * 1.06), 3);
}

:where(html[data-spw-loading-ecology-dimensions~="variant"]) {
  --spw-variant-selection-weight: max(var(--spw-variant-selection-weight, 0), 0.72);
  --spw-variant-accent: color-mix(
    in srgb,
    var(--component-accent, var(--active-op-color, var(--teal, #008080))) 68%,
    var(--pigment-violet-ink, #5a3d8a) 32%
  );
}
}

/* /public/css/shell/layout.css */
@layer shell {
/* ==========================================================================
   layout.css
   --------------------------------------------------------------------------
   Purpose
   - Site shell, viewport framing, page scaffolding, safe-area behavior,
     generic page rhythm, header/footer/navigation contracts, and broad
     “default page” presentation for spwashi.com.
   - This file should be trustworthy even on pages with minimal markup.
   - It should provide a pleasant generic page by default, while leaving room
     for routes to bias identity later.

   Design stance
   - The shell should feel materially calm, structurally clear, and subtly
     dimensional before any route-specific CSS loads.
   - Defaults should never aggressively tint the whole site into one operator.
   - Generic pages should still feel authored: readable measure, good spacing,
     decent panels, figure treatment, and useful empty-state behavior.
   - Shell semantics should remain low-specificity enough that route files can
     override them without fighting.

   Responsibilities
   - viewport / body / safe area scaffolding
   - generic page surfaces and reading defaults
   - generic page shell defaults beneath the shared site chrome
   - global side walls / brace rails
   - main / article / section / aside / figure shell defaults
   - generic cards, panels, notes, and page intro scaffolds
   - generic responsive behavior
   ========================================================================== */

/* ==========================================================================
   1. Shell root tokens
   ========================================================================== */

:root {
  /* Widths */
  --page-width: 72rem;
  --page-width-reading: 56rem;
  --page-width-newspaper: 68rem;
  --page-width-wide: 84rem;
  --page-gutter-inline: var(--page-gutter, clamp(0.75rem, 2.5vw, 1.5rem));
  --page-gutter-block: clamp(
    calc(var(--spw-rhythm-unit, 1rem) * 0.9),
    2.2vw,
    calc(var(--spw-rhythm-unit, 1rem) * 1.8)
  );

  /* Vertical rhythm */
  --surface-gap: clamp(
    calc(var(--spw-rhythm-unit, 1rem) * 0.92),
    2vw,
    calc(var(--spw-rhythm-unit, 1rem) * 1.35)
  );
  --page-stack-gap: clamp(
    calc(var(--spw-rhythm-unit, 1rem) * 1),
    2.3vw,
    calc(var(--spw-rhythm-unit, 1rem) * 1.7)
  );
  --page-stack-gap-loose: clamp(
    calc(var(--spw-rhythm-unit, 1rem) * 1.48),
    3vw,
    calc(var(--spw-rhythm-unit, 1rem) * 2.4)
  );
  --page-section-gap: clamp(
    calc(var(--spw-rhythm-unit, 1rem) * 1.85),
    4vw,
    calc(var(--spw-rhythm-unit, 1rem) * 3.25)
  );
  --page-section-gap-tight: clamp(
    calc(var(--spw-rhythm-unit, 1rem) * 1.22),
    2.8vw,
    calc(var(--spw-rhythm-unit, 1rem) * 2)
  );

  /* Hypermedia 2D real estate aliases (see tokens/dimensions.css) */
  --spw-real-estate-inline: var(--page-width-reading, 56rem);
  --spw-real-estate-block: var(--page-stack-gap);
  --spw-real-estate-section: var(--page-section-gap);

  /* Header — alias core token so scroll chrome stays aligned sitewide */
  --shell-header-height: var(--header-height, 4rem);
  --shell-header-min-height: 0;
  --shell-header-pad-inline: clamp(0.85rem, 2vw, 1.2rem);
  --shell-header-pad-block: 0.28rem;
  --shell-header-grid-gap: 0.5rem;

  /* Nav */
  --shell-nav-min-height: max(2.5rem, var(--touch-target-min, 2.75rem));
  --shell-nav-font-size: var(--text-size-nav, 0.88rem);
  --shell-nav-padding-inline: clamp(0.72rem, 1.3vw, 0.92rem);
  --shell-nav-padding-block: 0.38rem;
  --shell-nav-gap-inline: 0.58rem;
  --shell-nav-gap-block: 0.4rem;
  --shell-nav-radius: var(--shape-control, 0.78rem);

  /* Generic surface shell */
  --shell-panel-radius: var(--shape-surface, 10px);
  --shell-panel-radius-tight: var(--shape-component, 6px);
  --shell-panel-radius-loose: var(--shape-floating, 16px);

  --shell-panel-bg:
    color-mix(in srgb, var(--surface-strong, rgba(255, 255, 255, 0.78)) 92%, transparent);
  --shell-panel-bg-soft:
    color-mix(in srgb, var(--surface, rgba(255, 255, 255, 0.62)) 90%, transparent);
  --shell-panel-bg-matte:
    color-mix(in srgb, var(--surface-matte, rgba(247, 244, 238, 0.93)) 94%, transparent);

  --shell-panel-line:
    color-mix(in srgb, var(--line, rgba(14, 18, 20, 0.14)) 96%, transparent);
  --shell-panel-line-strong:
    color-mix(in srgb, var(--active-op-border, rgba(0, 128, 128, 0.34)) 90%, transparent);

  --shell-panel-shadow:
    var(--card-highlight, inset 0 1px 0 rgba(255, 255, 255, 0.52)),
    var(--card-shadow, 0 1px 3px rgba(0, 0, 0, 0.05), 0 2px 8px rgba(0, 0, 0, 0.03));

  --shell-panel-shadow-hover:
    var(--card-highlight, inset 0 1px 0 rgba(255, 255, 255, 0.52)),
    var(--card-shadow-hover, 0 4px 18px rgba(0, 0, 0, 0.09), 0 2px 6px rgba(0, 0, 0, 0.04));

  --shell-panel-pad-inline: clamp(
    calc(var(--spw-rhythm-unit, 1rem) * 0.84),
    2vw,
    calc(var(--spw-rhythm-unit, 1rem) * 1.25)
  );
  --shell-panel-pad-block: clamp(
    calc(var(--spw-rhythm-unit, 1rem) * 0.74),
    1.7vw,
    calc(var(--spw-rhythm-unit, 1rem) * 1.1)
  );

  /* Generic reading */
  --shell-reading-measure: min(var(--measure-reading, 68ch), var(--spw-layout-measure, 72ch));
  --shell-reading-measure-tight: var(--measure-panel, 52ch);
  --shell-reading-measure-compact: var(--measure-card, 42ch);
  --shell-nav-max-width: 74rem;

  /* Generic page hero */
  --shell-hero-pad-inline: clamp(
    calc(var(--spw-rhythm-unit, 1rem) * 1),
    2.4vw,
    calc(var(--spw-rhythm-unit, 1rem) * 1.5)
  );
  --shell-hero-pad-block: clamp(
    calc(var(--spw-rhythm-unit, 1rem) * 0.96),
    2.4vw,
    calc(var(--spw-rhythm-unit, 1rem) * 1.4)
  );

  /* Footer */
  --shell-footer-min-height: 3.5rem;
  --shell-footer-font-size: var(--text-size-sm, 0.92rem);
  --shell-footer-opacity: 0.92;

  /* Main page shell */
  --spw-main-display: flex;
  --spw-main-direction: column;
  --spw-main-width: min(var(--page-width), var(--spw-layout-frame-max, var(--page-width)));
  --spw-main-gap: var(--surface-gap);
  --spw-main-padding-inline: var(--page-gutter-inline);
  --spw-main-padding-block-start: clamp(
    calc(var(--spw-rhythm-unit, 1rem) * 1.05),
    3vw,
    calc(var(--spw-rhythm-unit, 1rem) * 2.2)
  );
  --spw-main-padding-block-end: calc(
    clamp(
      calc(var(--spw-rhythm-unit, 1rem) * 2.4),
      5.5vw,
      calc(var(--spw-rhythm-unit, 1rem) * 4.2)
    )
    + env(safe-area-inset-bottom)
    + var(--spw-bottom-chrome-clearance, 0px)
  );

  /* Rails / walls */
  --shell-wall-width: 2px;
  --shell-wall-opacity: 0.72;
  --shell-wall-active-opacity: 1;

  /* Motion */
  --shell-duration-fast: var(--duration-fast, 140ms);
  --shell-duration-base: var(--duration-base, 220ms);
  --shell-duration-deliberate: var(--duration-deliberate, 360ms);

  --shell-ease: var(--ease-mechanical, ease);
  --shell-settle-ease: var(--ease-settle, ease);

  /* Z layers */
  --z-base: var(--layer-ground, 1);
  --z-surface: var(--layer-surface, 20);
  --z-floating: var(--layer-floating, 100);
  --z-header: var(--layer-header, 1000);
  --z-priority: var(--layer-priority, 2000);
}

/* ==========================================================================
   2. Body / viewport scaffolding
   ========================================================================== */

/* Shell defaults keep raw HTML routes usable before route CSS loads. */
html {
  min-height: 100%;
  --spw-scroll-target-top-clearance: calc(var(--shell-header-height) + 1rem);
  --spw-scroll-target-bottom-clearance: calc(
    env(safe-area-inset-bottom)
    + var(--spw-bottom-chrome-clearance, 0px)
    + 0.75rem
  );
  scroll-padding-top: var(--spw-scroll-target-top-clearance);
  scroll-padding-bottom: calc(
    env(safe-area-inset-bottom)
    + var(--spw-bottom-chrome-clearance, 0px)
    + 0.75rem
  );
}

:where(main > section[id], main > article[id], main [data-spw-kind][id], main [data-spw-role][id]) {
  scroll-margin-block-start: var(--spw-scroll-target-top-clearance);
  scroll-margin-block-end: var(--spw-scroll-target-bottom-clearance);
}

@media (max-width: 720px) {
  html {
    --spw-scroll-target-top-clearance: calc(var(--shell-header-height) + 0.75rem);
    --spw-scroll-target-bottom-clearance: calc(
      env(safe-area-inset-bottom)
      + var(--spw-bottom-chrome-clearance, 0px)
      + var(--touch-target-compact, 2.15rem)
      + 1rem
    );
  }
}

body {
  min-height: 100vh;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  margin: 0;
  color: var(--ink, rgba(14, 18, 20, 0.92));
  background:
    linear-gradient(180deg, var(--bg-field, var(--bg, hsl(42 77% 82%))), var(--bg, hsl(42 77% 82%)));
  text-rendering: optimizeLegibility;

  /* Ensure the body itself respects the safe area to prevent horizontal bleed */
  padding-inline: env(safe-area-inset-left) env(safe-area-inset-right);

  /* Shell-friendly defaults */
  line-height: var(--site-line-height, 1.68);
  overflow-wrap: break-word;
}

/* Density is page rhythm; components consume it rather than rename it. */
body[data-spw-shell-density="compact"] {
  --surface-gap: clamp(
    calc(var(--spw-rhythm-unit, 1rem) * 0.74),
    1.5vw,
    calc(var(--spw-rhythm-unit, 1rem) * 1)
  );
  --page-stack-gap: clamp(
    calc(var(--spw-rhythm-unit, 1rem) * 0.84),
    1.8vw,
    calc(var(--spw-rhythm-unit, 1rem) * 1.2)
  );
  --page-section-gap: clamp(
    calc(var(--spw-rhythm-unit, 1rem) * 1.28),
    2.6vw,
    calc(var(--spw-rhythm-unit, 1rem) * 2)
  );
}

body[data-spw-shell-density="roomy"] {
  --surface-gap: clamp(
    calc(var(--spw-rhythm-unit, 1rem) * 1.08),
    2.2vw,
    calc(var(--spw-rhythm-unit, 1rem) * 1.55)
  );
  --page-stack-gap: clamp(
    calc(var(--spw-rhythm-unit, 1rem) * 1.28),
    2.8vw,
    calc(var(--spw-rhythm-unit, 1rem) * 1.95)
  );
  --page-section-gap: clamp(
    calc(var(--spw-rhythm-unit, 1rem) * 2.2),
    4.4vw,
    calc(var(--spw-rhythm-unit, 1rem) * 3.8)
  );
}

/* Generic top-level flow belongs to page regions, not floating chrome. */
body > :where(header, main, footer) {
  position: relative;
}

:where(header, main, footer, [data-spw-layout]) {
  /* Debug / inspection */
  --spw-debug-layer-owner: "shell";
  --spw-debug-layer-color: #22aa66;
}

/* ==========================================================================
   3. Generic page defaults
   --------------------------------------------------------------------------
   These make an otherwise plain page look intentional before route CSS adds
   more specific identity.
   ========================================================================== */

/* main owns the page gutter; nested sections should not add a second page edge. */
main {
  /* Layout */
  display: var(--spw-main-display);
  flex-direction: var(--spw-main-direction);
  gap: var(--spw-main-gap);

  /* Box */
  width: 100%;
  max-width: var(--spw-main-width);
  padding-inline: var(--spw-main-padding-inline);
  margin:
    var(--spw-main-padding-block-start)
    auto
    var(--spw-main-padding-block-end);

  /* Interaction */
  touch-action: pan-y;

  /* Layering / containment */
  container-type: inline-size;
}

:where(main > :where(section, article, aside)) {
  box-sizing: border-box;
  min-width: 0;
  max-inline-size: 100%;
}

/* Stack rhythm stays stable while region metadata arrives after first paint. */
:where(html[data-spw-page-state="booting"], html[data-spw-page-state="interactive"]) :where(main > :where(section, article)) {
  contain: layout style;
}

:where(html[data-spw-page-state="region-enhanced"], html[data-spw-page-state="enhanced"]) :where(main > :where(section, article)) {
  contain: style;
}

/* Layout variants: body[data-spw-layout] / main[data-spw-layout] opt a route into
   different uses of horizontal space on wide screens. Reading is the default.
   "newspaper" gives denser reference pages a printable measure; "wide" lets
   key clusters breathe; "atlas" gives a rail for auxiliary content; "split" is
   reading-column + rail for reading routes with navigation context. */
:where(body[data-spw-layout="reading"]) main,
main[data-spw-layout="reading"] {
  --spw-main-width: min(var(--page-width-reading), var(--spw-layout-frame-max, var(--page-width-reading)));
}

:where(body[data-spw-layout="newspaper"]) main,
main[data-spw-layout="newspaper"] {
  --spw-main-width: min(var(--page-width-newspaper), var(--spw-layout-frame-max, var(--page-width-newspaper)));
}

:where(body[data-spw-layout="wide"]) main,
main[data-spw-layout="wide"] {
  --spw-main-width: min(var(--page-width-wide), var(--spw-layout-frame-max, var(--page-width-wide)));
}

:where(body[data-spw-layout="atlas"]) main,
main[data-spw-layout="atlas"] {
  --spw-main-width: min(var(--page-width-atlas), var(--spw-layout-frame-max, var(--page-width-atlas)));
}

@media (min-width: 92rem) {
  :where(body[data-spw-layout="wide"]) main,
  main[data-spw-layout="wide"] {
    --spw-main-width: min(92rem, calc(100vw - (var(--page-gutter-inline) * 2)));
  }

  :where(body[data-spw-layout="split"]) main,
  main[data-spw-layout="split"],
  :where(body[data-spw-layout="atlas"]) main,
  main[data-spw-layout="atlas"] {
    --spw-main-width: min(var(--page-width-atlas), calc(100vw - (var(--page-gutter-inline) * 2)));
  }
}

/* Split layouts place a narrower reading column next to a rail for
   related-routes, quick-jumps, or locally-collected items. */
@media (min-width: 72rem) {
  /* Split is the shell-owned reading-column + rail contract. */
  :where(body[data-spw-layout="split"]) main,
  main[data-spw-layout="split"] {
    --spw-main-width: var(--page-width-wide);
    display: grid;
    grid-template-columns: minmax(0, 1fr) var(--attention-rail-width);
    column-gap: var(--attention-rail-gap);
    align-items: start;
  }

  :where(body[data-spw-layout="split"]) main > :not(.spw-gutter-rail),
  main[data-spw-layout="split"] > :not(.spw-gutter-rail) {
    grid-column: 1;
    min-width: 0;
  }

  :where(body[data-spw-layout="split"]) main > .spw-gutter-rail,
  main[data-spw-layout="split"] > .spw-gutter-rail {
    grid-column: 2;
    grid-row: 1 / span 99;
    position: sticky;
    top: calc(var(--header-height) + 1rem);
    align-self: start;
    max-height: calc(100dvh - var(--header-height) - 2rem);
    overflow-y: auto;
  }
}

@media (min-width: 72rem) and (max-width: 82rem) {
  :where(body[data-spw-layout="split"]) main,
  main[data-spw-layout="split"] {
    grid-template-columns: minmax(0, 1fr) minmax(12.5rem, max-content);
    column-gap: clamp(0.75rem, 1.4vw, 1rem);
  }
}

@media (min-width: 56rem) and (max-width: 72rem) {
  :where(body[data-spw-density="compact"]) main :where(.frame-grid--3up) {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

/* Gutter rail: auxiliary content that lives beside reading on wide screens
   and collapses into the document flow on narrow ones. */
.spw-gutter-rail {
  display: flex;
  flex-direction: column;
  gap: var(--gap-surface);
  font-size: var(--text-size-sm);
  color: var(--ink-soft, rgba(14, 18, 20, 0.68));
}

@media (max-width: 72rem) {
  .spw-gutter-rail {
    order: 99;
    border-top: 1px solid var(--line, rgba(0, 128, 128, 0.18));
    padding-top: var(--gap-surface);
  }
}

main > article {
  display: flex;
  flex-direction: column;
  gap: var(--page-section-gap);
  touch-action: pan-y;
}

/* Gap handles section separation; prevent typography flow from double-spacing */
main > article > * {
  margin-block-start: 0;
}

main > :where(section, aside, nav, article, figure) + :where(section, aside, nav, article, figure) {
  margin-top: 0;
}

:where(main > article > *, main > section > *, main > aside > *) {
  min-width: 0;
}

main :where(section, aside, figure) {
  min-width: 0;
}

main :where(section, aside) {
  display: flex;
  flex-direction: column;
  gap: var(--surface-gap);
}

main :where(article > h1:first-child, section > h1:first-child) {
  margin-bottom: 0.25rem;
}

main :where(article > p, section > p, aside > p, li, blockquote, figcaption) {
  max-width: var(--shell-reading-measure);
}

main :where(article > ul, article > ol, section > ul, section > ol) {
  max-width: var(--shell-reading-measure-tight);
}

/* Generic page hero / intro */
.page-intro,
.page-hero,
.shell-hero,
.site-hero {
  position: relative;
  display: grid;
  gap: clamp(0.85rem, 1.8vw, 1.2rem);
  padding: var(--shell-hero-pad-block) var(--shell-hero-pad-inline);
  border: 1px solid var(--shell-panel-line);
  border-radius: var(--shell-panel-radius-loose);
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--active-op-color, var(--teal, #008080)) 4%, transparent),
      transparent 26%
    ),
    var(--shell-panel-bg);
  box-shadow: var(--shell-panel-shadow);
}

.page-intro > :first-child,
.page-hero > :first-child,
.shell-hero > :first-child,
.site-hero > :first-child {
  margin-top: 0;
}

.page-intro > :last-child,
.page-hero > :last-child,
.shell-hero > :last-child,
.site-hero > :last-child {
  margin-bottom: 0;
}

.page-kicker,
.hero-kicker,
.section-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  width: fit-content;
  max-width: 100%;
  min-height: 1.7rem;
  padding: 0.14rem 0.54rem;
  border: 1px solid color-mix(in srgb, var(--active-op-color, var(--teal, #008080)) 16%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface-strong, rgba(255,255,255,0.78)) 92%, transparent);
  color: var(--ink-soft, rgba(14, 18, 20, 0.68));
  font-family: var(--site-mono-font, "JetBrains Mono", monospace);
  font-size: 0.68rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.page-lede,
.hero-lede,
.shell-lede {
  color: var(--ink-soft, rgba(14, 18, 20, 0.68));
  font-size: clamp(1rem, 1.2rem + 0.2vw, 1.15rem);
  line-height: 1.72;
  max-width: min(56ch, 100%);
}

/* Generic page clusters and grids */
.page-grid,
.panel-grid,
.card-grid,
.generic-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, var(--grid-min-card, 15rem)), 1fr));
  gap: var(--surface-gap);
  min-width: 0;
}

.panel-grid--wide,
.card-grid--wide {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, var(--grid-min-panel, 17rem)), 1fr));
}

.page-cluster,
.generic-cluster,
.meta-cluster,
.action-cluster {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 0.7rem;
  align-items: center;
  min-width: 0;
}

.meta-cluster > :is(code, kbd, samp) {
  flex: 1 1 12rem;
  min-inline-size: 0;
  overflow-wrap: anywhere;
}

/* ==========================================================================
   4. Generic surface defaults for common page content
   --------------------------------------------------------------------------
   This is intentionally broad so a route with sparse markup still looks good.
   ========================================================================== */

:where(
  .page-panel,
  .generic-panel,
  .info-panel,
  .page-card,
  .generic-card,
  .reading-card,
  .note-card,
  .callout-card
) {
  position: relative;
  min-width: 0;
  padding: var(--shell-panel-pad-block) var(--shell-panel-pad-inline);
  border: 1px solid var(--shell-panel-line);
  border-radius: var(--shell-panel-radius);
  background: var(--shell-panel-bg);
  box-shadow: var(--shell-panel-shadow);
  transition:
    border-color var(--shell-duration-base) var(--shell-ease),
    box-shadow var(--shell-duration-deliberate) var(--shell-settle-ease),
    background-color var(--shell-duration-fast) var(--shell-ease),
    transform var(--shell-duration-fast) var(--shell-settle-ease);
}

:where(
  .page-panel,
  .generic-panel,
  .info-panel,
  .page-card,
  .generic-card,
  .reading-card,
  .note-card,
  .callout-card
):is(:hover, :focus-within) {
  border-color: color-mix(in srgb, var(--active-op-border, rgba(0, 128, 128, 0.34)) 88%, transparent);
  box-shadow: var(--shell-panel-shadow-hover);
}

.callout-card,
.note-card {
  border-inline-start: 0.28rem solid color-mix(in srgb, var(--active-op-color, var(--teal, #008080)) 42%, transparent);
}

.page-panel--matte,
.generic-panel--matte {
  background: var(--shell-panel-bg-matte);
}

.page-card--soft,
.generic-card--soft {
  background: var(--shell-panel-bg-soft);
}

:where(
  .page-panel,
  .generic-panel,
  .info-panel,
  .page-card,
  .generic-card,
  .reading-card,
  .note-card,
  .callout-card
) > :first-child {
  margin-top: 0;
}

:where(
  .page-panel,
  .generic-panel,
  .info-panel,
  .page-card,
  .generic-card,
  .reading-card,
  .note-card,
  .callout-card
) > :last-child {
  margin-bottom: 0;
}

/* Generic panels for figures and screenshots */
figure.page-figure,
figure.generic-figure,
.screenshot-frame,
.media-frame {
  display: grid;
  gap: 0.75rem;
  padding: var(--shell-panel-pad-block) var(--shell-panel-pad-inline);
  border: 1px solid var(--shell-panel-line);
  border-radius: var(--shell-panel-radius);
  background: var(--shell-panel-bg);
  box-shadow: var(--shell-panel-shadow);
}

:where(figure.page-figure, figure.generic-figure, .screenshot-frame, .media-frame) > img,
:where(figure.page-figure, figure.generic-figure, .screenshot-frame, .media-frame) > svg,
:where(figure.page-figure, figure.generic-figure, .screenshot-frame, .media-frame) > video,
:where(figure.page-figure, figure.generic-figure, .screenshot-frame, .media-frame) > canvas {
  display: block;
  max-width: 100%;
  height: auto;
  border-radius: calc(var(--shell-panel-radius) - 2px);
}

:where(figure.page-figure, figure.generic-figure, .screenshot-frame, .media-frame) > figcaption {
  color: var(--ink-soft, rgba(14, 18, 20, 0.68));
  font-size: 0.84rem;
  line-height: 1.55;
}

/* Generic data / list surfaces */
.data-stack,
.page-index,
.link-index,
.file-index,
.section-index {
  display: grid;
  gap: 0.6rem;
  min-width: 0;
}

.link-row,
.file-row,
.index-row,
.page-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 0.8rem;
  align-items: start;
  min-width: 0;
  padding: 0.82rem 0.95rem;
  border: 1px solid var(--shell-panel-line);
  border-radius: var(--shell-panel-radius);
  background: var(--shell-panel-bg);
  box-shadow: var(--shell-panel-shadow);
}

.index-sigil,
.row-sigil,
.file-ext {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 3.6rem;
  min-height: 2.2rem;
  padding: 0.3rem 0.55rem;
  border-radius: var(--shell-panel-radius-tight);
  background:
    linear-gradient(180deg, rgba(255,255,255,0.18), transparent 64%),
    color-mix(in srgb, var(--active-op-color, var(--teal, #008080)) 8%, transparent);
  color: color-mix(in srgb, var(--active-op-color, var(--teal, #008080)) 84%, var(--ink));
  font-family: var(--site-mono-font, "JetBrains Mono", monospace);
  font-size: 0.82rem;
  font-weight: 700;
}

/* ==========================================================================
   5. Side rails / brace walls
   --------------------------------------------------------------------------
   Keep these subtle. The old defaults were too assertive for generic pages.
   ========================================================================== */

.spw-objective-wall,
.spw-boon-wall {
  position: fixed;
  left: 0;
  top: var(--shell-header-height);
  bottom: 0;
  width: var(--shell-wall-width);
  z-index: 198;
  pointer-events: none;
  background: transparent;
  opacity: var(--shell-wall-opacity);
  box-shadow:
    inset -1px 0 0 color-mix(in srgb, var(--objective-brace-color, var(--active-op-color, var(--teal, #008080))) 18%, transparent);
  transition:
    box-shadow var(--shell-duration-deliberate) var(--shell-settle-ease),
    background-color var(--shell-duration-fast) var(--shell-ease),
    opacity var(--shell-duration-fast) var(--shell-ease);
}

.spw-subjective-wall,
.spw-bane-wall {
  position: fixed;
  right: 0;
  top: var(--shell-header-height);
  bottom: 0;
  width: var(--shell-wall-width);
  z-index: 198;
  pointer-events: none;
  background: transparent;
  opacity: var(--shell-wall-opacity);
  box-shadow:
    inset 1px 0 0 color-mix(in srgb, var(--subjective-brace-color, var(--active-op-color, var(--teal, #008080))) 18%, transparent);
  transition:
    box-shadow var(--shell-duration-deliberate) var(--shell-settle-ease),
    background-color var(--shell-duration-fast) var(--shell-ease),
    opacity var(--shell-duration-fast) var(--shell-ease);
}

/* Hide interior content from walls by default */
.spw-objective-wall-char,
.spw-boon-wall-char,
.spw-subjective-wall-char,
.spw-bane-wall-char,
.spw-objective-label,
.spw-subjective-label,
.spw-bane-label,
.spw-pivot-label,
.spw-subjective-scroll-track,
.spw-bane-scroll-track {
  display: none;
}

.spw-objective-wall[role="button"],
.spw-subjective-wall[role="button"],
.spw-boon-wall[role="button"],
.spw-bane-wall[role="button"] {
  cursor: pointer;
  pointer-events: auto;
}

.spw-objective-wall[role="button"]:hover,
.spw-boon-wall[role="button"]:hover {
  opacity: var(--shell-wall-active-opacity);
  background: color-mix(in srgb, var(--objective-brace-wash, rgba(0, 128, 128, 0.08)) 170%, transparent);
  box-shadow:
    inset -2px 0 0 color-mix(in srgb, var(--objective-brace-color, var(--active-op-color, var(--teal, #008080))) 34%, transparent);
}

.spw-subjective-wall[role="button"]:hover,
.spw-bane-wall[role="button"]:hover {
  opacity: var(--shell-wall-active-opacity);
  background: color-mix(in srgb, var(--subjective-brace-wash, rgba(160, 42, 77, 0.08)) 170%, transparent);
  box-shadow:
    inset 2px 0 0 color-mix(in srgb, var(--subjective-brace-color, var(--active-op-color, var(--teal, #008080))) 34%, transparent);
}

.spw-objective-wall[data-spw-pivot-active="true"],
.spw-boon-wall[data-spw-pivot-active="true"] {
  background: color-mix(in srgb, var(--objective-brace-wash, rgba(0, 128, 128, 0.08)) 280%, transparent);
}

.spw-subjective-wall[data-spw-pivot-active="true"],
.spw-bane-wall[data-spw-pivot-active="true"] {
  background: color-mix(in srgb, var(--subjective-brace-wash, rgba(160, 42, 77, 0.08)) 280%, transparent);
}

/* ==========================================================================
   6. Utility shell defaults for common authoring structures
   --------------------------------------------------------------------------
   These support a generic page with decent style depth even without route CSS.
   ========================================================================== */

.page-columns,
.columns-2,
.columns-3 {
  display: grid;
  gap: var(--surface-gap);
  min-width: 0;
}

.page-columns,
.columns-2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.columns-3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.page-meta,
.page-note,
.page-transition,
.inline-note,
.section-note {
  color: var(--ink-soft, rgba(14, 18, 20, 0.68));
  font-size: 0.86rem;
  line-height: 1.55;
}

.page-note,
.page-transition,
.section-note {
  padding-left: 0.95rem;
  border-left: 2px solid color-mix(in srgb, var(--line, rgba(14, 18, 20, 0.14)) 96%, transparent);
}

.page-rule,
.section-rule,
.soft-rule {
