/* ==========================================================================
   7. Responsive
   ========================================================================== */

@media (max-width: 980px) {
  .page-columns,
  .columns-2,
  .columns-3 {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 720px) {
  .page-intro,
  .page-hero,
  .shell-hero,
  .site-hero {
    padding-inline: 1rem;
  }
}

@media (max-width: 600px) {
  main {
    width: min(calc(100vw - (var(--page-gutter-inline) * 2)), var(--page-width));
  }

  :where(
    .page-panel,
    .generic-panel,
    .info-panel,
    .page-card,
    .generic-card,
    .reading-card,
    .note-card,
    .callout-card,
    figure.page-figure,
    figure.generic-figure,
    .screenshot-frame,
    .media-frame
