  }
}

@media (max-width: 480px) {
  .index-sigil,
  .row-sigil,
  .file-ext {
    min-width: 3rem;
  }

  .link-row,
  .file-row,
  .index-row,
  .page-row {
    grid-template-columns: 1fr;
  }
}

/* ==========================================================================
   8. Reduced motion / low processing defaults
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  .spw-objective-wall,
  .spw-subjective-wall,
  .spw-boon-wall,
  .spw-bane-wall,
  :where(
    .page-panel,
    .generic-panel,
    .info-panel,
    .page-card,
    .generic-card,
    .reading-card,
    .note-card,
    .callout-card,
    .link-row,
    .file-row,
    .index-row,
    .page-row
  ) {
    transition: none !important;
    animation: none !important;
    transform: none !important;
  }
}

