  accent-color: var(--active-op-color, var(--teal, #008080));
}

.spw-region-menu__subtitle {
  margin: 0.35rem 0 0.15rem;
  font-family: var(--grammar-mono-font);
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
