@keyframes doodler-hop {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-3px) rotate(5deg);
  }
}

/* ==========================================================================
   18. Accessibility
   ========================================================================== */

:where([data-spw-form], .spw-topic, [data-spw-topic], .spw-delimiter):focus-visible {
  outline: var(--grammar-focus-outline);
