:where(html[data-spw-page-settling="true"]) main > :where(.site-frame, article > .site-frame):nth-child(5) {
  transition-delay: calc(var(--spw-settle-stagger-step, 18ms) * 4 * (1 - var(--spw-layout-cascade-hold, 0)));
