:where(.frame-grid--dense, .ref-grid--dense),
:where(.frame-grid, .plans-grid, .contact-grid, .gallery-overlays, .compare-sets, .spec-grid, .directory-grid, .ref-grid)[data-spw-density="dense"] {
  --spw-grid-min-base: 17.5rem;
