  --spw-grid-min-narrow: 13.25rem;
  --spw-grid-min-compact: 11.5rem;
  --spw-grid-gap-base: 0.72rem;
  --spw-grid-gap-mid: 0.68rem;
  --spw-grid-gap-narrow: 0.62rem;
