/* ==========================================================================
   JSON hydration and skeleton projection
   ========================================================================== */

:where([data-spw-hydration="loading"]) {
  --spw-hydration-accent: var(--component-accent, var(--active-op-color, var(--teal, currentColor)));
  --spw-lifecycle-phase: pre;
  --spw-pre-state-visibility: 0.82;
  position: relative;
  min-height: 2.4rem;
  overflow: clip;
  background-color: color-mix(
    in srgb,
    var(--spw-color-layer-fill-muted, var(--component-surface-strong, var(--surface-strong)))
      calc(100% - (var(--spw-pre-state-fill-mix, 0.12) * 100%)),
    var(--spw-color-layer-accent-apparent, var(--spw-hydration-accent)) calc(var(--spw-pre-state-fill-mix, 0.12) * 100%)
  );
}

:where([data-spw-hydration="loading"])::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  opacity: calc(0.45 + (var(--spw-pre-state-visibility, 0.82) * 0.4));
  background: linear-gradient(
    100deg,
    transparent 0%,
    color-mix(in srgb, var(--spw-hydration-accent) calc(6% + (var(--spw-pre-state-visibility, 0.82) * 10%)), transparent) 42%,
    transparent 84%
  );
  background-size: 220% 100%;
  animation: spw-hydration-shimmer var(--spw-hydration-shimmer-duration, 1.1s) var(--ease-reveal, ease-in-out) infinite;
}

:where([data-spw-hydration="loading"]) :where(.spw-skeleton) {
  opacity: var(--spw-settle-opacity-mid, 0.985);
}

/* Component altitude only: html/body wear data-spw-hydration as state
   narration, and replaying the settle animation on the root fades the whole
   page every time hydration reaches ready. */
:where([data-spw-hydration="ready"]):not(html, body) {
  animation: spw-hydration-settle var(--spw-component-settle-transition, 260ms ease-out) both;
}

:where([data-spw-hydration="ready"]):where(
  [data-spw-feature],
  [data-spw-handle],
  [data-spw-kind],
  [data-spw-module]
) {
  box-shadow: var(--spw-hydration-ready-shadow, var(--spw-local-shadow, var(--component-shadow, none)));
  transition:
    box-shadow var(--spw-interaction-settle, var(--spw-component-settle-transition, 260ms ease-out)),
    filter var(--spw-interaction-settle, var(--spw-component-settle-transition, 260ms ease-out));
}

:where([data-spw-hydration="error"]) {
  position: relative;
  padding-inline-start: 1.35rem;
  color: color-mix(in srgb, var(--danger, #9d2f2f) 72%, var(--ink, currentColor));
  transition:
    color var(--component-transition-base),
    opacity var(--component-transition-base);
}

:where([data-spw-hydration="error"])::before {
  content: "!";
  position: absolute;
  inset-inline-start: 0;
  top: 0.08rem;
  width: 1rem;
  height: 1rem;
  display: grid;
  place-items: center;
  border-radius: 999px;
  font-size: 0.68rem;
  font-weight: 800;
  line-height: 1;
  color: var(--danger, #9d2f2f);
  background: color-mix(in srgb, var(--danger, #9d2f2f) 12%, transparent);
}

:where(.spw-skeleton) {
  display: block;
  border-radius: var(--component-radius-tight, 0.45rem);
  background: color-mix(in srgb, var(--component-accent, var(--ink, currentColor)) 10%, transparent);
}

:where(.spw-skeleton[data-spw-skeleton-role="heading"]) {
  width: min(72%, 18rem);
  height: 1.1rem;
}

:where(.spw-skeleton[data-spw-skeleton-role="line"]) {
  width: 100%;
  height: 0.82rem;
}

:where(.spw-skeleton[data-spw-skeleton-role="card"]) {
  width: 100%;
  min-height: 5.5rem;
}

@keyframes spw-hydration-shimmer {
  0% { background-position: 120% 0; }
  100% { background-position: -120% 0; }
}

@keyframes spw-hydration-settle {
  from {
    opacity: 0.72;
    transform: translateY(var(--spw-settle-offset-mid, 1px));
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  :where([data-spw-hydration="loading"])::after,
  :where([data-spw-hydration="ready"]) {
    animation: none;
    transform: none;
  }
}
}

