:where([data-spw-floating-chrome="true"][data-spw-chrome-role$="toast-stack"]) {
  inline-size: min(24rem, calc(100vw - 2rem));
  max-inline-size: calc(100vw - 2rem);
}

/* Improved ephemeral chrome architecture: shared ergonomics/layout tokens for resonance between state satchel, visible console, toasts, handles.
   - Common padding, font-scale, material application (glass/matte via data-spw-metamaterial on chrome elements).
   - Ergonomics: consistent min targets, baseline text, gap for actions (like utility clusters).
   - Layout: use grid/flex patterns that echo satchel (launch/panel) and console (bar/body) for predictable positioning/collapse.
   - Configurable feedback/learnability: opacity/scale can respond to data-spw-enhancement-level or feedback (subtle vs rich).
   - Snap/fluid already supported; architecture keeps feature files (console.js, state-inspector) focused on content, chrome.css on containment + resonance.
   See also shell/chrome for utility menu integration, cards for cauldron footer.
*/
:where([data-spw-floating-chrome="true"]) {
  --chrome-pad: 0.45rem;
  --chrome-font: 0.82rem;
  --chrome-gap: 0.35rem;
  font-size: var(--chrome-font);
  padding: var(--chrome-pad);
}
:where([data-spw-floating-chrome="true"][data-spw-enhancement-level="minimal"]) {
  --chrome-pad: 0.32rem;
  --chrome-font: 0.76rem;
  opacity: 0.9;
}

:root[data-spw-floating-chrome-competition="stacked"] {
  --spw-floating-lane-gap: 0.75rem;
}

:root[data-spw-floating-chrome-competition="crowded"] {
  --spw-floating-lane-gap: 0.85rem;
  --spw-floating-safe-inset: max(1.15rem, env(safe-area-inset-bottom));
}

html[data-spw-discovery-notices-active="true"] {
  --spw-floating-discovery-stack-lift: 0.75rem;
}

html[data-spw-discovery-notices-active="true"][data-spw-bottom-lane-managed="true"] :where(
  [data-spw-floating-chrome="true"][data-spw-chrome-role="discovery-toast-stack"],
  .spw-discovery-notice-stack
) {
  inset-block-end: calc(
    var(--spw-bottom-chrome-clearance, 0px)
    + var(--spw-floating-discovery-stack-lift, 0.75rem)
  );
}

html:has([data-spw-state-inspector-root][data-spw-state-inspector="open"]) :where(
  [data-spw-floating-chrome="true"][data-spw-chrome-role$="toast-stack"]
) {
  inset-block-end: calc(
    max(0.9rem, env(safe-area-inset-bottom))
    + var(--spw-bottom-chrome-clearance, 0px)
    + var(--spw-floating-menu-clearance, 0px)
  );
}

:root[data-spw-floating-chrome-bottom="occupied"] :where(
  [data-spw-floating-chrome="true"][data-spw-popup-placement="popover"]
) {
  --spw-popup-bottom-awareness: occupied;
}

:where([data-spw-floating-chrome="true"][data-spw-metamaterial]) {
  /* resonance: material from global or local for glass/matte clear contrast on ephemeral too */
}

@media (max-width: 720px) {
  :root {
    --spw-floating-slot-control: clamp(2.8rem, 12vw, 3.15rem);
    --spw-floating-quiet-opacity: 0.74;
    --spw-floating-secondary-opacity: 0.86;
  }

  :root:not([data-spw-bottom-lane-managed="true"]):has(
    .spw-section-handle[data-spw-handle-state="visible"],
    .spw-section-handle-shell[data-spw-handle-state="visible"]
  ) {
    --spw-floating-slot-satchel: var(--spw-floating-slot-parallel-nav);
  }

  :root:not([data-spw-bottom-lane-managed="true"]):has([data-spw-state-inspector-root]) {
    --spw-floating-handle-inline-start: var(--spw-floating-inline-gutter);
    --spw-floating-handle-inline-end: auto;
    --spw-floating-handle-transform: none;
    --spw-floating-handle-max-inline-size: max(9.5rem, var(--spw-floating-left-lane-max));
  }

  :root:not([data-spw-bottom-lane-managed="true"]):has([data-spw-state-inspector-root]) :where(
    .spw-section-handle[data-spw-handle-state="visible"],
    .spw-section-handle-shell[data-spw-handle-state="visible"]
  ) {
    transform: var(--spw-floating-handle-transform, none) translateY(0);
  }

  :root:not([data-spw-bottom-lane-managed="true"]):has([data-spw-state-inspector-root]) :where(
    .spw-section-handle[data-spw-handle-state="hidden"],
    .spw-section-handle-shell[data-spw-handle-state="hidden"]
  ) {
    transform: var(--spw-floating-handle-transform, none) translateY(6px);
  }

  html[data-spw-bottom-lane-managed="true"][data-spw-bottom-lane-mode="split"] :where(
    .spw-section-handle[data-spw-handle-state="visible"],
    .spw-section-handle-shell[data-spw-handle-state="visible"]
  ) {
    transform: var(--spw-floating-handle-transform, none) translateY(0);
  }

  html[data-spw-bottom-lane-managed="true"][data-spw-bottom-lane-mode="crowded"] :where(
    .spw-section-handle-shell[data-spw-handle-shell-state="collapsed"]
  ) {
    opacity: var(--spw-floating-secondary-opacity, 0.86);
  }

  html[data-spw-bottom-lane-managed="true"][data-spw-bottom-lane-mode="crowded"] .spw-nav:not(.is-open) .spw-nav-strip {
    opacity: var(--spw-floating-quiet-opacity, 0.74);
    pointer-events: none;
  }

  html[data-spw-bottom-lane-nav="open"] .spw-nav-panel:not([hidden]) {
    max-block-size: min(28rem, calc(100dvh - var(--spw-bottom-chrome-clearance, 0px) - 4.5rem));
  }

  :where([data-spw-floating-chrome="true"][data-spw-chrome-role="state-inspector"]:not([data-spw-state-inspector="open"]):not([data-spw-satchel-anchor="chrome-rail"]):not([data-spw-satchel-anchor="chrome-rail-closed"])) {
    /* Reserve the mobile section-handle rail so floating tools do not stack on one tap target. */
    inset-block-end: calc(var(--spw-floating-bottom-rail) + var(--spw-floating-menu-clearance, 0px));
  }

  :where(
    [data-spw-floating-chrome="true"][data-spw-chrome-role="state-inspector"][data-spw-satchel-anchor="chrome-rail-closed"][data-spw-state-inspector="closed"]:not([data-spw-satchel-positioned="user"])
  ) {
    position: fixed;
    inset: auto max(0.65rem, env(safe-area-inset-right)) calc(var(--spw-floating-bottom-rail) + var(--spw-floating-menu-clearance, 0px)) auto;
    left: auto !important;
    top: auto !important;
    transform: none;
    inline-size: auto;
    max-inline-size: var(--spw-floating-satchel-lane);
    justify-items: end;
    pointer-events: none;
  }

  :where(
    [data-spw-floating-chrome="true"][data-spw-chrome-role="state-inspector"][data-spw-satchel-anchor="chrome-rail-closed"][data-spw-state-inspector="closed"]:not([data-spw-satchel-positioned="user"])
  ) > * {
    pointer-events: auto;
  }

  :where([data-spw-floating-chrome="true"][data-spw-chrome-role="state-inspector"][data-spw-state-inspector="open"],
         [data-spw-floating-chrome="true"][data-spw-chrome-role="state-inspector"][data-spw-satchel-anchor="chrome-rail"]) {
    inset: auto;
    inline-size: auto;
    max-inline-size: none;
    justify-items: stretch;
  }

  :where(html:has(.site-header[data-spw-menu-mode="toggle"][data-spw-menu="open"]),
         html:has(body > header[data-spw-menu-mode="toggle"][data-spw-menu="open"])) {
    --spw-floating-menu-clearance: 4.25rem;
  }

  :where([data-spw-floating-chrome="true"][data-spw-chrome-role$="toast-stack"]) {
    inline-size: auto;
    max-inline-size: none;
  }

  :where([data-spw-floating-chrome="true"][data-spw-chrome-role="state-inspector"]) .spw-state-inspector__launch {
    min-inline-size: var(--spw-floating-slot-control);
    min-block-size: var(--spw-floating-slot-control);
    padding-inline: 0.75rem;
  }

  html[data-spw-bottom-lane-managed="true"] :where(
    [data-spw-floating-chrome="true"][data-spw-chrome-role="discovery-toast-stack"],
    .spw-discovery-notice-stack
  ) {
    inset-block-end: calc(
      var(--spw-bottom-chrome-clearance, 0px)
      + var(--spw-floating-discovery-stack-lift, 0.5rem)
    );
    inset-inline: max(var(--spw-floating-inline-gutter), env(safe-area-inset-left))
      max(var(--spw-floating-inline-gutter), env(safe-area-inset-right));
    width: auto;
  }
}

/* ==========================================================================
   RPG Wednesday / physics / page regions: snap options, fluid semantics, scroll/swipe
   competition handling for floating chrome (state satchel, toasts, etc.).
   data-spw-snap, data-spw-chrome-fluid, data-spw-gesture (already used in drag) enable
   options for snapping (corners, edges), fluid (springy vs precise), and awareness that
   drag/swipe may compete with page scroll (pointer handling in JS already marks sustained).
   Small transient toasts get tighter max-size and safe stacking.
   ========================================================================== */

:where([data-spw-floating-chrome="true"][data-spw-snap]) {
  transition:
    left var(--component-transition-deliberate),
    top var(--component-transition-deliberate),
    inset var(--component-transition-deliberate);
}

:where([data-spw-floating-chrome="true"][data-spw-snap="corners"]) {
  /* Snap affordance hint; JS or user can drive to nearest corner via data or buttons. */
}
:where([data-spw-floating-chrome="true"][data-spw-snap="edges"]) {
  /* Edge magnetic feel for fluid region navigation. */
}

:where([data-spw-floating-chrome="true"][data-spw-chrome-fluid="springy"],
       [data-spw-physics-reason*="spring"]) {
  transition-timing-function: cubic-bezier(0.2, 0.8, 0.2, 1);
}
:where([data-spw-floating-chrome="true"][data-spw-chrome-fluid="precise"],
       [data-spw-physics-reason*="precise"]) {
  transition-timing-function: cubic-bezier(0.25, 0.1, 0.25, 1);
}

/* Transient/disappearing toasts in stack: smaller footprint, auto-fade via card-ecology.css
   animation class or attr; keeps competition with scroll low (pointer-events none during fade). */
:where([data-spw-floating-chrome="true"][data-spw-chrome-tier="toast"] .spw-toast--transient,
       [data-spw-floating-chrome="true"][data-spw-chrome-tier="toast"] [data-spw-toast="transient"]) {
  max-inline-size: 18rem;
  font-size: 0.82rem;
  padding: 0.25rem 0.55rem;
}

/* ==========================================================================
   Reward collection: docked window + achievement toasts (reward-ui.js)
   - Positioning by slot; capture.css already hides all floating chrome in
     clean mode, so screenshots fed to Grok Imagine stay calm.
   - Microinteraction state lives in data-attributes; honors reduce-motion.
   ========================================================================== */
:where(.spw-reward-dock[data-spw-chrome-role="collection-dock"]) {
  position: fixed;
  inset-block-end: calc(
    var(--spw-floating-slot-bottom-base, max(0.75rem, env(safe-area-inset-bottom)))
    + var(--spw-floating-menu-clearance, 0px)
  );
  inset-inline-start: 50%;
  translate: -50% 0;
  /* Flex column-reverse so the panel sits above the trigger (opening upward
     from this bottom anchor). When spatial gravity is mounted it owns the
     direction via data-spw-open-direction from the systems layer; this is the
     correct static fallback. */
  display: flex;
  flex-direction: column-reverse;
  align-items: center;
  gap: 0.4rem;
  padding: 0;
  pointer-events: none;
  /* Content ceiling for the gravity-driven reveal: grow to measured room, but
     scroll a large collection rather than fill the column. */
  --spw-gravity-reveal-max: 24rem;
  /* Settling mindfulness: stay invisible until the page has revealed the dock. */
  opacity: 0;
  transition: opacity 240ms ease, translate 240ms ease;
}
:where(.spw-reward-dock[data-spw-reward-reveal="revealed"]) {
  opacity: 1;
}
:where(.spw-reward-dock > *) {
  pointer-events: auto;
}

:where(.spw-reward-dock-trigger) {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.3rem 0.7rem;
  border: 1px solid color-mix(in srgb, var(--active-op-color, var(--teal, #008080)) 32%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface, #fbfaf7) 86%, var(--teal, #008080) 6%);
  color: var(--ink, #1b2a2a);
  font: inherit;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
  box-shadow: 0 2px 10px rgb(0 0 0 / 0.12);
  transition: scale 140ms ease, box-shadow 140ms ease;
}
:where(.spw-reward-dock-trigger:hover) {
  scale: 1.03;
  box-shadow: 0 3px 14px rgb(0 0 0 / 0.18);
}
:where(.spw-reward-dock-glyph) {
  color: var(--active-op-color, var(--teal, #008080));
}

/* Collectible tier escalation — the chip's accent deepens as a surface reveals
   more distinct component kinds (singular → teeming). data-spw-reward-tier is
   written by reward-ui; previously it had no visual treatment. */
:where(.spw-reward-dock[data-spw-reward-tier="varied"] .spw-reward-dock-trigger) {
  border-color: color-mix(in srgb, var(--active-op-color, var(--teal, #008080)) 48%, transparent);
}
:where(.spw-reward-dock[data-spw-reward-tier="rich"] .spw-reward-dock-trigger) {
  border-color: color-mix(in srgb, var(--active-op-color, var(--teal, #008080)) 62%, transparent);
  box-shadow: 0 2px 12px color-mix(in srgb, var(--active-op-color, var(--teal, #008080)) 18%, rgb(0 0 0 / 0.12));
}
:where(.spw-reward-dock[data-spw-reward-tier="teeming"] .spw-reward-dock-trigger) {
  border-color: color-mix(in srgb, var(--active-op-color, var(--teal, #008080)) 78%, transparent);
  box-shadow:
    0 0 0 2px color-mix(in srgb, var(--active-op-color, var(--teal, #008080)) 20%, transparent),
    0 2px 14px color-mix(in srgb, var(--active-op-color, var(--teal, #008080)) 24%, rgb(0 0 0 / 0.12));
}

/* Consume the salience-graded easter-egg accent that reward-ui sets on <html>
   during a rare reveal — the chip picks up a ring whose strength follows the
   resolved salience (transparent when subtle, so it stays quiet). */
:where(html[data-spw-reward-easter-egg]) :where(.spw-reward-dock-trigger) {
  box-shadow:
    0 0 0 2px var(--spw-reward-egg-accent, transparent),
    0 3px 14px rgb(0 0 0 / 0.16);
}

/* Fresh-discovery pulse — a brief rewarded-wonder flicker. */
:where(.spw-reward-dock[data-spw-collection-fresh] .spw-reward-dock-glyph) {
  animation: spw-reward-pop 600ms ease;
}
@keyframes spw-reward-pop {
  0% { scale: 1; }
  40% { scale: 1.5; }
  100% { scale: 1; }
}

:where(.spw-reward-dock-body) {
  display: grid;
  gap: 0.45rem;
  max-inline-size: min(20rem, calc(100vw - 2rem));
  /* A large collection scrolls inside the panel instead of towering over the
     page from its bottom anchor. */
  max-block-size: min(55vh, 24rem);
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 0.6rem 0.75rem;
  border-radius: 0.7rem;
  background: color-mix(in srgb, var(--surface, #fbfaf7) 92%, transparent);
  backdrop-filter: blur(8px);
  border: 1px solid color-mix(in srgb, var(--ink, #1b2a2a) 12%, transparent);
  box-shadow: 0 6px 22px rgb(0 0 0 / 0.16);
}

/* Redundancy handling / region collapsing: when the floating field is crowded
   or this dock overlaps other chrome, syncFloatingChromeState() marks it
   pressured and it collapses to just its chip, yielding space. The chip
   compresses as it yields — material physics, not a hard cut. */
:where(.spw-reward-dock[data-spw-chrome-collapse="pressured"] .spw-reward-dock-body) {
  display: none;
}
:where(.spw-reward-dock[data-spw-chrome-collapse="pressured"] .spw-reward-dock-trigger) {
  scale: 0.94;
  opacity: 0.82;
}
:where(.spw-reward-summary) {
  margin: 0;
  font-weight: 600;
  color: var(--ink, #1b2a2a);
}
:where(.spw-reward-kinds) {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
}
:where(.spw-reward-kind) {
  padding: 0.1rem 0.45rem;
  border-radius: 999px;
  font-size: 0.74rem;
  /* Chips are single tokens; never let ambient layout squeeze them into
     letter-stacks. */
  white-space: nowrap;
  background: color-mix(in srgb, var(--op-topic-color, var(--teal, #008080)) 14%, transparent);
  color: var(--ink, #1b2a2a);
}
:where(.spw-reward-kind.is-empty) {
  background: transparent;
  color: var(--ink-soft, #5a6a6a);
  font-style: italic;
}
:where(.spw-reward-badges) {
  display: grid;
  gap: 0.2rem;
  margin: 0;
  padding: 0;
  list-style: none;
}
:where(.spw-reward-badge) {
  font-size: 0.78rem;
  color: var(--ink-soft, #5a6a6a);
}
:where(.spw-reward-badge[data-spw-earned="true"]) {
  color: var(--active-op-color, var(--teal, #008080));
  font-weight: 600;
}
:where(.spw-reward-actions) {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  justify-content: flex-start;
}
:where(.spw-reward-actions .spw-reward-reset) {
  font-size: 0.76rem;
  padding-block: 0.2rem;
}

/* Achievement toast stack */
:where(.spw-reward-toasts[data-spw-chrome-role="collection-toast-stack"]) {
  position: fixed;
  inset-block-start: calc(max(0.9rem, env(safe-area-inset-top)) + var(--spw-header-clearance, 3.5rem));
  inset-inline-end: max(0.9rem, env(safe-area-inset-right));
  display: grid;
  gap: 0.4rem;
  padding: 0;
  pointer-events: none;
}
:where(.spw-reward-toast) {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.45rem 0.7rem;
  border-radius: 0.6rem;
  background: color-mix(in srgb, var(--surface, #fbfaf7) 90%, var(--active-op-color, var(--teal, #008080)) 8%);
  border: 1px solid color-mix(in srgb, var(--active-op-color, var(--teal, #008080)) 30%, transparent);
  box-shadow: 0 4px 16px rgb(0 0 0 / 0.18);
  color: var(--ink, #1b2a2a);
  /* Microinteraction: enter from the right, leave upward. */
  opacity: 0;
  translate: 0.6rem 0;
  transition: opacity 300ms ease, translate 300ms ease;
}
:where(.spw-reward-toast[data-spw-state="settled"]) {
  opacity: 1;
  translate: 0 0;
}
:where(.spw-reward-toast[data-spw-state="leave"]) {
  opacity: 0;
  translate: 0 -0.5rem;
}
:where(.spw-reward-toast-glyph) {
  color: var(--active-op-color, var(--teal, #008080));
}
/* Rare-tier unlock gets a touch more presence (easter-egg seam). */
:where(.spw-reward-toast[data-spw-reward-easter-egg="rare"]) {
  border-color: color-mix(in srgb, var(--op-probe-color, #7a4fb5) 50%, transparent);
  box-shadow: 0 4px 20px color-mix(in srgb, var(--op-probe-color, #7a4fb5) 30%, rgb(0 0 0 / 0.18));
}

/* Salience mechanics — how loudly a reward announces itself. Resolved at runtime
   from page zone + rarity + the reader's attentional arc (reward-ui.js). */
:where(.spw-reward-toast[data-spw-reward-salience="subtle"]) {
  opacity: 0.9;
  box-shadow: 0 2px 8px rgb(0 0 0 / 0.12);
}
:where(.spw-reward-toast[data-spw-reward-salience="subtle"] .spw-reward-toast-glyph) {
  opacity: 0.7;
}
:where(.spw-reward-toast[data-spw-reward-salience="vivid"]) {
  box-shadow:
    0 6px 22px color-mix(in srgb, var(--active-op-color, var(--teal, #008080)) 26%, rgb(0 0 0 / 0.2)),
    0 0 0 3px color-mix(in srgb, var(--active-op-color, var(--teal, #008080)) 14%, transparent);
}
:where(.spw-reward-toast[data-spw-reward-salience="vivid"] .spw-reward-toast-glyph) {
  animation: spw-reward-pop 700ms ease;
}

/* Page-level settling reveal: a rare unlock tints the document; vivid salience
   lets the reader's dwell surface a fuller easter-egg accent. */
:where(html[data-spw-reward-easter-egg][data-spw-reward-salience="vivid"]) {
  --spw-reward-egg-accent: color-mix(in srgb, var(--op-probe-color, #7a4fb5) 20%, transparent);
}
:where(html[data-spw-reward-easter-egg][data-spw-reward-salience="notable"]) {
  --spw-reward-egg-accent: color-mix(in srgb, var(--op-probe-color, #7a4fb5) 10%, transparent);
}
:where(html[data-spw-reward-easter-egg][data-spw-reward-salience="subtle"]) {
  --spw-reward-egg-accent: transparent;
}

@media (prefers-reduced-motion: reduce) {
  :where(.spw-reward-dock, .spw-reward-toast, .spw-reward-dock-trigger) {
    transition: none;
  }
  :where(.spw-reward-dock[data-spw-collection-fresh] .spw-reward-dock-glyph) {
    animation: none;
  }
}
:where(html[data-spw-reduce-motion="on"]) :where(.spw-reward-dock, .spw-reward-toast) {
  transition: none;
}
}

/* /public/css/components/runtime-states.css */
@layer components {
/* ==========================================================================
   components/runtime-states.css
   --------------------------------------------------------------------------
   Selection, active, accessibility, visibility, and responsive component states.
   ========================================================================== */

/* ==========================================================================
   25. Selection, active, and section states
   ========================================================================== */

:where(main > section[id], main > article > section[id]) {
  scroll-margin-top: calc(var(--shell-header-height, var(--header-height, 4rem)) + 1.1rem);
}

:where([data-spw-deep-link]) {
  scroll-margin-top: calc(var(--shell-header-height, var(--header-height, 4rem)) + 1.25rem);
}

:where([data-spw-deep-link]:target) {
  outline: 2px solid color-mix(in srgb, var(--component-accent, var(--active-op-color, var(--teal))) 38%, transparent);
  outline-offset: 0.32rem;
}

:where([data-spw-deep-link]) > :where(.frame-topline, .frame-heading) :where(.frame-sigil[href^="#"]) {
  text-decoration-thickness: 0.08em;
  text-underline-offset: 0.24em;
}

:where([data-spw-deep-link]:hover, [data-spw-deep-link]:focus-within) > :where(.frame-topline, .frame-heading) :where(.frame-sigil[href^="#"]) {
  text-decoration-line: underline;
}

/* Page and section transitions spend semantic hierarchy before decorative motion:
   active content gets resonance, adjacent content keeps inertia, and floating
   navigation surfaces answer faster than reading surfaces. */
:where(html[data-spw-page-transition-phase="entering"], html[data-spw-page-transition-phase="returning"], html[data-spw-page-transition-phase="restored"]) {
  --spw-transition-hierarchy-resonance: 0.16;
  --spw-transition-hierarchy-shadow:
    0 0 0 1px color-mix(in srgb, var(--component-accent, var(--active-op-color, var(--teal, #008080))) 8%, transparent),
    var(--spw-local-shadow, var(--component-shadow, none));
}

:where(html[data-spw-page-arrival="returning"], html[data-spw-page-arrival="restored"]) {
  --spw-transition-hierarchy-resonance: 0.24;
}

:where(html[data-spw-page-section-direction="forward"]) {
  --spw-section-inertia-shift: var(--spw-settle-offset-end, 0.25px);
}

:where(html[data-spw-page-section-direction="back"]) {
  --spw-section-inertia-shift: calc(var(--spw-settle-offset-end, 0.25px) * -1);
}

:where([data-spw-section-state]) {
  --spw-section-local-resonance: 0;
  transition:
    border-color var(--spw-interaction-commit, var(--component-transition-base)),
    box-shadow var(--spw-interaction-settle, var(--component-transition-base)),
    filter var(--spw-interaction-settle, var(--component-transition-base)),
    opacity var(--spw-interaction-settle, var(--component-transition-base)),
    transform var(--spw-interaction-settle, var(--component-transition-base));
}

:where([data-spw-section-state="active"]) {
  --spw-section-local-resonance: var(--spw-transition-hierarchy-resonance, 0.12);
  box-shadow: var(--spw-transition-hierarchy-shadow, var(--spw-local-shadow, var(--component-shadow, none)));
  transform: translateY(calc(var(--spw-section-inertia-shift, 0px) * -1));
}

:where([data-spw-section-state="previous"], [data-spw-section-state="next"]) {
  --spw-section-local-resonance: calc(var(--spw-transition-hierarchy-resonance, 0.12) * 0.42);
  filter: saturate(calc(1 + var(--spw-section-local-resonance, 0) * 0.12));
}

:where(
  [data-spw-floating-chrome="true"],
  .spw-section-handle,
  .spw-section-handle-shell,
  .spw-nav,
  .spw-console
) {
  --spw-transition-surface-physics: var(--spw-interaction-acknowledge, var(--component-transition-base));
  transition:
    box-shadow var(--spw-interaction-settle, var(--component-transition-base)),
    opacity var(--spw-transition-surface-physics),
    transform var(--spw-transition-surface-physics);
}

:where(html[data-spw-page-section-phase="traveling"]) :where(.spw-section-handle, .spw-section-handle-shell) {
  --spw-transition-surface-physics: var(--spw-interaction-acknowledge, var(--touch-acknowledge, 90ms) var(--ease-chassis, ease));
}

:where([data-spw-module-trigger]) {
  --spw-module-trigger-color: var(--component-accent, var(--active-op-color, var(--teal)));
}

:where(html[data-spw-module-visuals="on"], html[data-spw-debug-mode="on"]) :where([data-spw-module-trigger]) {
  position: relative;
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--spw-module-trigger-color) 12%, transparent),
    var(--component-shadow, none);
}

:where(html[data-spw-module-visuals="on"]:not([data-spw-debug-mode="on"])) :where([data-spw-module-trigger]) > :where(.frame-topline, .frame-heading)::after {
  content: none;
}

:where(html[data-spw-module-visuals="on"], html[data-spw-debug-mode="on"]) :where([data-spw-module-trigger]) > :where(.frame-topline, .frame-heading)::after {
  content: "mount trigger";
  display: inline-flex;
  max-inline-size: min(32ch, 100%);
  overflow: hidden;
  margin-inline-start: auto;
  padding: 0.18rem 0.44rem;
  border: 1px solid color-mix(in srgb, var(--spw-module-trigger-color) 28%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface-strong, #fff) 92%, var(--spw-module-trigger-color) 8%);
  color: color-mix(in srgb, var(--ink, #111) 84%, var(--spw-module-trigger-color) 16%);
  font-family: var(--site-mono-font, monospace);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  line-height: 1.2;
  pointer-events: none;
  text-overflow: ellipsis;
  white-space: nowrap;
}

:where(html[data-spw-module-visuals="on"], html[data-spw-debug-mode="on"]) :where([data-spw-module-trigger-status="queued"], [data-spw-module-trigger-status="waiting"]) > :where(.frame-topline, .frame-heading)::after {
  opacity: 0.72;
}

/* Feature partial presence — learnable islands when orchestration is visible.
   Outline only (no layout shift). Session feature-lab mutes use the same rail. */
:where(html[data-spw-module-visuals="on"]) :where([data-spw-feature]) {
  --spw-feature-island-ring:
    0 0 0 1px color-mix(in srgb, var(--op-topic-color, #2f6f5e) 28%, transparent);
  box-shadow: var(--spw-feature-island-ring), var(--spw-local-shadow, var(--component-shadow, none));
  transition:
    box-shadow var(--duration-base, 220ms) var(--ease-smooth, ease),
    opacity var(--duration-base, 220ms) var(--ease-smooth, ease);
}

:where(html[data-spw-module-visuals="on"]) :where([data-spw-feature][data-spw-feature-encounter]) {
  --spw-feature-island-ring:
    0 0 0 1px color-mix(in srgb, var(--active-op-color, #008080) 38%, transparent),
    0 0 12px color-mix(in srgb, var(--active-op-color, #008080) 10%, transparent);
}

/* Session feature lab: show that body features were rewritten this visit.
   Prefer html::after so we do not fight body::after grain/debug overlays. */
:where(body[data-spw-feature-lab="session"]) {
  --spw-feature-lab-cue: 1;
}

:where(html[data-spw-module-visuals="on"]:has(body[data-spw-feature-lab="session"]))::after {
  content: "feature lab active";
  position: fixed;
  inset-block-end: 0.65rem;
  inset-inline-end: 0.65rem;
  z-index: 40;
  max-inline-size: min(28ch, calc(100vw - 1.5rem));
  padding: 0.35rem 0.55rem;
  border: 1px solid color-mix(in srgb, var(--op-probe-color, #7a4fb5) 36%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface-strong, #fff) 92%, var(--op-probe-color, #7a4fb5) 8%);
  color: color-mix(in srgb, var(--ink, #111) 82%, var(--op-probe-color, #7a4fb5) 18%);
  font-family: var(--site-mono-font, monospace);
  font-size: 0.68rem;
  letter-spacing: 0.03em;
  pointer-events: none;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.08);
}

/* Mount pulse: brief learnable flash when a module writes effect tokens. */
:where(html[data-spw-module-visuals="on"][data-spw-module-effect-pulse]) {
  --spw-module-effect-pulse-ring:
    inset 0 0 0 2px color-mix(in srgb, var(--op-action-color, #006666) 22%, transparent);
  outline: 2px solid color-mix(in srgb, var(--op-action-color, #006666) 28%, transparent);
  outline-offset: -2px;
  transition: outline-color 320ms var(--ease-smooth, ease);
}

/* Ecology phase label for inspect postures — teaches reflow as a sequence.
   html::before keeps body free for grain texture. */
:where(
  html[data-spw-module-visuals="on"][data-spw-loading-ecology-phase]:not([data-spw-loading-ecology-phase="settled"])
)::before {
  content: "load · " attr(data-spw-loading-ecology-phase);
  position: fixed;
  inset-block-start: 0.55rem;
  inset-inline-start: 0.55rem;
  z-index: 40;
  padding: 0.3rem 0.5rem;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--op-action-color, #006666) 30%, transparent);
  background: color-mix(in srgb, var(--surface-strong, #fff) 90%, var(--op-action-color, #006666) 10%);
  color: color-mix(in srgb, var(--ink, #111) 80%, var(--op-action-color, #006666) 20%);
  font-family: var(--site-mono-font, monospace);
  font-size: 0.66rem;
  letter-spacing: 0.04em;
  text-transform: lowercase;
  pointer-events: none;
}


/* ==========================================================================
   Reading-quiet inspect overlays (public routes, non-debug)
   --------------------------------------------------------------------------
   Suppress slot anatomy and passive module-visual rails on editorial surfaces.
   Settings, website, and plans lab routes stay fully inspectable. Show mounts
   (module-visuals) still applies box-model rails when explicitly toggled on.
   ========================================================================== */

html:not([data-spw-debug-mode="on"]):not([data-spw-cognitive-handles="on"]) body:not(
