}

.spw-state-inspector {
  --state-inspector-accent: var(--op-probe-color, #4a2180);
  color: var(--ink, #111);
  font-family: var(--site-mono-font, monospace);
}

.spw-state-inspector__launch[data-spw-page-state-mirror] {
  position: relative;
}

.spw-state-inspector__launch[data-spw-page-state-mirror]::before {
  content: attr(data-spw-page-state-mirror);
  position: absolute;
  inset: auto 0 calc(100% + 0.22rem) auto;
  max-inline-size: min(16rem, 70vw);
  padding: 0.14rem 0.38rem;
  border: 1px solid color-mix(in srgb, var(--state-inspector-accent) 18%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface-strong, #fff) 92%, var(--state-inspector-accent) 8%);
  color: color-mix(in srgb, var(--ink-soft, rgba(14, 18, 20, 0.72)) 86%, var(--state-inspector-accent) 14%);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  opacity: 0;
  transform: translateY(4px);
  pointer-events: none;
  transition:
    opacity var(--duration-fast, 120ms) ease,
    transform var(--duration-fast, 120ms) ease;
}

html[data-spw-page-state="region-enhanced"] .spw-state-inspector__launch[data-spw-page-state-mirror]::before,
html[data-spw-page-state="enhanced"] .spw-state-inspector__launch[data-spw-page-state-mirror]::before,
.spw-state-inspector__launch[data-spw-page-state-mirror]:is(:hover, :focus-visible)::before {
  opacity: 1;
  transform: translateY(0);
}

.spw-state-inspector__launch {
  min-block-size: 2.2rem;
  padding: 0.38rem 0.68rem;
  border: 1px solid color-mix(in srgb, var(--state-inspector-accent) 24%, transparent);
  border-radius: var(--shape-control, 0.78rem);
  background:
    radial-gradient(circle at 12% 20%, color-mix(in srgb, var(--state-inspector-accent) 18%, transparent), transparent 32%),
    color-mix(in srgb, var(--surface-strong, #fff) 94%, var(--state-inspector-accent) 6%);
  box-shadow:
    0 0.7rem 1.8rem color-mix(in srgb, var(--shadow-color, #111111) 18%, transparent),
    inset 0 1px 0 color-mix(in srgb, white 16%, transparent);
  color: color-mix(in srgb, var(--ink, #111) 78%, var(--state-inspector-accent) 22%);
  cursor: pointer;
  font: inherit;
  font-size: 0.74rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  touch-action: none; /* helps with drag vs scroll */
  user-select: none;
}

.spw-state-inspector__launch:active,
.spw-state-inspector__launch[data-spw-dragging="true"],
.spw-state-inspector__launch[data-spw-drag-state="dragging"] {
  cursor: grabbing;
  transition: none !important;
  box-shadow: var(--floating-shadow, 0 8px 32px rgba(0, 0, 0, 0.12)), 0 0 0 1px color-mix(in srgb, var(--state-inspector-accent) 35%, transparent);
  will-change: left, top;
}

.spw-state-inspector__launch:active:not([data-spw-drag-state="dragging"]) {
  transform: translateY(var(--spw-control-press-depth, 1px)) scale(var(--spw-micro-press-scale, 0.998));
}

.spw-state-inspector__launch[data-spw-drag-state="dragging"] {
