  color: var(--ink-soft, rgba(14, 18, 20, 0.72));
  font-size: 0.72rem;
  line-height: 1.45;
}

.spw-state-inspector__actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.38rem;
}

.spw-state-inspector__position-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.32rem;
}

.spw-state-inspector__position-actions .operator-chip {
