    inset-block-start: auto;
    top: auto !important;
    left: max(0.65rem, env(safe-area-inset-left)) !important;
    right: max(0.65rem, env(safe-area-inset-right)) !important;
    inline-size: auto;
    max-block-size: min(68dvh, calc(100dvh - var(--spw-shell-menu-offset, 4rem) - 5.5rem));
    display: flex;
    flex-direction: column-reverse;
    align-items: stretch;
    gap: 0.45rem;
    z-index: var(--z-drawer, calc(var(--z-priority, 2000) + 20));
    pointer-events: none;
  }

  .spw-state-inspector[data-spw-state-inspector="open"] > *,
  .spw-state-inspector[data-spw-state-inspector="open"][data-spw-satchel-anchor="chrome-rail"] > * {
    pointer-events: auto;
  }

  .spw-state-inspector[data-spw-state-inspector="open"] .spw-state-inspector__panel,
  .spw-state-inspector[data-spw-state-inspector="open"][data-spw-satchel-anchor="chrome-rail"] .spw-state-inspector__panel {
    max-block-size: min(58dvh, calc(100dvh - var(--spw-shell-menu-offset, 4rem) - 8.5rem));
    margin-block-end: 0;
  }

  .spw-state-inspector[data-spw-state-inspector="closed"]:not([data-spw-satchel-positioned="user"]) .spw-state-inspector__launch {
    min-block-size: var(--touch-target-compact, 2.25rem);
    max-inline-size: min(8.8rem, calc(50vw - 0.7rem));
    padding: 0.28rem 0.56rem;
    border-radius: 999px;
    box-shadow:
      0 0.45rem 1.1rem color-mix(in srgb, var(--shadow-color, #111111) 18%, transparent),
      inset 0 1px 0 color-mix(in srgb, white 12%, transparent);
    font-size: 0.66rem;
    letter-spacing: 0;
    opacity: var(--spw-floating-secondary-opacity, 0.86);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .spw-state-inspector[data-spw-state-inspector="closed"]:not([data-spw-satchel-positioned="user"]) .spw-state-inspector__launch:is(:hover, :focus-visible) {
    opacity: 1;
  }

  :root:has([data-spw-state-inspector-root]) .spw-state-inspector__launch[data-spw-page-state-mirror]::before {
    inset-inline-end: 0;
    max-inline-size: var(--spw-floating-satchel-lane, min(11.5rem, calc(50vw - 0.8rem)));
  }
}

:where(main > section.site-frame[data-spw-section-state], main > article > section.site-frame[data-spw-section-state]) {
  transition:
    box-shadow var(--spw-layout-measure-settle, var(--component-transition-deliberate)),
    border-color var(--spw-component-settle-transition, var(--component-transition-deliberate)),
    transform var(--spw-component-settle-transition, var(--component-transition-deliberate)),
    opacity var(--component-transition-arrival);
}

:where(main > section.site-frame[data-spw-section-state="active"], main > article > section.site-frame[data-spw-section-state="active"]) {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--component-accent) 12%, transparent),
  var(--component-shadow-active);
}

:where(main > section.site-frame[data-spw-section-state="active"], main > article > section.site-frame[data-spw-section-state="active"]) :where(h1, h2, h3) {
  color: color-mix(in srgb, var(--ink, currentColor) 90%, var(--component-accent) 10%);
}

:where(html[data-spw-scroll-cadence="on"]) {
  & main > :is(section.site-frame, article > section.site-frame)[data-spw-section-state] {
    position: relative;
    overflow: clip;
  }

  & main > :is(section.site-frame, article > section.site-frame)[data-spw-section-state]::before {
    content: "";
    position: absolute;
    inset-block: 1rem;
    inset-inline-start: 0.55rem;
    width: 0.16rem;
    border-radius: 999px;
    background: color-mix(in oklab, var(--component-accent) 46%, transparent);
    opacity: 0;
    transform: scaleY(0.24);
    transform-origin: center top;
    transition:
      opacity var(--component-transition-deliberate),
      transform var(--component-transition-deliberate);
    pointer-events: none;
  }

  & main > :is(section.site-frame, article > section.site-frame)[data-spw-section-state]::after {
    content: "";
    position: absolute;
    inset: 0;
    background: color-mix(in oklab, var(--component-accent) 2.5%, transparent);
    opacity: 0;
    transition: opacity var(--component-transition-deliberate);
    pointer-events: none;
  }

  & main > :is(section.site-frame, article > section.site-frame):is(
    [data-spw-section-state="previous"],
    [data-spw-section-state="next"]
  )::before {
    opacity: 0.24;
    transform: scaleY(0.56);
  }

  & main > :is(section.site-frame, article > section.site-frame)[data-spw-section-state="active"] {
    border-color: color-mix(in oklab, var(--component-accent) 18%, transparent);
    box-shadow:
      inset 0 0 0 1px color-mix(in oklab, var(--component-accent) 10%, transparent),
      0 0.55rem 1.4rem color-mix(in oklab, var(--component-accent) 5%, transparent),
      var(--component-shadow-active);
  }

  & main > :is(section.site-frame, article > section.site-frame)[data-spw-section-state="active"]::before {
    opacity: 0.58;
    transform: scaleY(1);
  }

  & main > :is(section.site-frame, article > section.site-frame)[data-spw-section-state="active"]::after {
    opacity: 1;
  }

  & main > :is(section.site-frame, article > section.site-frame)[data-spw-section-state="active"]
    :where(.frame-sigil, h1, h2, h3, .inline-note, .frame-note) {
    transition:
      transform var(--component-transition-deliberate),
      color var(--component-transition-deliberate),
      opacity var(--component-transition-deliberate);
  }

  & main > :is(section.site-frame, article > section.site-frame)[data-spw-section-state="active"]
    :where(.frame-sigil, h1, h2, h3) {
    transform: translateX(0.08rem);
  }

  & main > :is(section.site-frame, article > section.site-frame):is(
    [data-spw-section-state="previous"],
    [data-spw-section-state="next"]
  ) :where(.inline-note, .frame-note) {
    opacity: 0.94;
  }
}

@media (prefers-reduced-motion: reduce) {
  :where(html[data-spw-scroll-cadence="on"] main > :is(section.site-frame, article > section.site-frame)[data-spw-section-state])::before,
  :where(html[data-spw-scroll-cadence="on"] main > :is(section.site-frame, article > section.site-frame)[data-spw-section-state="active"]) :where(.frame-sigil, h1, h2, h3, .inline-note, .frame-note) {
    transition: none;
    transform: none;
  }
}

:where([data-spw-selection]) {
  transition:
    background-color var(--spw-component-settle-transition, var(--component-transition-base)),
    border-color var(--spw-component-settle-transition, var(--component-transition-base)),
    box-shadow var(--spw-component-settle-transition, var(--component-transition-base)),
    opacity var(--component-transition-arrival),
    transform var(--component-transition-arrival);
}

:where([data-spw-selection="focused"]) {
  background-color: color-mix(in srgb, var(--component-accent) 3%, transparent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--component-accent) 16%, transparent);
}

:where([data-spw-selection="active"]) {
  background-color: color-mix(in srgb, var(--component-accent) 4%, transparent);
  border-color: color-mix(in srgb, var(--component-accent) 34%, transparent);
}

:where([data-spw-selection="selected"]) {
  border-color: color-mix(in srgb, var(--component-accent) 42%, transparent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--component-accent) 22%, transparent),
  0 0 0 4px color-mix(in srgb, var(--component-accent) 7%, transparent);
}

/* Coalesce parallel module mounts: hold cascade tokens steady until the batch settles. */
:where(html[data-spw-runtime-mount-batch="active"]) {
  --spw-runtime-enhancement-intensity: 0.32;
  --spw-runtime-feature-intensity: 0.22;
  --spw-site-rhythm-tempo: 0.72;
  --spw-layout-cascade-hold: 1;
  --spw-region-profile-intensity: min(var(--spw-region-profile-intensity, 1), 0.28);
}

:where(html:not([data-spw-runtime-mount-batch="active"])) {
  transition:
    --spw-runtime-enhancement-intensity var(--duration-base, 200ms) ease,
    --spw-runtime-feature-intensity var(--duration-base, 200ms) ease,
    --spw-site-rhythm-tempo var(--duration-base, 200ms) ease,
    --spw-site-rhythm-density var(--duration-base, 200ms) ease,
    --spw-region-profile-intensity var(--spw-region-profile-refresh-duration, 220ms) var(--ease-settle, ease);
}

/* Page lifecycle cascade — region metadata enrichment is deferred until interactive. */
:where(html[data-spw-page-state="booting"], html[data-spw-page-state="interactive"]) {
  --spw-layout-cascade-hold: 1;
  --spw-region-profile-intensity: 0;
}

:where(html[data-spw-page-state="hydrated"]) {
  --spw-region-profile-intensity: 0.48;
}

:where(html[data-spw-page-state="region-enhanced"], html[data-spw-page-state="enhanced"]) {
  --spw-region-profile-intensity: 1;
}

:where(html[data-spw-page-state="region-enhanced"], html[data-spw-page-state="enhanced"]) :where(
  [data-spw-feature],
  [data-spw-handle],
  [data-spw-kind]:not(body):not(main),
  [data-spw-module]
) {
  --spw-hydration-ready-shadow:
    0 0 0 1px color-mix(in srgb, var(--component-accent, var(--active-op-color, var(--teal, #008080))) 12%, transparent),
    var(--spw-local-shadow, var(--component-shadow, none));
}

/* During cascade hold, limit transitions to paint-safe properties so runtime
   dataset writes do not trigger layout-affecting interpolation. */
:where(
  html[data-spw-runtime-mount-batch="active"],
  html[data-spw-page-state="booting"],
  html[data-spw-page-state="interactive"]
) {
  --spw-component-settle-transition: 0ms linear;
}

:where(
  html[data-spw-runtime-mount-batch="active"],
  html[data-spw-page-state="booting"],
  html[data-spw-page-state="interactive"]
) :where(
  .site-frame,
  .frame-panel,
  .frame-card,
  [data-spw-kind]:not(body):not(main),
  [data-spw-box-model]
) {
  transition-property: color, background-color, opacity, filter;
}

:where(html[data-spw-page-state="region-enhanced"], html[data-spw-page-state="enhanced"]) :where(
  [data-spw-harmony],
  [data-spw-region-state],
  [data-spw-region-genome],
  [data-spw-tempo],
  [data-spw-density]
) {
  transition:
    border-color var(--spw-region-profile-refresh-duration, 220ms) var(--ease-settle, ease),
    box-shadow var(--spw-region-profile-refresh-duration, 220ms) var(--ease-settle, ease),
    outline-color var(--spw-region-profile-refresh-duration, 220ms) var(--ease-settle, ease),
    transform var(--spw-component-arrival-transition, 140ms var(--ease-settle, ease));
}

:where(html[data-spw-connection-posture="offline"], html[data-spw-prefetch-mode="deferred"]) {
  --spw-runtime-enhancement-intensity: min(var(--spw-runtime-enhancement-intensity, 0.5), 0.48);
  --spw-site-rhythm-tempo: min(var(--spw-site-rhythm-tempo, 1), 0.82);
}

:where(html[data-spw-connection-posture="offline"]) :where(.site-frame, .frame-panel, .frame-card) {
  --component-accent:
    color-mix(in srgb, var(--component-accent, var(--teal, #008080)) 72%, var(--ink-soft, rgba(14, 18, 20, 0.72)) 28%);
}

/* Module effect surface — root-level tokens derived from mounted module side effects. */
:where(html[data-spw-module-effects-active]) {
  --spw-module-effect-surface: 1;
}

:where(html[data-spw-module-effect-pulse]) {
  --spw-module-effect-pulse: 1;
  --spw-site-rhythm-tempo: min(calc(var(--spw-site-rhythm-tempo, 1) * 1.08), 3.2);
}

/* Effect ledger flourishes — precipitated residue as soft ornament knobs.
   Defaults live in tokens/core.css; effect-ledger.js overrides on html when residue lands. */
:where(html[data-spw-effects]) {
  --spw-effect-surface: 1;
  --spw-effect-ledger-scale: calc(1 + (min(var(--spw-effect-count), 24) * 0.004));
  --spw-site-rhythm-density: max(
    var(--spw-site-rhythm-density, 0.5),
    calc(0.48 + (var(--spw-effect-charge) * 0.28))
  );
}

:where(html[data-spw-effect-pulse]) {
  --spw-effect-pulse-active: max(var(--spw-effect-pulse), 1);
  --spw-microinteraction-pulse-intensity: max(
    var(--spw-microinteraction-pulse-intensity, 1),
    calc(1 + (max(var(--spw-effect-charge), 0.18) * 0.22 * var(--spw-effect-pulse-active, 1)))
  );
  --spw-site-rhythm-tempo: min(
    calc(var(--spw-site-rhythm-tempo, 1) * (1 + (max(var(--spw-effect-charge), 0.12) * 0.1))),
    3.2
  );
}

:where(html[data-spw-module-visuals="on"][data-spw-effect-pulse]) {
  --spw-effect-pulse-ring:
    inset 0 0 0 1px color-mix(in srgb, var(--op-object-color, #c9862a) calc(18% + (var(--spw-effect-charge) * 16%)), transparent);
  outline: 1px solid color-mix(in srgb, var(--op-object-color, #c9862a) calc(16% + (var(--spw-effect-charge) * 14%)), transparent);
  outline-offset: -1px;
  transition: outline-color 420ms var(--ease-smooth, ease);
}

/* Runtime load diagnostic — module-loader writes avg mount ms; inspect surfaces may read it. */
:where(html[data-spw-module-visuals="on"]) {
  --spw-runtime-load-bias: clamp(
    0,
    calc(var(--spw-runtime-avg-module-ms) / 120),
    1
  );
}

:where(html[data-spw-module-visuals="on"][data-spw-runtime-stage="ready"]) {
  --spw-site-rhythm-density: max(
    var(--spw-site-rhythm-density, 0.5),
    calc(0.42 + (var(--spw-runtime-load-bias) * 0.18))
  );
}

:where(html[data-spw-reduce-motion="on"][data-spw-effect-pulse]) {
  --spw-effect-pulse-active: 0;
  --spw-microinteraction-pulse-intensity: 1;
}

:where(html[data-spw-runtime-enhancement-active="true"]) {
  --spw-runtime-enhancement-intensity: max(var(--spw-runtime-enhancement-intensity, 0.32), 0.72);
}

:where(html[data-spw-runtime-feature-active="true"]) {
  --spw-runtime-feature-intensity: max(var(--spw-runtime-feature-intensity, 0.22), 0.62);
}

:where(html[data-spw-runtime-layer-pulse="dense"]) {
  --spw-site-rhythm-density: max(var(--spw-site-rhythm-density, 0.5), 0.92);
}

:where([data-spw-interaction-contract]) {
  --spw-interaction-contract-surface: 1;
}

:where([data-spw-interaction-affordance]) {
  cursor: pointer;
}

:where(
  [data-spw-interaction-contract]:is(:hover, :focus-visible),
  [data-spw-loop-state="preview"],
  .spw-route-menu-link:is(:hover, :focus-visible)
) {
  --spw-interaction-loop-preview: 1;
}

:where([data-spw-loop-state="activated"], [data-spw-loop-state="resolved"]) {
  --spw-interaction-loop-active: 1;
}

/* ==========================================================================
   25b. Loading ecology surface
   --------------------------------------------------------------------------
   Root token projections for prefetch, measurement, settling, and genre
   maturation. Environmental spending lives in substrate-ecology; arrival bias
   spends through frames/surfaces; operator twinkle spends in operators.css.
   ========================================================================== */

:where(html[data-spw-loading-ecology-phase]) {
  --spw-loading-ecology-surface: 1;
}

:where(html[data-spw-loading-ecology-phase="discovering"], html[data-spw-loading-ecology-phase="prefetching"]) {
  --spw-layout-cascade-hold: max(var(--spw-layout-cascade-hold, 0), 0.72);
  --spw-region-profile-intensity: min(var(--spw-region-profile-intensity, 1), 0.42);
}

:where(html[data-spw-loading-ecology-phase="measuring"]) {
  --spw-layout-measure-settle: var(--spw-region-profile-refresh-duration, 220ms) var(--ease-settle);
}

:where(html[data-spw-loading-ecology-phase="mounting"]) {
  --spw-site-rhythm-tempo: min(calc(var(--spw-site-rhythm-tempo, 1) * 0.92), 2.4);
}

:where(html[data-spw-loading-ecology-phase="settling"], html[data-spw-loading-ecology-phase="personalizing"]) {
  --spw-site-rhythm-tempo: min(calc(var(--spw-site-rhythm-tempo, 1) * 0.94), 2.8);
  --spw-ecology-settle-weight: 1;
  --spw-component-transition-arrival: var(--spw-component-arrival-transition, 140ms var(--ease-settle));
}

:where(html[data-spw-loading-ecology-phase="settled"]) {
  --spw-ecology-settle-weight: 0;
  --spw-ecology-arrival-bias: 0px;
}

:where(html[data-spw-loading-ecology-salience="forward"]) {
  --spw-ecology-salience-shift: var(--spw-settle-offset-start, 2px);
}

:where(html[data-spw-loading-ecology-salience="return"], html[data-spw-loading-ecology-salience="restore"]) {
  --spw-ecology-salience-shift: calc(var(--spw-settle-offset-start, 2px) * -1);
}

:where(html[data-spw-loading-ecology-salience="anchor"]) {
  --spw-ecology-salience-shift: 0px;
}

:where(html[data-spw-loading-ecology-salience="dormancy"]) {
  --spw-ecology-salience-shift: var(--spw-settle-offset-mid, 1px);
  --spw-site-rhythm-tempo: min(var(--spw-site-rhythm-tempo, 1), 0.72);
}

:where(html[data-spw-loading-ecology-salience]:not([data-spw-loading-ecology-salience="anchor"])) {
  --spw-ecology-arrival-bias: calc(var(--spw-ecology-salience-shift, 0px) * -1 * var(--spw-ecology-settle-weight, 0));
}

:where(html[data-spw-loading-ecology-rhythm="snap"], html[data-spw-loading-ecology-rhythm="fast"]) {
  --spw-ecology-beat-align: 0.42;
}

:where(html[data-spw-loading-ecology-rhythm="base"]) {
  --spw-ecology-beat-align: 0.62;
}

:where(html[data-spw-loading-ecology-rhythm="deliberate"], html[data-spw-loading-ecology-rhythm="settle"]) {
  --spw-ecology-beat-align: 1;
}

:where(html[data-spw-loading-ecology-twinkle="true"]) {
  --spw-ecology-twinkle: 1;
  --spw-site-rhythm-density: max(var(--spw-site-rhythm-density, 0.5), 0.88);
  --spw-ecology-readiness-ring-strength: 1;
}

:where(html[data-spw-loading-ecology-dimensions~="fetch"]) {
  --spw-ecology-readiness-ring-strength: max(var(--spw-ecology-readiness-ring-strength, 0), 0.72);
}

:where(html[data-spw-prefetch-mode="selective"]) :where(
  [data-spw-module],
  [data-spw-image-reward],
  [data-spw-image-discovery]
) {
  --spw-runtime-readiness-ring:
    0 0 0 calc(1px + (1px * var(--spw-ecology-readiness-ring-strength, 0)))
      color-mix(in srgb, var(--active-op-color, var(--teal, #008080)) calc(10% + (8% * var(--spw-ecology-readiness-ring-strength, 0))), transparent),
    0 0 calc(8px * var(--spw-ecology-twinkle, 0) * var(--spw-ecology-readiness-ring-strength, 0))
      color-mix(in srgb, var(--active-op-color, var(--teal, #008080)) 8%, transparent);
  box-shadow: var(--spw-runtime-readiness-ring), var(--spw-local-shadow, var(--component-shadow, none));
}

:where(html[data-spw-loading-ecology-dimensions~="personalize"]) {
  --spw-runtime-enhancement-intensity: max(var(--spw-runtime-enhancement-intensity, 0.32), 0.58);
}

:where(html[data-spw-loading-ecology-dimensions~="theme"]) {
  --spw-component-settle-transition: var(--spw-interaction-settle, var(--component-transition-base));
}

:where(html[data-spw-loading-ecology-dimensions~="measure"]) :where(
  [data-spw-flow="pretext"],
  [data-spw-box-model]
) {
  transition:
    opacity var(--spw-layout-measure-settle, 220ms var(--ease-settle)),
    transform var(--spw-layout-measure-settle, 220ms var(--ease-settle));
}

:where(html[data-spw-loading-ecology-trope="ruleset-settle"]) {
  --spw-ecology-trope-weight: 0.72;
}

:where(html[data-spw-loading-ecology-trope="theme-shift"], html[data-spw-loading-ecology-trope="spacing-tune"]) {
  --spw-ecology-trope-weight: 0.78;
}

:where(html[data-spw-loading-ecology-trope="gestalt-rebalance"], html[data-spw-loading-ecology-trope="typography-flow"]) {
  --spw-ecology-trope-weight: 0.86;
}

:where(html[data-spw-loading-ecology-genre]) {
  --spw-salience-weight: calc(0.34 + (var(--spw-ecology-trope-weight, 0) * 0.12));
}

:where(html[data-spw-loading-ecology-phase="settling"], html[data-spw-loading-ecology-phase="personalizing"]) :where(
  [data-spw-region-state="settling"],
  [data-spw-module][data-spw-module-hydration="ready"]
) {
  --component-module-rail-opacity: calc(0.44 + (0.12 * var(--spw-ecology-settle-weight, 0)));
}

:where(html[data-spw-reduce-motion="on"]) {
  --spw-ecology-twinkle: 0;
  --spw-ecology-readiness-ring-strength: 0;
  --spw-ecology-arrival-bias: 0px;
}

/* Settings tuning + spell momentum (brief pulse after canonical settings apply) */
:where(html[data-spw-settings-momentum="pulse"]) {
  --spw-runtime-enhancement-intensity: max(var(--spw-runtime-enhancement-intensity, 0.32), 0.64);
  --spw-interaction-loop-active: 1;
}

:where(html[data-spw-spell-momentum="tuning"]) :where(
  .spw-spell,
  .spw-route-menu-link,
  [data-spw-interaction-contract]
) {
  transition-duration: var(--touch-commit, 180ms);
}


/* ==========================================================================
   26. Accessibility and visibility
   ========================================================================== */

:where([hidden]) {
  display: none !important;
}

:where(:focus-visible) {
  outline: none;
  box-shadow: var(--focus-ring, 0 0 0 3px rgba(0, 128, 128, 0.18));
}

:where(button, a, input, select, textarea, summary) {
  -webkit-tap-highlight-color: color-mix(in srgb, var(--component-accent) 18%, transparent);
}

:where(button, summary, input[type="button"], input[type="submit"], input[type="reset"], [role="button"]) {
  cursor: pointer;
}

:where(html[data-spw-high-contrast="on"]) {
  --component-border: 1px solid color-mix(in srgb, var(--ink, currentColor) 34%, var(--line, transparent));
