  }

  :where(.frame-operators, .card-sub-links, .ref-links, .plan-links) {
    gap: 0.4rem;
  }

  :where(.frame-operators > .operator-chip, .card-sub-links a, .ref-links a, .plan-links a) {
    flex: 1 1 11rem;
    justify-content: flex-start;
    min-height: 2.55rem;
    padding-inline: 0.82rem;
    text-align: left;
  }

  :where(.frame-operators, .card-sub-links, .ref-links, .plan-links) {
    padding: 0.14rem;
