}
}

/* /public/css/components/charge-cycle.css */
@layer components {
/* ==========================================================================
   charge-cycle.css
   --------------------------------------------------------------------------
   Field-level charge/discharge projection when explore posture reveals anatomy.
   ========================================================================== */

:root {
  --spw-charge-field: 0;
  --spw-arc-color: var(--active-op-color, var(--semantic-accent, #008080));
}

/* Ambient field wash — stronger in workshop, subtle in field */
:where(html[data-spw-explore-posture="field"], html[data-spw-explore-posture="workshop"]) {
  background-image:
    radial-gradient(
      ellipse 120% 80% at 50% -10%,
      color-mix(in srgb, var(--op-probe-color, #4a2180) calc(var(--spw-charge-field, 0) * 14%), transparent),
      transparent 58%
    ),
    radial-gradient(
      ellipse 90% 60% at 88% 100%,
      color-mix(in srgb, var(--active-op-color, #008080) calc(var(--spw-charge-field, 0) * 10%), transparent),
      transparent 62%
    );
  background-attachment: fixed;
}

:where(html[data-spw-tuning-discoverability="revealed"]) {
  background-image:
    radial-gradient(
      ellipse 120% 80% at 50% -10%,
      color-mix(in srgb, var(--op-probe-color, #4a2180) calc(var(--spw-charge-field, 0) * 18%), transparent),
      transparent 58%
    ),
    radial-gradient(
      ellipse 90% 60% at 88% 100%,
      color-mix(in srgb, var(--active-op-color, #008080) calc(var(--spw-charge-field, 0) * 12%), transparent),
      transparent 62%
    );
  background-attachment: fixed;
}

/* Live consequence on frames during charge/discharge */
:where(
  html[data-spw-explore-posture="field"],
  html[data-spw-explore-posture="workshop"],
  html[data-spw-tuning-discoverability="ambient"],
  html[data-spw-tuning-discoverability="revealed"]
) :where(.site-frame[data-spw-charge-phase="preview"], .site-frame[data-spw-charge-phase="charged"]) {
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--active-op-color, #008080) 16%, transparent),
    0 0 0 calc(1px + (var(--spw-charge-field, 0) * 2px))
    color-mix(in srgb, var(--op-probe-color, #4a2180) calc(var(--spw-charge-field, 0) * 28%), transparent);
}

:where(
  html[data-spw-explore-posture="field"],
  html[data-spw-explore-posture="workshop"],
  html[data-spw-tuning-discoverability="revealed"]
) :where(.site-frame[data-spw-discharge-kind]) {
  animation: spw-discharge-echo 1.1s ease-out both;
}

@keyframes spw-discharge-echo {
  0% {
    box-shadow:
      0 0 0 0 color-mix(in srgb, var(--spw-arc-color, var(--active-op-color, #008080)) 42%, transparent),
      inset 3px 0 0 color-mix(in srgb, var(--spw-arc-color, var(--active-op-color, #008080)) 55%, transparent);
  }
  100% {
    box-shadow:
      0 0 0 12px transparent,
      inset 3px 0 0 color-mix(in srgb, var(--spw-arc-color, var(--active-op-color, #008080)) 18%, transparent);
  }
}

/* Discharge kind accent on frame edge */
:where(.site-frame[data-spw-discharge-kind="release"]) {
  --spw-discharge-color: var(--op-probe-color, #4a2180);
}

:where(.site-frame[data-spw-discharge-kind="transfer"]) {
  --spw-discharge-color: var(--op-ref-color, #355f77);
}

:where(.site-frame[data-spw-discharge-kind="ground"]) {
  --spw-discharge-color: var(--op-frame-color, #008080);
}

:where(.site-frame[data-spw-discharge-kind="project"]) {
  --spw-discharge-color: var(--op-object-color, #a67c00);
}

:where(.site-frame[data-spw-discharge-kind]) {
  border-color: color-mix(in srgb, var(--spw-discharge-color, var(--active-op-color)) 24%, var(--line, rgba(14, 18, 20, 0.14)) 76%);
}

/* Embedded workshop charge readout */
:where(.spw-embedded-workshop [data-charge-field-readout]) {
  font-variant-numeric: tabular-nums;
}
}

/* /public/css/systems/image-utilization.css */
@layer systems {
/* ==========================================================================
   image-utilization.css
   --------------------------------------------------------------------------
   Performance + distribution for figures and reward/discovery image surfaces.
   JS sets data-spw-image-utilization; CSS owns layout containment and decode
   cost without blocking authored aspect ratios.
   ========================================================================== */

:root {
  --spw-image-distribution-gap: var(--component-gap-tight, 0.55rem);
  --spw-image-utilization-contain: layout style paint;
}

:where([data-spw-image-utilization="distributed"], [data-spw-image-distribution="cascade"]) {
  content-visibility: auto;
  contain-intrinsic-size: auto 12rem;
}

:where([data-spw-image-utilization="hero"], [data-spw-image-distribution="anchor"]) {
  content-visibility: visible;
}

:where(main img, [data-spw-image-surface] img, [data-spw-image-reward] img, [data-spw-image-discovery] img) {
  max-inline-size: 100%;
  block-size: auto;
  object-fit: cover;
}

:where([data-spw-image-reward], [data-spw-image-discovery], .frame-card-media, .image-study) {
  contain: var(--spw-image-utilization-contain);
}

:where(html[data-spw-hydration-pass="lex"]) :where([data-spw-image-utilization="distributed"]) {
  opacity: var(--spw-settle-opacity-mid, 0.985);
}

:where(html[data-spw-hydration-pass="pragmatic"]) :where([data-spw-image-discovered="true"]) {
  --spw-image-utilization-contain: none;
}

:where(.spw-visual-link-board__grid, .frame-grid--media) {
  display: grid;
  gap: var(--spw-image-distribution-gap);
  grid-template-columns: repeat(auto-fit, minmax(min(100%, var(--grid-min-card, 15rem)), 1fr));
}
}

/* /public/css/systems/image-interaction.css */
@layer systems {
/* ==========================================================================
   image-interaction.css
   --------------------------------------------------------------------------
   Framing, hover/focus, tap/hold/swipe lens interaction for image figures.
   Performance/containment stays in image-utilization.css.
   ========================================================================== */

:root {
  --spw-image-frame-pad: 0.48rem;
  --spw-image-frame-line: color-mix(in srgb, var(--line, rgba(14, 18, 20, 0.14)) 72%, transparent);
  --spw-image-mat: color-mix(in srgb, var(--surface-strong, #fff) 92%, var(--active-op-color, var(--teal, #008080)) 8%);
  --spw-image-interaction-lift: 1.018;
  --spw-image-interaction-saturate: 1.05;
  --spw-image-interaction-contrast: 1.03;
  --spw-image-interaction-duration: var(--duration-deliberate, 360ms);
  --spw-image-interaction-ease: var(--ease-mechanical, ease);
  --spw-image-interaction-ring: color-mix(in srgb, var(--spw-image-lens-accent, var(--active-op-color, var(--teal, #008080))) 22%, transparent);
  --spw-image-interaction-glow: color-mix(in srgb, var(--spw-image-lens-accent, var(--active-op-color, var(--teal, #008080))) 10%, transparent);
  --spw-image-lens-accent: var(--active-op-color, var(--teal, #008080));
}

:where(
  .topic-photo-card,
  .image-study,
  [data-spw-image-reward],
  [data-spw-image-discovery],
  .frame-card-media,
  .spw-visual-link-card__media,
  [data-spw-image-surface]
) {
  --spw-image-interaction-scale: 1;
  --spw-image-interaction-filter: none;
  position: relative;
  touch-action: pan-y;
  border: 1px solid var(--spw-image-frame-line);
  border-radius: var(--component-radius-tight, 8px);
  background:
    linear-gradient(165deg, color-mix(in srgb, var(--spw-image-mat) 88%, white 12%), var(--spw-image-mat)),
    var(--spw-image-mat);
  padding: var(--spw-image-frame-pad);
  transition:
    border-color var(--spw-image-interaction-duration) var(--spw-image-interaction-ease),
    box-shadow var(--spw-image-interaction-duration) var(--spw-image-interaction-ease),
    transform var(--spw-image-interaction-duration) var(--spw-image-interaction-ease);
}

:where(.topic-photo-card, .image-study)[data-spw-image-prominence="hero"] {
  --spw-image-frame-pad: 0.58rem;
}

:where(.topic-photo-card, .image-study)[data-spw-image-prominence="supporting"] {
  --spw-image-frame-pad: 0.38rem;
  max-inline-size: min(100%, 36rem);
}

:where(.frame-card--illustrated .frame-card-media, .spw-visual-link-card__media) {
  --spw-image-frame-pad: 0;
  border: none;
  background: transparent;
  padding: 0;
  border-radius: inherit;
}

:where(
  .topic-photo-card img,
  .image-study img,
  [data-spw-image-reward] img,
  [data-spw-image-discovery] img,
  .frame-card-media img,
  .spw-visual-link-card__media img,
  [data-spw-image-surface] img
) {
  display: block;
  inline-size: 100%;
  block-size: auto;
  border-radius: calc(var(--component-radius-tight, 8px) - 2px);
  object-fit: cover;
  transition:
    transform var(--spw-image-interaction-duration) var(--spw-image-interaction-ease),
    filter var(--spw-image-interaction-duration) var(--spw-image-interaction-ease);
}

:where([data-spw-image-shape="landscape"] img) {
  aspect-ratio: 16 / 10;
}

:where([data-spw-image-shape="square"] img) {
  aspect-ratio: 1 / 1;
}

:where([data-spw-image-shape="portrait"] img) {
  aspect-ratio: 3 / 4;
}

:where([data-spw-image-lens-active="probe"]) {
  --spw-image-lens-accent: var(--op-probe-color, #6a3fb8);
}

:where([data-spw-image-lens-active="frame"]) {
  --spw-image-lens-accent: var(--op-frame-color, #1a9999);
}

:where([data-spw-image-lens-active="object"]) {
  --spw-image-lens-accent: var(--op-object-color, #c68a22);
}

:where([data-spw-image-lens-active="ref"]) {
  --spw-image-lens-accent: var(--op-ref-color, #1d57a3);
}

:where([data-spw-image-lens-active="action"]) {
  --spw-image-lens-accent: var(--op-action-color, #147a70);
}

:where([data-spw-image-lens-active="stream"]) {
  --spw-image-lens-accent: var(--op-stream-color, #2a8c76);
}

:where([data-spw-image-lens-active="surface"]) {
  --spw-image-lens-accent: var(--op-surface-color, #355f77);
}

:where([data-spw-image-lens-active="integrate"]) {
  --spw-image-lens-accent: var(--op-integrate-color, var(--teal, #008080));
}

:where([data-spw-image-lens-active="baseline"]) {
  --spw-image-lens-accent: var(--ink-soft, rgba(14, 18, 20, 0.68));
}

:where([data-spw-image-lens-active="potential"]) {
  --spw-image-lens-accent: var(--op-potential-color, var(--op-probe-color, #6a3fb8));
}

:where(
  .topic-photo-card:is(:hover, :focus-within),
  .image-study:is(:hover, :focus-within),
  [data-spw-image-reward]:is(:hover, :focus-within),
  [data-spw-image-discovery]:is(:hover, :focus-within),
  .frame-card-media:is(:hover, :focus-within),
  [data-spw-image-surface]:is(:hover, :focus-within),
  [data-spw-image-interaction-state="primed"],
  [data-spw-image-interaction-state="inspecting"],
  [data-spw-image-interaction-state="lensed"]
) {
  border-color: color-mix(in srgb, var(--spw-image-interaction-ring) 68%, var(--line, transparent));
  box-shadow:
    0 0 0 1px var(--spw-image-interaction-glow),
    var(--spw-local-shadow, var(--component-shadow, none));
}

:where(
  .topic-photo-card:is(:hover, :focus-within) img,
  .image-study:is(:hover, :focus-within) img,
  [data-spw-image-reward]:is(:hover, :focus-within) img,
  [data-spw-image-discovery]:is(:hover, :focus-within) img,
  .frame-card-media:is(:hover, :focus-within) img,
  [data-spw-image-surface]:is(:hover, :focus-within) img,
  [data-spw-image-interaction-state="primed"] img,
  [data-spw-image-interaction-state="inspecting"] img,
  [data-spw-image-interaction-state="lensed"] img
) {
  transform: scale(var(--spw-image-interaction-lift));
  filter: saturate(var(--spw-image-interaction-saturate)) contrast(var(--spw-image-interaction-contrast));
}

:where([data-spw-image-interaction-state="inspecting"]) {
  transform: translateY(-1px);
}

:where([data-spw-image-interaction-state="inspecting"] img) {
  --spw-image-interaction-lift: 1.024;
}

:where([data-spw-image-interaction-state="lensed"] img) {
  filter:
    saturate(calc(var(--spw-image-interaction-saturate) + 0.04))
    contrast(calc(var(--spw-image-interaction-contrast) + 0.02));
}

:where([data-spw-image-discovered="true"], [data-spw-image-interaction-state="discovered"]) {
  border-color: color-mix(in srgb, var(--spw-image-lens-accent, var(--active-op-color, var(--teal, #008080))) 28%, transparent);
}

:where([data-spw-image-discovered="true"]::after, [data-spw-image-discovery][data-spw-image-interaction-state="primed"]::after) {
  border-color: color-mix(in srgb, var(--spw-image-lens-accent, var(--active-op-color, var(--teal, #008080))) 36%, transparent);
}

:where(
  .topic-photo-card .study-summary,
  .image-study .study-summary
) {
  display: grid;
  gap: 0.42rem;
  padding: 0.55rem 0.12rem 0.18rem;
  min-width: 0;
}

:where(.study-summary .meta-cluster) {
  display: flex;
  flex-wrap: wrap;
  gap: 0.38rem;
  align-items: center;
}

:where(.study-summary .meta-cluster .spec-pill) {
  margin: 0;
}

:where(.spw-image-lens-hint) {
  color: color-mix(in srgb, var(--spw-image-lens-accent, var(--ink-soft, rgba(14, 18, 20, 0.68))) 72%, var(--ink, currentColor) 28%);
  font-family: var(--site-mono-font, "JetBrains Mono", monospace);
  font-size: var(--text-size-2xs, 0.68rem);
  font-weight: 700;
  letter-spacing: 0.02em;
  line-height: 1.3;
}

:where(.study-summary p, .study-summary > span:not(.spw-image-lens-hint)) {
  margin: 0;
  color: var(--ink-soft, rgba(14, 18, 20, 0.68));
  font-size: var(--text-size-sm, 0.88rem);
  line-height: 1.5;
  text-wrap: pretty;
}

:where(.study-summary__lead) {
  color: color-mix(in srgb, var(--ink, currentColor) 88%, var(--spw-image-lens-accent, var(--active-op-color, var(--teal, #008080))) 12%);
}

:where(.study-summary__move) {
  font-size: var(--text-size-xs, 0.82rem);
  line-height: 1.45;
  max-inline-size: 62ch;
}

:where(.study-summary strong) {
  color: color-mix(in srgb, var(--ink, currentColor) 84%, var(--spw-image-lens-accent, var(--active-op-color, var(--teal, #008080))) 16%);
}

:where(html[data-spw-loading-ecology-twinkle="true"]) :where(
  [data-spw-image-discovered="true"],
  [data-spw-image-discovery][data-spw-image-interaction-state="primed"]
) {
  box-shadow:
    var(--spw-runtime-readiness-ring, 0 0 0 1px var(--spw-image-interaction-glow)),
    var(--spw-local-shadow, var(--component-shadow, none));
}

:where(html[data-spw-hydration-pass="semantic"]) :where(
  [data-spw-image-discovery],
  [data-spw-image-reward],
  .topic-photo-card[data-spw-image-prominence="hero"]
) {
  opacity: var(--spw-settle-opacity-high, 1);
}

:where(html[data-spw-reduce-motion="on"]) {
  --spw-image-interaction-lift: 1;
  --spw-image-interaction-saturate: 1;
  --spw-image-interaction-contrast: 1;
  --spw-image-interaction-duration: 1ms;
}

:where(html[data-spw-reduce-motion="on"]) :where(
  .topic-photo-card,
  .image-study,
  [data-spw-image-reward],
  [data-spw-image-discovery],
  .frame-card-media,
  [data-spw-image-surface]
) {
  transform: none;
}

/* Phase coupling — image surfaces breathe with html interaction phase */
:where(html[data-spw-interaction-phase="approach"]) :where(
  [data-spw-image-interaction-state="primed"],
  [data-spw-image-interaction-state="idle"]
) {
  --spw-image-interaction-lift: 1.012;
}

:where(html[data-spw-interaction-phase="inspect"]) :where([data-spw-image-interaction-state="inspecting"]) {
  --spw-image-interaction-lift: 1.028;
  border-color: color-mix(in srgb, var(--spw-image-interaction-ring) 82%, var(--line, transparent));
}

:where(html[data-spw-interaction-phase="charge"]) :where([data-spw-image-interaction-state="lensed"]) {
  --spw-image-interaction-saturate: 1.08;
}

:where(html[data-spw-interaction-phase="discover"]) :where(
  [data-spw-image-interaction-state="lensed"],
  [data-spw-image-interaction-state="discovered"]
) {
  box-shadow:
    inset 0 -2px 0 color-mix(in srgb, var(--spw-image-lens-accent) 22%, transparent),
    0 0 0 1px var(--spw-image-interaction-glow),
    var(--spw-local-shadow, var(--component-shadow, none));
}

:where(html[data-spw-microinteraction-pulse="discover"]) :where([data-spw-image-lens-active]) {
  outline: 1px dashed color-mix(in srgb, var(--spw-image-lens-accent) 30%, transparent);
  outline-offset: 3px;
}
}

/* /public/css/systems/interaction-progression.css */
@layer systems {
/* ==========================================================================
   interaction-progression.css
   --------------------------------------------------------------------------
   Interaction phase tokens and microinteraction pulses for progressive states.
   ========================================================================== */

:root {
  --spw-interaction-phase-weight: 0;
  --spw-microinteraction-pulse-scale: 1;
  --spw-interaction-phase-tuning: 1;
}

:where(html[data-spw-enhancement-level="minimal"]) {
  --spw-interaction-phase-tuning: 0.72;
}

:where(html[data-spw-enhancement-level="rich"]) {
  --spw-interaction-phase-tuning: 1.14;
}

:where(html[data-spw-semantic-density="minimal"]) {
  --spw-microinteraction-pulse-scale: 1;
  --spw-interaction-phase-tuning: calc(var(--spw-interaction-phase-tuning, 1) * 0.86);
}

:where(html[data-spw-semantic-density="rich"]) {
  --spw-interaction-phase-tuning: calc(var(--spw-interaction-phase-tuning, 1) * 1.08);
}

:where(html[data-spw-interaction-phase="approach"]) {
  --spw-interaction-phase-weight: calc(0.28 * var(--spw-interaction-phase-tuning, 1));
  --spw-pre-state-visibility: max(var(--spw-pre-state-visibility, 0.5), 0.62);
}

:where(html[data-spw-interaction-phase="prime"]) {
  --spw-interaction-phase-weight: calc(0.46 * var(--spw-interaction-phase-tuning, 1));
  --spw-variant-selection-weight: max(var(--spw-variant-selection-weight, 0), 0.34);
}

:where(html[data-spw-interaction-phase="charge"]) {
  --spw-interaction-phase-weight: calc(0.58 * var(--spw-interaction-phase-tuning, 1));
  --spw-ecology-twinkle: max(var(--spw-ecology-twinkle, 0), 0.42);
}

:where(html[data-spw-interaction-phase="inspect"]) {
  --spw-interaction-phase-weight: calc(0.72 * var(--spw-interaction-phase-tuning, 1));
  --spw-color-layer-accent-apparent: color-mix(
    in srgb,
    var(--active-op-color, var(--teal, #008080)) 52%,
    transparent
  );
}

:where(html[data-spw-interaction-phase="discover"]) {
  --spw-interaction-phase-weight: calc(0.86 * var(--spw-interaction-phase-tuning, 1));
  --spw-salience-weight: max(var(--spw-salience-weight, 0.34), 0.72);
}

:where(html[data-spw-interaction-phase="settle"]) {
  --spw-interaction-phase-weight: calc(0.34 * var(--spw-interaction-phase-tuning, 1));
  --spw-ecology-settle-weight: max(var(--spw-ecology-settle-weight, 0), 0.88);
}

:where(html[data-spw-microinteraction-pulse]) {
  --spw-microinteraction-pulse-scale: 1.012;
}

:where(html[data-spw-microinteraction-pulse] :where(
  [data-spw-image-interaction-state],
  [data-spw-vocabulary-collectible="high"],
  .study-summary
)) {
  transition:
    box-shadow 220ms var(--ease-settle, ease),
    border-color 220ms var(--ease-settle, ease),
    transform 220ms var(--ease-settle, ease);
}

:where(html[data-spw-microinteraction-pulse="prime"] :where([data-spw-image-interaction-state="primed"])) {
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--active-op-color, var(--teal, #008080)) 16%, transparent),
    var(--spw-local-shadow, var(--component-shadow, none));
}

:where(html[data-spw-microinteraction-pulse="charge"] :where([data-spw-image-lens-active])) {
  outline: 1px solid color-mix(in srgb, var(--spw-image-lens-accent, var(--active-op-color, var(--teal, #008080))) 24%, transparent);
  outline-offset: 2px;
}

:where([data-spw-learnable-dimension]) {
  --spw-salience-weight: calc(0.34 + (var(--spw-interaction-phase-weight, 0) * 0.22));
}

:where(html[data-spw-reduce-motion="on"]) {
  --spw-microinteraction-pulse-scale: 1;
}

/* --------------------------------------------------------------------------
   Pinch scaling + gesture state coupling
   -------------------------------------------------------------------------- */

:where(html[data-spw-pinch-scaling="true"], body[data-spw-pinch-scaling="true"]) {
  --spw-interaction-phase-weight: max(var(--spw-interaction-phase-weight, 0), 0.32);
  --spw-color-layer-accent-subtle: color-mix(
    in srgb,
    var(--active-op-color, var(--teal, #008080)) 28%,
    transparent
  );
  --palette-depth-strength: calc(var(--palette-depth-strength, 1) * 1.06);
}

:where(html[data-spw-interaction-phase="charge"], html[data-spw-interaction-phase="inspect"]) {
  --palette-depth-strength: calc(var(--palette-depth-strength, 1) * 1.04);
}

:where([data-spw-gesture="charging"], [data-spw-gesture="armed"], [data-spw-gesture="sustained"]) {
  --spw-interaction-contract-surface: calc(1 + (var(--spw-interaction-phase-weight, 0) * 0.18));
}

/* Copy-depth accent breathes with phase (see coloring-depth.css tokens) */
:where(html[data-spw-interaction-phase="prime"]) :where([data-spw-copy-depth]) {
  --spw-copy-depth-bg-mix: calc(var(--spw-copy-depth-bg-mix, 4%) + 1%);
}

:where(html[data-spw-interaction-phase="charge"]) :where([data-spw-copy-depth]) {
  --spw-copy-depth-line-mix: calc(var(--spw-copy-depth-line-mix, 22%) + 4%);
  --spw-copy-depth-bg-mix: calc(var(--spw-copy-depth-bg-mix, 4%) + 2%);
}

:where(html[data-spw-interaction-phase="discover"]) :where([data-spw-copy-depth="genre"]) {
  --spw-copy-depth-line-mix: calc(var(--spw-copy-depth-line-mix, 30%) + 4%);
}

/* --------------------------------------------------------------------------
   Interaction contracts: hover, focus, active, loop sequence
   -------------------------------------------------------------------------- */

:where([data-spw-interaction-contract]) {
  --spw-contract-press-depth: 0;
}

:where(
  [data-spw-interaction-contract]:is(:hover, :focus-visible),
  [data-spw-interaction-contract][data-spw-loop-state="preview"]
) {
  --spw-contract-press-depth: 1;
  transform: translateY(calc(-1px * var(--spw-interaction-phase-weight, 0.28)));
}

:where([data-spw-interaction-contract]:active) {
  --spw-contract-press-depth: 2;
  transform: translateY(0);
  transition-duration: 90ms;
}

:where([data-spw-interaction-contract][data-spw-loop-state="activated"]) {
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--spw-operator-color, var(--active-op-color)) 22%, transparent),
    0 0 0 2px color-mix(in srgb, var(--spw-operator-color, var(--active-op-color)) 10%, transparent);
}

:where([data-spw-interaction-contract][data-spw-loop-state="resolved"]) {
  opacity: 0.92;
  filter: saturate(0.94);
}

/* Coarse pointer: tap replaces hover affordance */
@media (hover: none) and (pointer: coarse) {
  :where(
    [data-spw-interaction-contract]:active,
    [data-spw-gesture-contract]:active,
    .operator-chip:active
  ) {
    --spw-interaction-phase-weight: max(var(--spw-interaction-phase-weight, 0), 0.42);
    transform: scale(0.992);
  }

  :where([data-spw-gesture-contract]:active) {
    box-shadow:
      inset 0 0 0 1px color-mix(in srgb, var(--active-op-color) 24%, transparent),
      0 0 0 3px color-mix(in srgb, var(--active-op-color) 8%, transparent);
  }
}

/* Scroll-rail swipe discoverability */
:where([data-spw-scroll-rail], .spw-visual-link-board__grid, .frame-grid--media) {
  scroll-behavior: smooth;
}

:where(html[data-spw-interaction-phase="discover"]) :where(
  [data-spw-scroll-rail],
  .spw-visual-link-board__grid,
  .frame-grid--media
) {
  box-shadow: inset 0 -2px 0 color-mix(in srgb, var(--active-op-color) 18%, transparent);
}

:where(html[data-spw-microinteraction-pulse="discover"] :where([data-spw-vocab], [data-spw-semantic-cluster])) {
  text-decoration-thickness: 0.1em;
  text-underline-offset: 0.2em;
}

/* --------------------------------------------------------------------------
   Pulse-beat tuner: settings-driven freshness + baker's-dozen beat cycle
   -------------------------------------------------------------------------- */

:where(html[data-spw-playing="on"]) {
  --spw-ecology-beat-align: calc(0.18 + (var(--spw-freshness-weight, 0.62) * 0.42));
}

:where(html[data-spw-playing="on"][data-spw-beat="1"]) {
  --spw-ecology-beat-align: calc(0.34 + (var(--spw-freshness-weight, 0.62) * 0.48));
}

:where(html[data-spw-playing="on"][data-spw-beat="5"]),
:where(html[data-spw-playing="on"][data-spw-beat="9"]),
:where(html[data-spw-playing="on"][data-spw-beat="13"]) {
  --spw-ecology-beat-align: calc(0.52 + (var(--spw-freshness-weight, 0.62) * 0.38));
  --spw-ecology-twinkle: max(var(--spw-ecology-twinkle, 0), calc(0.22 * var(--spw-freshness-weight, 0.62)));
}

:where(html[data-spw-freshness-pulse]) {
  --spw-microinteraction-pulse-scale: calc(1 + (0.018 * var(--spw-microinteraction-pulse-intensity, 1) * var(--spw-freshness-weight, 0.62)));
  --spw-ecology-twinkle: max(var(--spw-ecology-twinkle, 0), calc(0.34 * var(--spw-freshness-weight, 0.62)));
  transition:
    --spw-microinteraction-pulse-scale var(--spw-microinteraction-pulse-duration, 280ms) var(--ease-settle, ease),
    --spw-ecology-twinkle var(--spw-microinteraction-pulse-duration, 280ms) var(--ease-settle, ease);
}

:where(html[data-spw-freshness-pulse="beat-prime"]) {
  --spw-salience-weight: max(var(--spw-salience-weight, 0.34), calc(0.48 + (var(--spw-freshness-weight, 0.62) * 0.22)));
}

:where(html[data-spw-freshness-pulse^="phase-"]) {
  --spw-interaction-phase-weight: max(
    var(--spw-interaction-phase-weight, 0),
    calc(0.28 + (var(--spw-freshness-weight, 0.62) * 0.24))
  );
}

:where(html[data-spw-freshness-pulse="component-lifecycle"]) {
  --spw-interaction-loop-preview: 1;
}

:where(html[data-spw-freshness-pulse="settings-tuning"]) {
  --spw-site-rhythm-density: max(var(--spw-site-rhythm-density, 0.5), calc(0.62 + (var(--spw-freshness-weight, 0.62) * 0.28)));
}

:where(html[data-spw-freshness-pulse] :where(
  .operator-chip,
  [data-spw-operator],
  [data-spw-interaction-contract],
  [data-spw-gesture-contract],
  .frame-card,
  [data-spw-component-genome]
)) {
  transition:
    box-shadow var(--spw-microinteraction-pulse-duration, 280ms) var(--ease-settle, ease),
    border-color var(--spw-microinteraction-pulse-duration, 280ms) var(--ease-settle, ease),
    transform var(--spw-microinteraction-pulse-duration, 280ms) var(--ease-settle, ease);
}

:where(html[data-spw-freshness-pulse="beat-prime"] :where(.operator-chip, [data-spw-operator])) {
  box-shadow:
    var(--spw-local-shadow, none),
    0 0 0 1px color-mix(in srgb, var(--spw-operator-color, var(--active-op-color)) calc(14% + (var(--spw-freshness-weight, 0.62) * 10%)), transparent);
}

:where(html[data-spw-freshness-pulse="settings-tuning"] :where(.spw-site-rhythm__node, [data-spw-ornament="site-rhythm"] .spw-site-rhythm__node)) {
  transform: scale(calc(1 + (0.06 * var(--spw-freshness-weight, 0.62))));
}

:where(html[data-spw-reduce-motion="on"][data-spw-playing="on"]),
:where(html[data-spw-reduce-motion="on"][data-spw-freshness-pulse]) {
  --spw-ecology-beat-align: 0;
  --spw-ecology-twinkle: 0;
}
}

/* /public/css/systems/scroll-gesture.css */
@layer systems {
/* ==========================================================================
   scroll-gesture.css
   --------------------------------------------------------------------------
   Seamless vertical scroll with horizontal swipe reserved for lens/progression.
   ========================================================================== */

@media (prefers-reduced-motion: no-preference) {
  :where(html) {
    scroll-behavior: smooth;
  }
}

:where(html, body, main) {
  overscroll-behavior-y: none;
}

:where(main) {
  scroll-padding-top: calc(var(--shell-header-height, var(--header-height, 4rem)) + 0.75rem);
}

:where(
  .topic-photo-card,
  .image-study,
  [data-spw-image-discovery],
  [data-spw-image-reward],
  .spw-visual-link-card,
  .frame-card--illustrated a
) {
  touch-action: pan-y pinch-zoom;
}

:where([data-spw-gesture-contract*="swipe"]) {
  -webkit-user-select: none;
  user-select: none;
}

:where([data-spw-scroll-rail], .spw-visual-link-board__grid, .frame-grid--media) {
  scroll-snap-type: x proximity;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scrollbar-gutter: stable;
}

:where([data-spw-scroll-rail] > *, .spw-visual-link-board__grid > *, .frame-grid--media > *) {
  scroll-snap-align: start;
}
}

/* /public/css/systems/spatial-gravity.css */
@layer systems {
/* ==========================================================================
 * spatial-gravity.css
 * --------------------------------------------------------------------------
 * The visible + functional half of runtime/spatial-gravity.js. Opt-in via
 * [data-spw-gravity]; the runtime writes edge/vertical gravity, extent, and a
 * proximity custom property, and these rules turn that into behavior you can
 * feel: expansions open toward room, and the nearest viewport edge announces
 * itself as you scroll.
 *
 * This grounds the conceptual #cognitive_gravity_planes in real geometry —
 * "down" stops being a metaphor and becomes a measured pull the component
 * responds to. Ungated so any surface can opt a component in.
 * ========================================================================== */

[data-spw-gravity] {
    --spw-edge-proximity: 0;
    --spw-proximity-top: 0;
    --spw-proximity-bottom: 0;
    --spw-proximity-left: 0;
    --spw-proximity-right: 0;
    --spw-vertical-bias: 0;
    --spw-horizontal-bias: 0;
}

/* ─── Edge proximity: feel each edge independently ──────────────────────── */
/*
 * Four inset shadows, one per side, each faded by that side's proximity
 * (0..1). A component in a corner lights up two sides at once. The point is
 * legibility: nearing an edge should tell you the edge is shaping the
 * component, not silently clip it. Corner-aware, so it works with the
 * two-axis edge gravity (top-left, bottom-right, …).
 */

/* Establish a positioning context for the edge-glow ::after — but never on
   chrome that already positions itself (fixed/absolute floating chrome), since
   this rule lives in a later cascade layer and would otherwise override the
   author's position and drop the element out of its anchor. Fixed/absolute
   already form a containing block, so the ::after still anchors correctly. */
[data-spw-gravity]:not([data-spw-edge-gravity="none"]):not([data-spw-floating-chrome="true"]) {
    position: relative;
}

[data-spw-gravity]:not([data-spw-edge-gravity="none"])::after {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    border-radius: inherit;
    box-shadow:
        inset 0 3px 0 -1px color-mix(in srgb, var(--active-op-color, #008080) calc(var(--spw-proximity-top, 0) * 70%), transparent),
        inset 0 -3px 0 -1px color-mix(in srgb, var(--active-op-color, #008080) calc(var(--spw-proximity-bottom, 0) * 70%), transparent),
        inset 3px 0 0 -1px color-mix(in srgb, var(--active-op-color, #008080) calc(var(--spw-proximity-left, 0) * 70%), transparent),
        inset -3px 0 0 -1px color-mix(in srgb, var(--active-op-color, #008080) calc(var(--spw-proximity-right, 0) * 70%), transparent);
    transition: box-shadow var(--duration-base, 200ms) var(--ease-smooth, ease);
}

/* ─── Opportunistic opening direction ───────────────────────────────────── */
/*
 * data-spw-gravity="open" panels grow toward the roomier side. The runtime
 * sets data-spw-open-direction from vertical gravity; CSS anchors the reveal
 * so an expansion near the bottom of the frame opens upward instead of off
 * the edge. Content order stays in DOM; only the visual growth flips.
 */

[data-spw-gravity="open"] {
    display: flex;
    flex-direction: column;
}

[data-spw-gravity="open"] [data-spw-gravity-reveal] {
    transform-origin: top center;
    transition:
        max-height var(--duration-base, 200ms) var(--ease-smooth, ease),
        opacity var(--duration-fast, 120ms) var(--ease-mechanical, ease);
}

[data-spw-gravity="open"][data-spw-open-direction="up"] {
    flex-direction: column-reverse;
}

[data-spw-gravity="open"][data-spw-open-direction="up"] [data-spw-gravity-reveal] {
    transform-origin: bottom center;
}

/* 2D anchor: horizontal alignment for popover-shaped reveals. The reveal aligns
   to whichever inline side has room (start/end), and its height caps to the room
   available in the opening direction so it never overflows the viewport. */
[data-spw-gravity="open"] [data-spw-gravity-reveal] {
    align-self: stretch;
    max-block-size: none;
}

[data-spw-gravity="open"][data-spw-open-anchor$="-start"] [data-spw-gravity-reveal] {
    align-self: start;
}

[data-spw-gravity="open"][data-spw-open-anchor$="-end"] [data-spw-gravity-reveal] {
    align-self: end;
}

/* Measured room caps the reveal so it never overflows the viewport. A consumer
   can also impose a content ceiling with --spw-gravity-reveal-max (e.g. a dock
   that should scroll a large collection rather than fill the whole column); the
   reveal then grows to the smaller of measured room and that ceiling. */
[data-spw-gravity="open"][data-spw-open-direction="down"] [data-spw-gravity-reveal] {
    max-block-size: min(var(--spw-room-below, 100vh), var(--spw-gravity-reveal-max, 100vh));
    overflow: auto;
}

[data-spw-gravity="open"][data-spw-open-direction="up"] [data-spw-gravity-reveal] {
    max-block-size: min(var(--spw-room-above, 100vh), var(--spw-gravity-reveal-max, 100vh));
    overflow: auto;
}

/* ─── Extent: height band affects internal packing ──────────────────────── */
/*
 * Extent is the block-axis counterpart of measure. A tall specimen can afford
 * generous internal rhythm; an overtall one should tighten so it does not
 * force the reader into a long scroll for a single component.
 */

[data-spw-gravity][data-spw-extent="squat"] {
    --spw-gravity-rhythm: var(--space-xs, 0.5rem);
}
[data-spw-gravity][data-spw-extent="contained"] {
    --spw-gravity-rhythm: var(--space-sm, 0.75rem);
}
[data-spw-gravity][data-spw-extent="tall"] {
    --spw-gravity-rhythm: var(--space-md, 1rem);
}
[data-spw-gravity][data-spw-extent="overtall"] {
    --spw-gravity-rhythm: var(--space-xs, 0.5rem);
}

/* ─── Seating: flush vs inset ───────────────────────────────────────────── */
/*
 * Flushness encodes belonging. data-spw-seating declares it instead of leaving
 * it to ad-hoc margins:
 *   flush-viewport — full-bleed to the viewport edge (chrome that frames all).
 *   flush-host     — flush to the containing surface, no gap from its edge.
 *   inset          — holds a gutter; never touches the boundary (reading content).
 */

[data-spw-seating="flush-viewport"] {
    margin-inline: calc(50% - 50vw);
    max-width: 100vw;
    border-radius: 0;
}

[data-spw-seating="flush-host"] {
    margin: 0;
    border-radius: inherit;
}

[data-spw-seating="inset"] {
    margin-inline: auto;
    max-width: min(100%, var(--measure-reading, 68ch));
}

/* ─── Boundary overlap: the yielded layer demotes visibly ───────────────── */
/*
 * When runtime/spatial-gravity.js marks a lower-salience element as yielded in
 * a boundary contest, it recedes — quieter, desaturated, non-interactive on the
 * contested frame — rather than clipping silently. The winner is untouched.
 */

[data-spw-yielded="true"] {
    opacity: 0.55;
    filter: saturate(0.7);
    transition:
        opacity var(--duration-base, 200ms) var(--ease-smooth, ease),
        filter var(--duration-base, 200ms) var(--ease-smooth, ease);
}

[data-spw-yielded="true"]::before {
    content: attr(data-spw-yield-reason);
    position: absolute;
    inset-block-start: 0.25rem;
    inset-inline-end: 0.4rem;
    font-family: var(--site-mono-font, 'JetBrains Mono', monospace);
    font-size: var(--text-size-2xs, 0.62rem);
    color: var(--ink-soft, rgba(14, 18, 20, 0.5));
    pointer-events: none;
}

/* Salience as a resting emphasis, independent of density. */
[data-spw-salience="focal"] { --spw-salience-weight: 1; }
[data-spw-salience="ambient"] { --spw-salience-weight: 0.5; }
[data-spw-salience="background"] { --spw-salience-weight: 0.25; opacity: 0.82; }

/* ─── Gravity readout (resonance) ───────────────────────────────────────── */
/*
 * When a component carries a [data-spw-gravity-readout] child, it mirrors the
 * live state so scrolling the specimen visibly narrates its own gravity. This
 * is the "interacting clarifies the concept" surface.
 */

[data-spw-gravity-readout] {
    font-family: var(--site-mono-font, 'JetBrains Mono', monospace);
    font-size: var(--text-size-xs, 0.72rem);
    letter-spacing: 0.02em;
    color: var(--ink-soft, rgba(14, 18, 20, 0.68));
    display: inline-flex;
    gap: 0.5rem;
    flex-wrap: wrap;
}

[data-spw-gravity-readout] b {
    font-weight: 700;
    color: var(--active-op-color, #008080);
}

@media (prefers-reduced-motion: reduce) {
    [data-spw-gravity]:not([data-spw-edge-gravity="none"])::after,
    [data-spw-gravity="open"] [data-spw-gravity-reveal] {
        transition: none;
    }
}

/* ─── Composition-lab bench (demonstration surface) ─────────────────────── */
/*
 * Minimal layout for the /design/composition/ gravity bench. Specimens are
 * spaced far apart so scrolling moves each one through the viewport and its
 * vertical gravity visibly flips.
 */

.spatial-gravity-bench {
    display: grid;
    /* Enough vertical travel that each specimen moves through different
       viewport positions as you scroll (so its gravity visibly flips) without
       opening a blank void. */
    gap: clamp(2rem, 22vh, 12rem);
    margin-top: var(--space-md, 1rem);
}

.spatial-gravity-specimen {
    padding: var(--gravity-rhythm, var(--spw-gravity-rhythm, 1rem)) var(--space-md, 1rem);
    border: 1px solid var(--line, rgba(14, 18, 20, 0.14));
    border-radius: var(--shape-surface, 10px);
    background: var(--surface-strong, #ffffff);
    display: flex;
    flex-direction: column;
    gap: var(--spw-gravity-rhythm, var(--space-sm, 0.75rem));
}

.spatial-gravity-status {
    margin: 0;
}

.spatial-gravity-reveal {
    padding: var(--space-sm, 0.75rem);
    border-radius: var(--shape-component, 8px);
    background: color-mix(in srgb, var(--active-op-color, #008080) 8%, var(--surface, #ffffff));
    border: 1px dashed color-mix(in srgb, var(--active-op-color, #008080) 30%, transparent);
}

.spatial-gravity-reveal strong {
    color: var(--active-op-color, #008080);
}

.spatial-gravity-subhead {
    margin-top: var(--space-lg, 1.5rem);
}

/* Overlap demo: two cards deliberately share space so the salience contest is
   visible at rest (no scroll needed). */
.spatial-gravity-overlap {
    position: relative;
    min-height: 12rem;
    margin-top: var(--space-md, 1rem);
}

.spatial-gravity-overlap .spatial-gravity-contender {
    position: absolute;
    width: min(60%, 20rem);
    padding: var(--space-sm, 0.75rem) var(--space-md, 1rem);
    border: 1px solid var(--line, rgba(14, 18, 20, 0.14));
    border-radius: var(--shape-surface, 10px);
    background: var(--surface-strong, #ffffff);
}

.spatial-gravity-contender--ambient {
    inset-block-start: 0;
    inset-inline-start: 0;
}

.spatial-gravity-contender--focal {
    inset-block-start: 3.5rem;
    inset-inline-start: 30%;
    border-color: color-mix(in srgb, var(--active-op-color, #008080) 40%, var(--line, rgba(14, 18, 20, 0.14)));
}
}

/* /public/css/systems/component-packing.css */
@layer systems {
/* ==========================================================================
 * component-packing.css
 * --------------------------------------------------------------------------
 * Component-local layout: a card arranges its OWN regions by its own inline
 * size, not the viewport. This is the container-relative counterpart to
 * spatial-gravity.css (which is viewport-relative): outer gravity says where a
 * card sits; inner packing says how the card arranges itself. Both are
 * first-class, and a card in a narrow column packs the same way whether that
 * column is on a phone or a sidebar on a wide screen — because it reads its
 * container, not the screen.
 *
 * Native + framework-free on purpose (container queries + :has), so it doubles
 * as a legible reference. The box model mirrors the resolved variant into
 * data-spw-pack-layout / data-spw-pack-fill for inspection + JS consumers.
 * ========================================================================== */

/* Opt in: the card becomes an inline-size container; its region grid responds
   to the card's width. Breakpoints mirror composition-box-model MEASURE_BANDS
   so the inspectable attribute and the CSS agree. */
[data-spw-pack-local] {
    container: spw-pack / inline-size;
}

[data-spw-pack-regions] {
    display: grid;
    gap: var(--spw-pack-gap, var(--space-sm, 0.75rem));
    grid-template-areas:
        "media"
        "body"
        "actions";
}

[data-spw-pack-region="media"] { grid-area: media; min-inline-size: 0; }
[data-spw-pack-region="body"] { grid-area: body; min-inline-size: 0; }
[data-spw-pack-region="actions"] { grid-area: actions; min-inline-size: 0; }

/* Split: media seats beside body once the card itself is wide enough. */
@container spw-pack (min-width: 26rem) {
    [data-spw-pack-regions] {
        grid-template-columns: minmax(7rem, 1fr) minmax(0, 1.7fr);
        grid-template-areas:
            "media body"
            "media actions";
        align-items: start;
    }
}

/* Feature: three lanes when the card has room to spread. */
@container spw-pack (min-width: 44rem) {
    [data-spw-pack-regions] {
        grid-template-columns: minmax(7rem, 1fr) minmax(0, 2fr) minmax(6rem, auto);
        grid-template-areas: "media body actions";
        align-items: center;
    }
}

/* Content-count awareness (the other packing axis). A card holding many items
   tightens its rhythm regardless of width — :has counts without JS. */
[data-spw-pack-regions]:has(> [data-spw-pack-region] > :nth-child(6)) {
    --spw-pack-gap: var(--space-xs, 0.5rem);
}

/* Density from the box model's content tone: dense/operator-heavy content packs
   tighter, long-form content breathes. Orthogonal to the width axis above. */
[data-spw-pack-local][data-spw-content-tone="dense"],
[data-spw-pack-local][data-spw-content-tone="operator-heavy"] {
    --spw-pack-gap: var(--space-xs, 0.5rem);
}

[data-spw-pack-local][data-spw-content-tone="text-long"] {
    --spw-pack-gap: var(--space-md, 1rem);
}

/* Inspectable fill band (written by composition-box-model) can also drive
   packing when :has is unavailable. */
[data-spw-pack-local][data-spw-pack-fill="full"] {
    --spw-pack-gap: var(--space-xs, 0.5rem);
}

@media (prefers-reduced-motion: no-preference) {
    [data-spw-pack-regions] {
        transition: gap var(--duration-base, 200ms) var(--ease-smooth, ease);
    }
}

/* ─── Composition-lab demo ──────────────────────────────────────────────── */
/*
 * A user-resizable wrapper so the card's OWN width changes independent of the
 * viewport — the clearest way to feel component-local (container) packing.
 */
.pack-demo-resizer {
    resize: horizontal;
    overflow: auto;
    min-inline-size: 14rem;
    max-inline-size: 100%;
    inline-size: 100%;
    padding-block-end: var(--space-xs, 0.5rem);
    border-inline-start: 2px solid color-mix(in srgb, var(--active-op-color, #008080) 30%, transparent);
    padding-inline-start: var(--space-sm, 0.75rem);
}

.pack-card {
    padding: var(--space-md, 1rem);
}

.pack-card__media {
    display: grid;
    place-items: center;
    min-block-size: 4rem;
    border-radius: var(--shape-component, 8px);
    background: color-mix(in srgb, var(--active-op-color, #008080) 12%, var(--surface, #ffffff));
    color: var(--active-op-color, #008080);
}

.pack-card__thumb {
    font-family: var(--site-mono-font, 'JetBrains Mono', monospace);
    font-size: var(--text-size-xs, 0.72rem);
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

.pack-card__body h4 {
    margin: 0 0 0.35rem;
}

.pack-card__actions {
    display: flex;
    gap: var(--space-2xs, 0.36rem);
    flex-wrap: wrap;
    align-content: start;
}
}

/* /public/css/systems/print-precipitation.css */
@layer systems {
/* ==========================================================================
   print-precipitation.css
   --------------------------------------------------------------------------
   Print and condensation surfaces for Spw projection / precipitation requests.
   ========================================================================== */

:where(html[data-spw-print-ready="true"], html[data-spw-precipitation-mode="screenshot"]) {
  --spw-semantic-density-factor: max(var(--spw-semantic-density-factor, 0.42), 0.88);
  --spw-image-interaction-lift: 1;
  --spw-image-interaction-duration: 1ms;
}

:where(html[data-spw-condense-tier="brief"]) :where(
  .frame-note,
  .spw-card-reason,
  .hook-sub,
  details.spw-card-reason
) {
  display: none;
}

:where(html[data-spw-condense-tier="card"]) :where(
  .site-header,
  .site-footer,
  .spw-section-handle,
  .frame-operators
) {
  opacity: 0.72;
}

:where(html[data-spw-precipitation-mode="condensed"]) :where(.study-summary .spw-image-lens-hint) {
  font-size: var(--text-size-2xs, 0.64rem);
}

@media print {
  :where(
    .site-header,
    .site-footer,
    .spw-section-handle,
    .skip-link,
    [data-spw-floating-chrome="true"],
    .frame-operators,
    nav.frame-operators
  ) {
    display: none !important;
  }

  :where(html, body) {
    background: white !important;
    color: black !important;
  }

  :where(main, article, .site-frame) {
    break-inside: avoid-page;
    box-shadow: none !important;
  }

  :where(.topic-photo-card, .image-study, [data-spw-image-discovery]) {
    break-inside: avoid;
    border: 1px solid #ccc !important;
    box-shadow: none !important;
    page-break-inside: avoid;
  }

  :where(.study-summary) {
    color: #222 !important;
  }

  :where(html[data-spw-condense-tier="brief"]) :where(.frame-note, details, .hook-sub) {
    display: none !important;
  }

  :where(a[href^="http"]::after) {
    content: " (" attr(href) ")";
    font-size: 0.75em;
  }
}
}

/* /public/css/systems/layout-postures.css */
@layer systems {
/* ==========================================================================
   layout-postures.css
   --------------------------------------------------------------------------
   Layout tuner + explore posture + packing parity from settings/query surfaces.
   ========================================================================== */

:root {
  --spw-layout-posture-weight: 0.5;
  --spw-layout-posture-measure-bias: 1;
  --spw-layout-posture-grid-bias: 1;
}

:where(html[data-spw-layout-tuner="reading"], body[data-spw-layout="reading"]) {
  --spw-real-estate-inline: var(--page-width-reading, 56rem);
  --spw-layout-posture-measure-bias: 0.92;
}

:where(html[data-spw-layout-tuner="newspaper"]) {
  --spw-real-estate-inline: var(--page-width-newspaper, 68rem);
  --spw-layout-posture-grid-bias: 1.08;
  --spw-grid-min-active: min(var(--spw-grid-min-active, 15rem), 11.25rem);
}

:where(html[data-spw-layout-tuner="wide"], body[data-spw-layout="wide"]) {
  --spw-real-estate-inline: var(--page-width-wide, 84rem);
  --spw-layout-posture-measure-bias: 1.04;
}

:where(html[data-spw-layout-tuner="atlas"], body[data-spw-layout="atlas"]) {
  --spw-real-estate-inline: var(--page-width-atlas, 96rem);
  --spw-layout-posture-measure-bias: 1.12;
  --spw-layout-posture-grid-bias: 1.14;
}

:where(html[data-spw-explore-posture="reading"], html[data-spw-layout-posture="reading"]) {
  --spw-layout-posture-weight: 0.34;
  --spw-variant-selection-weight: max(var(--spw-variant-selection-weight, 0), 0.38);
}

:where(html[data-spw-explore-posture="field"], html[data-spw-layout-posture="field"]) {
  --spw-layout-posture-weight: 0.62;
  --spw-layout-posture-grid-bias: 1.06;
  --spw-variant-selection-weight: max(var(--spw-variant-selection-weight, 0), 0.52);
}

:where(html[data-spw-explore-posture="workshop"], html[data-spw-layout-posture="workshop"]) {
  --spw-layout-posture-weight: 0.86;
  --spw-layout-posture-grid-bias: 1.12;
  --spw-variant-selection-weight: max(var(--spw-variant-selection-weight, 0), 0.68);
  --spw-tuning-discoverability: revealed;
}

:where(html[data-spw-packing-state="compact"], html[data-spw-component-density="dense"]) {
  --spw-pack-tier: compact;
}

:where(html[data-spw-packing-state="roomy"], html[data-spw-component-density="roomy"]) {
  --spw-pack-tier: roomy;
}

:where(main, [data-spw-page-role="content"]) {
  max-inline-size: min(100%, calc(var(--spw-real-estate-inline, 72rem) * var(--spw-layout-posture-measure-bias, 1)));
}

:where(
  .frame-grid,
  .craft-route-grid,
  .spw-visual-link-board__grid
) {
  gap: calc(var(--component-gap, 0.9rem) * var(--spw-layout-posture-grid-bias, 1));
}

:where([data-spw-variant-selected="true"]) {
  --spw-variant-selection-weight: 0.86;
  border-color: color-mix(
    in srgb,
    var(--spw-variant-accent, var(--active-op-color, var(--teal, #008080))) 34%,
    var(--line, transparent)
  );
}

:where([data-spw-component-variant-active]) {
  --spw-variant-selection-weight: max(var(--spw-variant-selection-weight, 0), 0.72);
}

:where(html[data-spw-query-parity="synced"]) {
  --spw-pre-state-visibility: max(var(--spw-pre-state-visibility, 0.5), 0.58);
}
}

/* /public/css/systems/effect-interpretation.css */
@layer systems {
/* ==========================================================================
   effect-interpretation.css
   --------------------------------------------------------------------------
   Visual layer for interpreting image lenses, interaction states, and cues.
   ========================================================================== */

:where(
  .topic-photo-card,
  .image-study,
  [data-spw-image-reward],
  [data-spw-image-discovery],
  .frame-card-media,
  [data-spw-image-surface]
) {
  --spw-effect-accent: var(--spw-image-lens-accent, var(--active-op-color, var(--teal, #008080)));
  --spw-effect-rail-opacity: 0;
}

:where(
  .topic-photo-card[data-spw-image-lens-active],
  .image-study[data-spw-image-lens-active],
  [data-spw-image-surface][data-spw-image-lens-active],
  .frame-card-media[data-spw-image-lens-active]
)::before {
  content: "";
  position: absolute;
  inset: 0 auto auto 0;
  inline-size: 100%;
  block-size: 3px;
  border-radius: var(--component-radius-tight, 8px) var(--component-radius-tight, 8px) 0 0;
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--spw-effect-accent) 72%, transparent),
    color-mix(in srgb, var(--spw-effect-accent) 28%, transparent)
  );
  opacity: calc(0.28 + (var(--spw-interaction-phase-weight, 0) * 0.42));
  pointer-events: none;
  z-index: 2;
  transition: opacity var(--spw-image-interaction-duration, 360ms) var(--spw-image-interaction-ease, ease);
}

:where(
  .topic-photo-card[data-spw-image-interaction-state="primed"],
  .image-study[data-spw-image-interaction-state="primed"],
  [data-spw-image-surface][data-spw-image-interaction-state="primed"]
)::before {
  --spw-effect-rail-opacity: 0.52;
  opacity: max(var(--spw-effect-rail-opacity), 0.52);
}

:where(
  .topic-photo-card[data-spw-image-interaction-state="inspecting"],
  .image-study[data-spw-image-interaction-state="inspecting"],
  [data-spw-image-surface][data-spw-image-interaction-state="inspecting"]
)::before {
  block-size: 4px;
  opacity: 0.78;
}

:where(
  .topic-photo-card[data-spw-image-interaction-state="discovered"],
  .image-study[data-spw-image-interaction-state="discovered"],
  [data-spw-image-discovery][data-spw-image-interaction-state="discovered"]
)::before {
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--spw-effect-accent) 88%, white 12%),
    color-mix(in srgb, var(--delight-color, var(--spw-effect-accent)) 42%, transparent)
  );
  opacity: 0.92;
}

:where(.spw-effect-state) {
  position: absolute;
  inset: 0.42rem 0.42rem auto auto;
  z-index: 3;
  padding: 0.16rem 0.46rem;
  border: 1px solid color-mix(in srgb, var(--spw-effect-accent) 34%, var(--line, transparent));
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface-strong, #fff) 88%, var(--spw-effect-accent) 12%);
  color: color-mix(in srgb, var(--ink, currentColor) 78%, var(--spw-effect-accent) 22%);
  font-family: var(--site-mono-font, "JetBrains Mono", monospace);
  font-size: var(--text-size-2xs, 0.68rem);
  font-weight: 700;
  letter-spacing: 0.02em;
  line-height: 1.2;
  pointer-events: none;
}

:where(.spw-effect-legend) {
  display: flex;
  flex-wrap: wrap;
  gap: 0.34rem;
  align-items: center;
}

:where(.spw-effect-chip) {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
  padding: 0.14rem 0.46rem;
  border: 1px solid color-mix(in srgb, var(--line, transparent) 82%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface-strong, #fff) 94%, var(--ink, #111) 6%);
  color: var(--ink-soft, rgba(14, 18, 20, 0.68));
  font-size: var(--text-size-2xs, 0.68rem);
  font-weight: 650;
  letter-spacing: 0.02em;
  line-height: 1.25;
  transition:
    border-color 180ms ease,
    background 180ms ease,
    color 180ms ease,
    box-shadow 180ms ease,
    transform 140ms ease;
}

:where(button.spw-effect-chip) {
  cursor: pointer;
  font: inherit;
  appearance: none;
}

:where(button.spw-effect-chip:hover),
:where(button.spw-effect-chip:focus-visible) {
