}

:where(.spw-effect-chip__capacity) {
  font-weight: 650;
}

:where(.spw-effect-chip[data-spw-operator="probe"]) { --spw-effect-chip-accent: var(--op-probe-color, #6a3fb8); }
:where(.spw-effect-chip[data-spw-operator="frame"]) { --spw-effect-chip-accent: var(--op-frame-color, #1a9999); }
:where(.spw-effect-chip[data-spw-operator="ref"]) { --spw-effect-chip-accent: var(--op-ref-color, #1d57a3); }
:where(.spw-effect-chip[data-spw-operator="object"]) { --spw-effect-chip-accent: var(--op-object-color, #c68a22); }
:where(.spw-effect-chip[data-spw-operator="integrate"]) { --spw-effect-chip-accent: var(--op-integrate-color, var(--teal, #008080)); }
:where(.spw-effect-chip[data-spw-operator="stream"]) { --spw-effect-chip-accent: var(--op-stream-color, #2a8c76); }
:where(.spw-effect-chip[data-spw-operator="route"]) { --spw-effect-chip-accent: var(--op-topic-color, #2e8b57); }
:where(.spw-effect-chip[data-spw-operator="potential"]) { --spw-effect-chip-accent: var(--op-probe-color, #6a3fb8); }
:where(.spw-effect-chip[data-spw-operator="baseline"]) { --spw-effect-chip-accent: var(--ink-soft, rgba(14, 18, 20, 0.68)); }
:where(.spw-effect-chip[data-spw-operator="surface"]) { --spw-effect-chip-accent: var(--op-surface-color, #355f77); }
:where(.spw-effect-chip[data-spw-operator="action"]) { --spw-effect-chip-accent: var(--op-action-color, #147a70); }

:where(.spw-effect-chip[aria-pressed="true"]) {
  border-color: color-mix(in srgb, var(--spw-effect-chip-accent, var(--spw-effect-accent)) 42%, var(--line, transparent));
  background: color-mix(in srgb, var(--surface-strong, #fff) 78%, var(--spw-effect-chip-accent, var(--spw-effect-accent)) 22%);
  color: color-mix(in srgb, var(--ink, currentColor) 70%, var(--spw-effect-chip-accent, var(--spw-effect-accent)) 30%);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--spw-effect-chip-accent, var(--spw-effect-accent)) 14%, transparent);
}

:where(
  .topic-photo-card[data-spw-image-lens-active="probe"] .spw-effect-chip[data-spw-lens-chip="probe"],
  .image-study[data-spw-image-lens-active="probe"] .spw-effect-chip[data-spw-lens-chip="probe"],
  .topic-photo-card[data-spw-image-lens-active="frame"] .spw-effect-chip[data-spw-lens-chip="frame"],
  .image-study[data-spw-image-lens-active="frame"] .spw-effect-chip[data-spw-lens-chip="frame"],
  .topic-photo-card[data-spw-image-lens-active="ref"] .spw-effect-chip[data-spw-lens-chip="ref"],
  .image-study[data-spw-image-lens-active="ref"] .spw-effect-chip[data-spw-lens-chip="ref"],
  .topic-photo-card[data-spw-image-lens-active="object"] .spw-effect-chip[data-spw-lens-chip="object"],
  .image-study[data-spw-image-lens-active="object"] .spw-effect-chip[data-spw-lens-chip="object"],
  .topic-photo-card[data-spw-image-lens-active="integrate"] .spw-effect-chip[data-spw-lens-chip="integrate"],
  .image-study[data-spw-image-lens-active="integrate"] .spw-effect-chip[data-spw-lens-chip="integrate"],
  .topic-photo-card[data-spw-image-lens-active="stream"] .spw-effect-chip[data-spw-lens-chip="stream"],
  .image-study[data-spw-image-lens-active="stream"] .spw-effect-chip[data-spw-lens-chip="stream"],
  .topic-photo-card[data-spw-image-lens-active="baseline"] .spw-effect-chip[data-spw-lens-chip="baseline"],
  .image-study[data-spw-image-lens-active="baseline"] .spw-effect-chip[data-spw-lens-chip="baseline"],
  .topic-photo-card[data-spw-image-lens-active="route"] .spw-effect-chip[data-spw-lens-chip="route"],
  .image-study[data-spw-image-lens-active="route"] .spw-effect-chip[data-spw-lens-chip="route"],
  .topic-photo-card[data-spw-image-lens-active="potential"] .spw-effect-chip[data-spw-lens-chip="potential"],
  .image-study[data-spw-image-lens-active="potential"] .spw-effect-chip[data-spw-lens-chip="potential"],
  .topic-photo-card[data-spw-image-lens-active="surface"] .spw-effect-chip[data-spw-lens-chip="surface"],
  .image-study[data-spw-image-lens-active="surface"] .spw-effect-chip[data-spw-lens-chip="surface"],
  .frame-card-media[data-spw-image-lens-active] .spw-effect-chip[aria-pressed="true"]
) {
  border-color: color-mix(in srgb, var(--spw-effect-chip-accent, var(--spw-effect-accent)) 42%, var(--line, transparent));
  background: color-mix(in srgb, var(--surface-strong, #fff) 78%, var(--spw-effect-chip-accent, var(--spw-effect-accent)) 22%);
  color: color-mix(in srgb, var(--ink, currentColor) 70%, var(--spw-effect-chip-accent, var(--spw-effect-accent)) 30%);
}

:where(.spw-effect-cues) {
