  line-height: 1.35;
}

:where(.study-summary) {
  gap: 0.48rem;
}

:where(.study-summary .meta-cluster .spec-pill[data-spw-effect-view]) {
  border-color: color-mix(in srgb, var(--spw-effect-accent) 28%, var(--line, transparent));
