/* /public/css/systems/film-scene-composition.css */
@layer systems {
/* ==========================================================================
   film-scene-composition.css
   Practice-bed staging for film scene composition with culinary metaphor lanes.
   ========================================================================== */

:where(.spw-scene-bed) {
  display: grid;
  gap: calc(0.85rem * var(--spw-medium-layout-gap-scale, 1));
}

:where(.spw-scene-bed__stage) {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.55rem;
  min-block-size: 11rem;
  padding: 0.72rem;
  border: 1px solid color-mix(in srgb, var(--line, transparent) 82%, transparent);
  border-radius: var(--component-radius, 12px);
  background:
    linear-gradient(
      165deg,
      color-mix(in srgb, var(--surface-strong, #fff) 92%, var(--active-op-color, var(--teal, #008080)) 8%),
      color-mix(in srgb, var(--surface-strong, #fff) 98%, var(--ink, #111) 2%)
    );
  overflow: hidden;
}

:where(.spw-scene-bed__lane) {
  display: grid;
  gap: 0.35rem;
  align-content: start;
  padding: var(--spw-medium-lane-pad, 0.55rem);
  min-block-size: var(--spw-medium-touch-min, 2.75rem);
  border-radius: var(--component-radius-tight, 8px);
  border: 1px dashed color-mix(in srgb, var(--line, transparent) 70%, transparent);
  background: color-mix(in srgb, var(--surface-strong, #fff) 88%, transparent);
  font-size: var(--text-size-xs, 0.82rem);
  line-height: 1.4;
}

:where(.spw-scene-bed__lane strong) {
  font-family: var(--site-mono-font, "JetBrains Mono", monospace);
  font-size: var(--text-size-2xs, 0.68rem);
  letter-spacing: 0.03em;
  text-transform: lowercase;
}

:where(.spw-scene-bed__lane[data-spw-scene-lane="focus"]) {
  border-style: solid;
  border-color: color-mix(in srgb, var(--active-op-color, var(--teal, #008080)) 28%, transparent);
  background: color-mix(in srgb, var(--surface-strong, #fff) 78%, var(--active-op-color, var(--teal, #008080)) 22%);
}

:where(.spw-culinary-ref-grid) {
  display: grid;
  gap: 0.55rem;
}

@media (min-width: 48rem) {
  :where(.spw-culinary-ref-grid) {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

:where(.spw-culinary-ref) {
  display: grid;
  gap: 0.28rem;
  padding: 0.62rem 0.72rem;
  border-radius: var(--component-radius-tight, 8px);
  border: 1px solid color-mix(in srgb, var(--line, transparent) 78%, transparent);
  background: color-mix(in srgb, var(--surface-strong, #fff) 94%, var(--ink, #111) 6%);
  font-size: var(--text-size-xs, 0.82rem);
  line-height: 1.45;
}

:where(.spw-culinary-ref__kitchen) {
  color: color-mix(in srgb, var(--op-object-color, #c68a22) 72%, var(--ink, currentColor) 28%);
  font-weight: 650;
}

:where(.spw-culinary-ref__film) {
  color: color-mix(in srgb, var(--op-frame-color, #1a9999) 72%, var(--ink, currentColor) 28%);
  font-weight: 650;
}

:where(.spw-scene-bed[data-spw-scene-posture="mise"] .spw-scene-bed__stage) {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--op-object-color, #c68a22) 14%, transparent);
}

:where(.spw-scene-bed[data-spw-scene-posture="reduction"] .spw-scene-bed__stage) {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--op-stream-color, #2a8c76) 18%, transparent);
}

:where(.spw-scene-bed[data-spw-scene-posture="ferment"] .spw-scene-bed__stage) {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--op-probe-color, #6a3fb8) 16%, transparent);
}

:where(html[data-spw-reduce-motion="on"]) :where(.spw-scene-bed__stage) {
  transition: none;
}
}

/* /public/css/systems/scene-interaction.css */
@layer systems {
/* ==========================================================================
   scene-interaction.css
   --------------------------------------------------------------------------
   Interactive scene beds: lane focus, image coupling, local memory strip.
   ========================================================================== */

:root {
  --spw-scene-lane-active-strength: 0;
  --spw-scene-image-coupling: var(--spw-medium-scene-coupling, 0.42);
}

:where(.spw-scene-bed[data-spw-scene-interactive]) {
  --spw-scene-lane-active-strength: 0.55;
}

:where(.spw-scene-bed__layout) {
  display: grid;
  gap: calc(0.85rem * var(--spw-medium-layout-gap-scale, 1));
}

@media (min-width: 52rem) {
  :where(.spw-scene-bed__layout:has(.spw-scene-bed__figure)) {
    grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
    align-items: start;
  }

  :where(.spw-scene-bed__layout:has(.spw-scene-bed__figure)) .spw-scene-bed__stage {
    grid-column: 2;
    grid-row: 1 / span 2;
  }

  :where(.spw-scene-bed__layout:has(.spw-scene-bed__figure)) .spw-scene-memory {
    grid-column: 1;
  }
}

:where(.spw-scene-bed__figure) {
  margin: 0;
}

:where(.spw-scene-bed__figure[data-spw-scene-image-active="off"]) {
  opacity: 0.72;
  filter: saturate(0.88);
}

:where(.spw-scene-bed__figure[data-spw-scene-image-active="on"]) {
  opacity: 1;
  --spw-image-interaction-scale: 1.02;
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--spw-image-lens-accent, var(--active-op-color, #008080)) 24%, transparent),
    0 14px 28px color-mix(in srgb, var(--shadow, #000) 8%, transparent);
}

:where(.spw-scene-bed__lane) {
  cursor: pointer;
  min-block-size: var(--spw-medium-touch-min, 2.75rem);
  padding: var(--spw-medium-lane-pad, 0.55rem);
  transition:
    border-color var(--spw-wonder-duration-base, 200ms) var(--spw-wonder-ease-settle, ease),
    background-color var(--spw-wonder-duration-base, 200ms) var(--spw-wonder-ease-settle, ease),
    transform var(--spw-wonder-duration-fast, 120ms) var(--spw-wonder-ease-settle, ease),
    box-shadow var(--spw-wonder-duration-base, 200ms) var(--spw-wonder-ease-settle, ease);
}

:where(.spw-scene-bed__lane:hover, .spw-scene-bed__lane:focus-visible) {
  border-color: color-mix(
    in srgb,
    var(--active-op-color, #008080) calc(28% + (var(--spw-medium-accent-weight, 1) * 6%)),
    transparent
  );
}

:where(html[data-spw-hover-mode="hover"]) :where(.spw-scene-bed__lane:hover, .spw-scene-bed__lane:focus-visible) {
  transform: translateY(calc(var(--spw-medium-hover-lift, 1px) * -1));
}

:where(.spw-scene-bed__lane[data-spw-scene-lane-active="true"]) {
  border-style: solid;
  border-color: color-mix(
    in srgb,
    var(--active-op-color, #008080) calc(34% + (var(--spw-scene-lane-active-strength) * 22%)),
    transparent
  );
  background: color-mix(
    in srgb,
    var(--surface-strong, #fff) 72%,
    var(--active-op-color, #008080) 28%
  );
  box-shadow:
    inset 3px 0 0 color-mix(in srgb, var(--op-probe-color, #6a3fb8) 55%, transparent),
    0 8px 18px color-mix(in srgb, var(--shadow, #000) 5%, transparent);
}

:where(.spw-scene-bed__lane[data-spw-scene-lane-active="true"] strong) {
  color: color-mix(in srgb, var(--active-op-color, #008080) 78%, var(--ink, currentColor) 22%);
}

:where(.spw-scene-memory) {
  display: grid;
  gap: 0.2rem;
  margin: 0;
  padding: 0.5rem 0.62rem;
  border-radius: var(--component-radius-tight, 8px);
  border: 1px dashed color-mix(in srgb, var(--line, transparent) 72%, transparent);
  background: color-mix(in srgb, var(--surface-strong, #fff) 94%, var(--active-op-color, #008080) 6%);
  font-size: var(--text-size-2xs, 0.68rem);
  line-height: 1.45;
}

:where(.spw-scene-memory__label) {
  font-family: var(--site-mono-font, "JetBrains Mono", monospace);
  letter-spacing: 0.04em;
  text-transform: lowercase;
  color: color-mix(in srgb, var(--ink-soft, currentColor) 72%, transparent);
}

:where(.spw-scene-memory code) {
  font-family: var(--site-mono-font, "JetBrains Mono", monospace);
  font-size: 0.72rem;
  color: color-mix(in srgb, var(--op-ref-color, #1d57a3) 70%, var(--ink, currentColor) 30%);
}

:where([data-spw-scene-local-state="active"] .spw-scene-bed__figure[data-spw-scene-image-active="on"]) {
  animation: spw-scene-image-couple var(--spw-wonder-duration-deliberate, 420ms) var(--spw-wonder-ease-settle, ease) both;
}

@keyframes spw-scene-image-couple {
  from {
    opacity: 0.7;
    transform: translateY(6px) scale(0.992);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1.02);
  }
}

@media (prefers-reduced-motion: reduce) {
  :where(.spw-scene-bed__lane),
  :where(.spw-scene-bed__figure[data-spw-scene-image-active="on"]) {
    transition: none;
    animation: none;
    transform: none;
  }
}
}

/* /public/css/systems/substrate-ecology.css */
@layer systems {
/* ==========================================================================
   substrate-ecology.css
   --------------------------------------------------------------------------
   Purpose
   - Shared ecological contract for Spw surfaces.
   - Defines context, room, permeability, succession, and field-state tokens
     that other surface files can consume.
   - Keeps memo seams, helper seams, and environmental response generic enough
     to work across cards, labs, settings, figures, navigator, and console.

   Design rules
   - Surface ecology should be composable and medium-agnostic.
   - Local field state should feel environmental, not gimmicky.
   - Room-aware seams should appear only when the substrate has enough space.
   - This file sets contracts; feature shells consume them.
   ========================================================================== */

/* ==========================================================================
   1. Root ecology tokens
   ========================================================================== */

:root {
  --spw-surface-clarity: 0.62;
  --spw-surface-pressure: 0.34;
  --spw-surface-atmosphere: 0.18;
  --spw-surface-permeability: 0.3;
  --spw-surface-memory: 0.16;
  --spw-surface-resonance: 0.18;

  --spw-surface-room-scale: 1;
  --spw-surface-seam-opacity: 0.72;
  --spw-surface-seam-gap: var(--space-xs, 0.5rem);
  --spw-surface-seam-radius: var(--shape-surface, 10px);

  --spw-field-charge: 0;
  --spw-field-orientation: 0;
  --spw-field-inquiry: 0;
  --spw-field-comparison: 0;
  --spw-field-memory: 0;
  --spw-field-projection: 0;
  --spw-field-constraint: 0;
  --spw-field-resonance: 0;
}

/* ==========================================================================
   2. Generic ecology hosts
   ========================================================================== */

:where(
  [data-spw-surface-kind],
  .site-frame,
  .frame-card,
  .frame-panel,
  .mode-panel,
  .operator-card,
  .media-card,
  .media-focus-card,
  .pretext-surface,
  .settings-category,
  .settings-fieldset,
  .spw-console,
  .spw-nav-panel
) {
  /* Debug / inspection */
  --spw-debug-layer-owner: "systems";
  --spw-debug-layer-color: #008080;

  /* Local tokens */
  --spw-surface-local-clarity: var(--spw-surface-clarity, 0.62);
  --spw-surface-local-pressure: var(--spw-surface-pressure, 0.34);
  --spw-surface-local-atmosphere: var(--spw-surface-atmosphere, 0.18);
  --spw-surface-local-permeability: var(--spw-surface-permeability, 0.3);
  --spw-surface-local-memory: var(--spw-surface-memory, 0.16);
  --spw-surface-local-resonance: var(--spw-surface-resonance, 0.18);

  /* Box */
  min-width: 0;

  /* Layering / containment */
  position: relative;
}

/* ==========================================================================
   3. Context routing
   --------------------------------------------------------------------------
   reading | analysis | routing | ritual | play | settings | publishing
   ========================================================================== */

:where([data-spw-context='reading']) {
  --spw-surface-local-clarity: 0.82;
  --spw-surface-local-pressure: 0.22;
  --spw-surface-local-atmosphere: 0.08;
  --spw-surface-local-permeability: 0.24;
}

:where([data-spw-context='analysis']) {
  --spw-surface-local-clarity: 0.76;
  --spw-surface-local-pressure: 0.48;
  --spw-surface-local-atmosphere: 0.14;
  --spw-surface-local-permeability: 0.38;
}

:where([data-spw-context='routing']) {
  --spw-surface-local-clarity: 0.68;
  --spw-surface-local-pressure: 0.54;
  --spw-surface-local-atmosphere: 0.12;
  --spw-surface-local-permeability: 0.34;
}

:where([data-spw-context='ritual']) {
  --spw-surface-local-clarity: 0.52;
  --spw-surface-local-pressure: 0.56;
  --spw-surface-local-atmosphere: 0.34;
  --spw-surface-local-permeability: 0.42;
}

:where([data-spw-context='play']) {
  --spw-surface-local-clarity: 0.58;
  --spw-surface-local-pressure: 0.42;
  --spw-surface-local-atmosphere: 0.28;
  --spw-surface-local-permeability: 0.46;
}

:where([data-spw-context='settings']) {
  --spw-surface-local-clarity: 0.84;
  --spw-surface-local-pressure: 0.24;
  --spw-surface-local-atmosphere: 0.06;
  --spw-surface-local-permeability: 0.18;
}

:where([data-spw-context='publishing']) {
  --spw-surface-local-clarity: 0.74;
  --spw-surface-local-pressure: 0.32;
  --spw-surface-local-atmosphere: 0.16;
  --spw-surface-local-permeability: 0.28;
}

/* ==========================================================================
   4. Room routing
   --------------------------------------------------------------------------
   compact | standard | roomy
   ========================================================================== */

:where([data-spw-room='compact']) {
  --spw-surface-room-scale: 0.82;
  --spw-surface-seam-opacity: 0.58;
}

:where([data-spw-room='standard']) {
  --spw-surface-room-scale: 1;
  --spw-surface-seam-opacity: 0.72;
}

:where([data-spw-room='roomy']) {
  --spw-surface-room-scale: 1.14;
  --spw-surface-seam-opacity: 0.86;
}

/* ==========================================================================
   5. Permeability routing
   --------------------------------------------------------------------------
   sealed | porous | annotatable | mutable
   ========================================================================== */

:where([data-spw-permeability='sealed']) {
  --spw-surface-local-permeability: 0.08;
}

:where([data-spw-permeability='porous']) {
  --spw-surface-local-permeability: 0.34;
}

:where([data-spw-permeability='annotatable']) {
  --spw-surface-local-permeability: 0.52;
}

:where([data-spw-permeability='mutable']) {
  --spw-surface-local-permeability: 0.68;
}

/* ==========================================================================
   6. Succession routing
   --------------------------------------------------------------------------
   raw | measured | resolved | visited | latched
   ========================================================================== */

:where([data-spw-succession='raw']) {
  --spw-surface-local-clarity: calc(var(--spw-surface-local-clarity, 0.62) * 0.88);
  --spw-surface-local-memory: 0.08;
}

:where([data-spw-succession='measured']) {
  --spw-surface-local-clarity: calc(var(--spw-surface-local-clarity, 0.62) * 1.02);
  --spw-surface-local-memory: 0.18;
}

:where([data-spw-succession='resolved']) {
  --spw-surface-local-clarity: calc(var(--spw-surface-local-clarity, 0.62) * 1.08);
  --spw-surface-local-memory: 0.24;
}

:where([data-spw-succession='visited']) {
  --spw-surface-local-memory: 0.42;
  --spw-surface-local-resonance: 0.32;
}

:where([data-spw-succession='latched']) {
  --spw-surface-local-memory: 0.58;
  --spw-surface-local-pressure: calc(var(--spw-surface-local-pressure, 0.34) * 1.08);
}

/* ==========================================================================
   7. Wonder-field routing
   --------------------------------------------------------------------------
   The gesture / experiential layers can set data-spw-field-wonder on local
   roots. This file turns that into generic environmental tuning.
   ========================================================================== */

:where([data-spw-field-wonder='orientation']) {
  --spw-field-orientation: max(var(--spw-field-orientation, 0), 0.65);
}

:where([data-spw-field-wonder='inquiry']) {
  --spw-field-inquiry: max(var(--spw-field-inquiry, 0), 0.65);
}

:where([data-spw-field-wonder='comparison']) {
  --spw-field-comparison: max(var(--spw-field-comparison, 0), 0.65);
}

:where([data-spw-field-wonder='memory']) {
  --spw-field-memory: max(var(--spw-field-memory, 0), 0.65);
}

:where([data-spw-field-wonder='projection']) {
  --spw-field-projection: max(var(--spw-field-projection, 0), 0.65);
}

:where([data-spw-field-wonder='constraint']) {
  --spw-field-constraint: max(var(--spw-field-constraint, 0), 0.65);
}

:where([data-spw-field-wonder='resonance']) {
  --spw-field-resonance: max(var(--spw-field-resonance, 0), 0.65);
}

/* ==========================================================================
   8. Generic seams
   --------------------------------------------------------------------------
   These are shared ecological seams, not feature-specific widgets.
   ========================================================================== */

:where(.spw-context-memo, .spw-experience-memo) {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-2xs, 0.35rem);
  max-width: min(100%, 72ch);
  margin-top: var(--space-2xs, 0.4rem);
  padding: 0.22rem 0.54rem;
  border: 1px solid color-mix(in srgb, var(--active-op-color, #008080) 18%, transparent);
  border-radius: var(--radius-pill, 999px);
  background:
    linear-gradient(
      90deg,
      color-mix(in srgb, var(--active-op-color, #008080) 8%, transparent) 0,
      transparent 48%
    ),
    color-mix(in srgb, var(--surface, #ffffff) 90%, transparent);
  color: var(--ink-soft, rgba(14, 18, 20, 0.68));
  font-family: var(--site-mono-font, 'JetBrains Mono', monospace);
  font-size: var(--text-size-xs, 0.66rem);
  line-height: 1.35;
  letter-spacing: 0.04em;
  opacity: var(--spw-surface-seam-opacity, 0.72);
  transition:
    border-color var(--duration-fast, 140ms) var(--ease-mechanical, ease),
    opacity var(--duration-fast, 140ms) var(--ease-mechanical, ease);
}

:where(.spw-context-memo[hidden], .spw-experience-memo[hidden]) {
  display: none !important;
}

:where(.spw-surface-helper-strip) {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-2xs, 0.4rem);
  max-width: 100%;
}

:where(.spw-surface-helper-chip) {
  display: inline-flex;
  align-items: center;
  min-width: 0;
  padding: 0.16rem 0.42rem;
  border: 1px solid color-mix(in srgb, var(--active-op-color, #008080) 18%, transparent);
  border-radius: var(--radius-pill, 999px);
  background: color-mix(in srgb, var(--surface, #ffffff) 86%, transparent);
  color: var(--ink-soft, rgba(14, 18, 20, 0.68));
  font-size: 0.64rem;
  line-height: 1.3;
  transition: border-color var(--duration-fast, 140ms) var(--ease-mechanical, ease);
}

/* ==========================================================================
   9. Memo-wonder tinting
   ========================================================================== */

:where([data-spw-memo-wonder='orientation']) .spw-context-memo,
:where([data-spw-field-wonder='orientation']) .spw-context-memo {
  border-color: color-mix(in srgb, var(--op-frame-color, #008080) 24%, transparent);
}

:where([data-spw-memo-wonder='inquiry']) .spw-context-memo,
:where([data-spw-field-wonder='inquiry']) .spw-context-memo {
  border-color: color-mix(in srgb, var(--op-probe-color, #4a2180) 24%, transparent);
}

:where([data-spw-memo-wonder='memory']) .spw-context-memo,
:where([data-spw-field-wonder='memory']) .spw-context-memo {
  border-color: color-mix(in srgb, var(--op-object-color, #a67c00) 24%, transparent);
}

:where([data-spw-memo-wonder='projection']) .spw-context-memo,
:where([data-spw-field-wonder='projection']) .spw-context-memo {
  border-color: color-mix(in srgb, var(--op-surface-color, #178282) 24%, transparent);
}

:where([data-spw-memo-wonder='constraint']) .spw-context-memo,
:where([data-spw-field-wonder='constraint']) .spw-context-memo {
  border-color: color-mix(in srgb, var(--op-pragma-color, #883a3a) 24%, transparent);
}

:where([data-spw-memo-wonder='comparison']) .spw-context-memo,
:where([data-spw-field-wonder='comparison']) .spw-context-memo {
  border-color: color-mix(in srgb, var(--op-merge-color, #277a87) 24%, transparent);
}

:where([data-spw-memo-wonder='resonance']) .spw-context-memo,
:where([data-spw-field-wonder='resonance']) .spw-context-memo {
  border-color: color-mix(in srgb, var(--op-ref-color, #1d57a3) 24%, transparent);
}

/* ==========================================================================
   10. Room-aware visibility
   ========================================================================== */

:where([data-spw-room='compact']) :is(.spw-context-memo, .spw-surface-helper-strip) {
  display: none;
}

:where([data-spw-room='standard']) .spw-context-memo {
  max-width: min(100%, var(--measure-panel, 52ch));
}

:where([data-spw-room='roomy']) .spw-context-memo {
  max-width: min(100%, var(--measure-reading, 72ch));
}

@container (max-width: 42rem) {
  :where(.spw-context-memo, .spw-experience-memo) {
    max-width: 100%;
    font-size: 0.62rem;
  }
}

/* ==========================================================================
   11. Surface-field seam
   ========================================================================== */

:where([data-spw-field-wonder])::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 1px;
  pointer-events: none;
  opacity: calc(0.12 + (var(--spw-field-charge, 0) * 0.28));
  background:
    linear-gradient(
      90deg,
      color-mix(in srgb, var(--active-op-color, #008080) 22%, transparent) 0%,
      transparent 62%
    );
}

/* ==========================================================================
   12. Loading ecology field routing
   --------------------------------------------------------------------------
   Root ecology phases raise environmental field tokens; hosts inherit without
   route-local timers. Succession stays on surfaces; this layer names the field.
   ========================================================================== */

:where(html[data-spw-loading-ecology-phase="discovering"]) {
  --spw-field-inquiry: 0.18;
  --spw-field-projection: 0.08;
}

:where(html[data-spw-loading-ecology-phase="prefetching"]) {
  --spw-field-projection: 0.22;
  --spw-field-memory: 0.14;
  --spw-ecology-field-charge: 0.12;
}

:where(html[data-spw-loading-ecology-phase="measuring"]) {
  --spw-field-comparison: 0.24;
  --spw-field-constraint: 0.16;
  --spw-ecology-field-charge: 0.18;
}

:where(html[data-spw-loading-ecology-phase="mounting"]) {
  --spw-field-charge: 0.14;
  --spw-field-resonance: 0.12;
  --spw-ecology-field-resonance: 0.16;
}

:where(html[data-spw-loading-ecology-phase="settling"], html[data-spw-loading-ecology-phase="personalizing"]) {
  --spw-field-resonance: calc(0.16 + (var(--spw-ecology-trope-weight, 0) * 0.18));
  --spw-surface-local-resonance: calc(var(--spw-surface-resonance, 0.18) + var(--spw-ecology-field-resonance, 0));
  --spw-ecology-field-charge: calc(0.14 + (var(--spw-ecology-beat-align, 0) * 0.1));
}

:where(html[data-spw-loading-ecology-phase="settled"]) {
  --spw-field-memory: calc(0.16 + (var(--spw-ecology-trope-weight, 0) * 0.12));
  --spw-surface-local-memory: calc(var(--spw-surface-memory, 0.16) + (var(--spw-ecology-trope-weight, 0) * 0.08));
}

:where(html[data-spw-loading-ecology-dimensions~="fetch"]) {
  --spw-surface-local-permeability: calc(var(--spw-surface-permeability, 0.3) + 0.08);
}

:where(html[data-spw-loading-ecology-dimensions~="measure"]) {
  --spw-surface-local-clarity: calc(var(--spw-surface-clarity, 0.62) + 0.06);
}

:where(html[data-spw-loading-ecology-dimensions~="personalize"], html[data-spw-loading-ecology-dimensions~="theme"]) {
  --spw-surface-local-atmosphere: calc(var(--spw-surface-atmosphere, 0.18) + 0.08);
  --spw-field-charge: calc(var(--spw-field-charge, 0) + 0.1);
}

:where(html[data-spw-loading-ecology-dimensions~="localize"], html[data-spw-loading-ecology-dimensions~="variant"]) {
  --spw-field-orientation: 0.14;
}

:where(
  [data-spw-succession='raw'],
  [data-spw-succession='measured']
) {
  --spw-surface-local-resonance: calc(
    var(--spw-surface-local-resonance, var(--spw-surface-resonance, 0.18))
    + (var(--spw-loading-ecology-surface, 0) * 0.06)
  );
}

/* ==========================================================================
   13. Reduced motion
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  :where(.spw-context-memo, .spw-experience-memo, .spw-surface-helper-chip) {
    transition: none !important;
    animation: none !important;
  }
}
}

/* /public/css/systems/registers.css */
@layer systems {
/* ==========================================================================
   registers.css — Expressive Registers (systems layer)
   --------------------------------------------------------------------------
   A composable grammar that projects the registered scalar channels declared
   in tokens/core.css (@property --spw-*) into visual expression.

   The model, in three strata (see .spw/conventions/expressive-registers.spw):

     1. CHANNELS  — nouns. Continuous scalars with documented polarity:
        --spw-depth      0 far  → 1 near        (lift)
        --spw-valence   -1 avoid → +1 approach  (temperature)
        --spw-resonance  0 isolated → 1 coupled (coupling ring)
        --spw-attention  0 ambient → 1 focal    (salience weight)
        --spw-field-intensity 0 quiet → 1 charged (substrate wash)

     2. RENDERINGS — verbs. Each reads exactly ONE channel × its register
        weight, so renderings sum cleanly and never entangle.

     3. REGISTERS  — the viewpoint. [data-spw-register="..."] sets a weight
        mix: it does not change channel values, only how loudly each
        rendering speaks. This is "differential salience via lenses".

   Strictly additive and OPT-IN: nothing renders until a surface adds
   [data-spw-register] to a container and [data-spw-express] to participants.
   Register ≠ lens (content filter) ≠ form (spatial grammar) — all orthogonal.
   ========================================================================== */

/* --------------------------------------------------------------------------
   Register weights — the viewpoint. Default to "balanced" so an opted-in
   participant always has a full weight vector even with no register named.
   -------------------------------------------------------------------------- */
:where([data-spw-express]),
:where([data-spw-register]) {
  --reg-w-depth: 1;
  --reg-w-valence: 1;
  --reg-w-resonance: 1;
  --reg-w-attention: 1;
  --reg-w-field: 1;
}

:where([data-spw-register="depth"]) {
  --reg-w-depth: 1.5;
  --reg-w-valence: 0.4;
  --reg-w-resonance: 0.4;
  --reg-w-attention: 0.6;
}
:where([data-spw-register="valence"]) {
  --reg-w-valence: 1.6;
  --reg-w-depth: 0.5;
  --reg-w-resonance: 0.4;
  --reg-w-attention: 0.6;
}
:where([data-spw-register="resonance"]) {
  --reg-w-resonance: 1.7;
  --reg-w-depth: 0.4;
  --reg-w-valence: 0.4;
  --reg-w-attention: 0.5;
}
:where([data-spw-register="attention"]) {
  --reg-w-attention: 1.6;
  --reg-w-depth: 0.5;
  --reg-w-valence: 0.5;
  --reg-w-resonance: 0.4;
}

/* --------------------------------------------------------------------------
   Authoring handle — data-spw-approach. One attribute sets several channels
   per the prairie phase (approach_topography). Authors compose feeling
   without writing calc(); runtime may also set the channels directly.
   -------------------------------------------------------------------------- */
:where([data-spw-approach="distant"]) {
  --spw-depth: 0.15;
  --spw-attention: 0.15;
  --spw-valence: 0;
}
:where([data-spw-approach="approaching"]) {
  --spw-depth: 0.5;
  --spw-attention: 0.5;
  --spw-valence: 0.5;
}
:where([data-spw-approach="arrival"]) {
  --spw-depth: 1;
  --spw-attention: 1;
  --spw-valence: 1;
}
:where([data-spw-approach="return"]) {
  --spw-depth: 0.5;
  --spw-resonance: 0.85;
  --spw-attention: 0.4;
  --spw-valence: -0.3;
}

/* --------------------------------------------------------------------------
   Renderings — verbs. Each composes channel × weight into one CSS effect.
   Resolved factors are named so the cascade stays diagnosable.
   -------------------------------------------------------------------------- */
:where([data-spw-express]) {
  --reg-depth: calc(var(--spw-depth, 0) * var(--reg-w-depth, 1));
  --reg-valence: calc(var(--spw-valence, 0) * var(--reg-w-valence, 1));
  --reg-resonance: calc(var(--spw-resonance, 0) * var(--reg-w-resonance, 1));
  --reg-attention: calc(var(--spw-attention, 0) * var(--reg-w-attention, 1));

  /* split valence into warm (approach) and cool (avoid) magnitudes */
  --reg-warm: max(var(--reg-valence), 0);
  --reg-cool: max(calc(-1 * var(--reg-valence)), 0);

  /* salience: focal sharpens ink + presence, ambient recedes */
  font-weight: calc(420 + var(--reg-attention) * 260);
  opacity: calc(0.7 + var(--reg-attention) * 0.3);

  /* lift: the near develops out of the substrate; coupling adds an outer ring */
  transform: translateY(calc(var(--reg-depth) * -4px));
  box-shadow:
    0 calc(var(--reg-depth) * 6px) calc(var(--reg-depth) * 18px)
      color-mix(in srgb, var(--ink, #1b1f23) calc(var(--reg-depth) * 16%), transparent),
    0 0 0 calc(var(--reg-resonance) * 2px)
      color-mix(in srgb, var(--spw-operator-color, var(--wonder-accent-color, #4aa3a3)) calc(var(--reg-resonance) * 40%), transparent);

  /* temperature: a thin tint toward warm or cool by valence direction */
  background-image: linear-gradient(
    160deg,
    color-mix(in srgb, var(--reg-warm-tint, #d98a4a) calc(var(--reg-warm) * 10%), transparent),
    color-mix(in srgb, var(--reg-cool-tint, #4a82d9) calc(var(--reg-cool) * 10%), transparent)
  );

  transition:
    transform var(--duration-fast, 160ms) var(--ease-mechanical, ease),
    box-shadow var(--duration-fast, 160ms) var(--ease-mechanical, ease),
    font-weight var(--duration-fast, 160ms) var(--ease-mechanical, ease),
    opacity var(--duration-fast, 160ms) var(--ease-mechanical, ease);
}

/* wash: substrate gradient on the register container — holds the journey
   without competing with figure (substrate vs figure discipline). */
:where([data-spw-register]) {
  background-image: radial-gradient(
    120% 80% at 50% 0%,
    color-mix(in srgb, var(--wonder-accent-color, #4aa3a3) calc(var(--spw-field-intensity, 0) * var(--reg-w-field, 1) * 6%), transparent),
    transparent 70%
  );
}

/* --------------------------------------------------------------------------
   Coupling ↔ existing resonance field. When a kin operator is pinned by
   attention-architecture (html[data-spw-resonance-probe]), lift coupled
   participants' resonance so they brighten together under any register.
   -------------------------------------------------------------------------- */
@supports selector(:has(*)) {
  :where(html[data-spw-resonance-probe]) :where([data-spw-express][data-spw-operator]) {
    --spw-resonance: max(var(--spw-resonance, 0), 0.6);
  }
}

/* --------------------------------------------------------------------------
   Reduced motion — keep the expression, drop the movement.
   -------------------------------------------------------------------------- */
@media (prefers-reduced-motion: reduce) {
  :where([data-spw-express]) {
    transform: none;
    transition: box-shadow var(--duration-fast, 160ms) var(--ease-mechanical, ease),
      opacity var(--duration-fast, 160ms) var(--ease-mechanical, ease);
  }
}
}

/* /public/css/systems/surfaces/base.css */
@layer systems {
/* ==========================================================================
   surfaces/base.css
   --------------------------------------------------------------------------
   Shared shell variables and macro-layout normalization.
   ========================================================================== */

:root {
  --spw-shell-card-gap:   var(--gap-inline-flow, clamp(0.75rem, 1.4vw, 1rem));
  --spw-shell-panel-gap:  var(--gap-surface, clamp(0.85rem, 1.8vw, 1.15rem));
  --spw-shell-inline-gap: var(--space-xs, 0.55rem);

  --spw-shell-card-pad:   var(--inset-component, 1rem);
  --spw-shell-panel-pad:  var(--inset-surface, 0.9rem);

  --spw-shell-soft-bg:        var(--spw-surface-fill-soft, var(--surface-soft, rgba(255, 255, 255, 0.44)));
  --spw-shell-card-bg:        var(--spw-surface-fill-rest, var(--surface, rgba(255, 255, 255, 0.68)));
  --spw-shell-card-bg-strong: var(--spw-surface-fill-strong, var(--surface-strong, rgba(255, 255, 255, 0.74)));
  --spw-shell-panel-bg:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--spw-shell-card-bg-strong) 92%, transparent),
      color-mix(in srgb, var(--spw-shell-card-bg) 92%, transparent)
    );
  --spw-shell-panel-bg-strong:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--surface-panel-strong, var(--spw-shell-card-bg-strong)) 94%, transparent),
      color-mix(in srgb, var(--surface-panel, var(--spw-shell-card-bg)) 94%, transparent)
    );
  --spw-shell-sheen: color-mix(in srgb, var(--surface-strong, rgba(255, 255, 255, 0.78)) 22%, transparent);
  --spw-shell-overlay: var(--overlay-gradient-fade-bottom);

  --spw-shell-line:        var(--spw-surface-line-rest, var(--line, rgba(14, 18, 20, 0.14)));
  --spw-shell-line-strong: var(--spw-surface-line-active, var(--line-strong, rgba(0, 128, 128, 0.34)));
  --spw-shell-card-shadow: var(--spw-surface-shadow-rest, var(--card-shadow));
  --spw-shell-card-shadow-raised: var(--spw-surface-shadow-raised, var(--card-shadow-hover));
  --spw-shell-card-transition:
    transform var(--duration-base, 220ms) var(--ease-mechanical, ease),
    border-color var(--duration-fast, 140ms) var(--ease-mechanical, ease),
    background var(--duration-fast, 140ms) var(--ease-mechanical, ease),
    box-shadow var(--duration-base, 220ms) var(--ease-mechanical, ease);
  --spw-palette-probe-1: var(--active-op-color, #008080);
  --spw-palette-probe-2: var(--op-object-color, #c68a22);
  --spw-palette-probe-3: var(--op-ref-color, #1d57a3);
  --spw-palette-probe-4: var(--op-probe-color, #6a3fb8);
}

/* Generic shell card/panel rhythm */
:where(
  .media-focus-card,
  .media-card,
  .pretext-controls-panel,
  .pretext-summary-panel,
  .pretext-surface,
  .rpg-gameplay-panel,
  .settings-category,
  .settings-fieldset,
  .pwa-status-card,
  .spw-nav-panel,
  .spw-console
) {
  min-width: 0;
}

:where(.media-focus-card, .media-card, .topic-reference-card) {
  position: relative;
  min-height: 100%;
  padding: var(--spw-shell-card-pad);
  border: 1px solid var(--spw-shell-line);
  border-radius: var(--shape-surface, 10px);
  background: var(--spw-shell-panel-bg);
  color: inherit;
  box-sizing: border-box;
  box-shadow: var(--spw-shell-card-shadow);
  overflow: hidden;
  transition: var(--spw-shell-card-transition);
}

:where(.media-focus-card, .media-card) {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm, 0.62rem);
}

:where(.topic-reference-card) {
  display: grid;
  gap: 0.55rem;
}

:where(.frame-grid) {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, var(--grid-min-card, 16rem)), 1fr));
  gap: var(--spw-shell-panel-gap, var(--component-gap, 0.9rem));
  min-width: 0;
}

:where(.frame-grid[data-spw-layout="media-prose"], .frame-grid--media-prose) {
  grid-template-columns: minmax(0, 1fr) minmax(min(100%, 18rem), 0.72fr);
  align-items: start;
}

:where(.frame-grid[data-spw-layout="media-prose"], .frame-grid--media-prose) > :where(*) {
  min-width: 0;
}

:where(.frame-grid[data-spw-layout="media-prose"], .frame-grid--media-prose) > :first-child {
  grid-column: auto;
}

:where(.frame-grid[data-spw-layout="media-prose"], .frame-grid--media-prose) > :is(figure, .image-study, .topic-photo-card) {
  grid-column: auto;
  align-self: start;
  justify-self: center;
  inline-size: min(100%, 30rem);
  max-inline-size: 30rem;
}

@media (max-width: 48rem) {
  :where(.frame-grid[data-spw-layout="media-prose"], .frame-grid--media-prose) {
    grid-template-columns: 1fr;
  }
}

:where(.frame-grid--dense) {
  gap: var(--component-gap-tight, 0.55rem);
}

:where(
  .frame-grid,
  .media-card-grid,
  .media-focus-layout,
  .feature-map,
  .domain-grid,
  .spec-grid
) {
  align-items: stretch;
}

:where(
  .frame-grid > :is(.frame-card, .software-card),
  .media-card-grid > .media-card,
  .media-focus-layout > * > .media-focus-card,
  .feature-map > .frame-card,
  .domain-grid > .frame-panel,
  .spec-grid > :is(.software-card, .frame-panel)
) {
  height: 100%;
}

/* ==========================================================================
   Shared route ecology (all surfaces)
   ========================================================================== */

:where(main) {
  padding-block-end: calc(var(--spw-bottom-chrome-clearance, 0px) + clamp(1.5rem, 4vw, 2.75rem));
}

:where(main > .site-frame) {
  scroll-margin-top: calc(var(--header-height, 4rem) + 0.85rem);
}

:where(.site-frame > .frame-body) {
  display: grid;
  gap: var(--spw-shell-panel-gap);
  align-content: start;
  min-width: 0;
}

:where(.site-frame .frame-heading) {
  padding-block-end: 0.38rem;
  margin-block-end: 0.08rem;
  border-bottom: 1px solid color-mix(in srgb, var(--spw-shell-line) 72%, transparent);
}

:where(.site-frame .frame-heading h2) {
  flex: 1 1 12rem;
  min-width: 0;
  text-wrap: balance;
}

:where(.site-frame .inline-note) {
  margin: 0;
  max-inline-size: var(--spw-layout-measure, 68ch);
  color: color-mix(in srgb, var(--ink-soft, rgba(14, 18, 20, 0.68)) 88%, var(--active-op-color, var(--teal)) 12%);
  line-height: 1.52;
  text-wrap: pretty;
}

:where(.site-frame[data-spw-attentional-weight="1.35"]) {
  border-color: color-mix(in oklab, var(--active-op-color, var(--teal)) 30%, var(--line, transparent));
}

:where(.site-frame[data-spw-attentional-weight="1.25"]),
:where(.site-frame[data-spw-attentional-weight="1.2"]) {
  border-color: color-mix(in oklab, var(--active-op-color, var(--teal)) 24%, var(--line, transparent));
}

:where(.site-frame[data-spw-attentional-weight="1.15"]),
:where(.site-frame[data-spw-attentional-weight="1.1"]),
:where(.site-frame[data-spw-attentional-weight="1.05"]) {
  border-color: color-mix(in oklab, var(--active-op-color, var(--teal)) 18%, var(--line, transparent));
}

:where(.site-frame[data-spw-attentional-weight="0.95"]),
:where(.site-frame[data-spw-attentional-weight="0.92"]) {
  opacity: 0.98;
}

:where(
  .site-frame[data-spw-region-purpose="public-spine"][data-spw-composition-stability="anchored"],
  .site-frame[data-spw-region-purpose="public-spine"][data-spw-composition-stability="stable"],
  .site-frame[data-spw-region-purpose="section-hub"][data-spw-composition-stability="anchored"],
  .site-frame[data-spw-region-purpose="section-hub"][data-spw-composition-stability="stable"],
  .site-frame[data-spw-feature$="-entry"][data-spw-composition-stability="anchored"],
  .site-frame[data-spw-feature$="-entry"][data-spw-composition-stability="stable"]
) {
  --site-frame-seam-color: color-mix(in srgb, var(--active-op-color, var(--teal)) 38%, transparent);
  --spw-chassis-highlight:
    inset 0 1px 0 color-mix(in srgb, white 22%, transparent),
    inset 0.28rem 0 0 color-mix(in srgb, var(--active-op-color, var(--teal)) 12%, transparent);
}

:where(
  .site-frame[data-spw-region-purpose="public-spine"][data-spw-composition-stability="stable"],
  .site-frame[data-spw-region-purpose="section-hub"][data-spw-composition-stability="stable"],
  .site-frame[data-spw-feature$="-entry"][data-spw-composition-stability="stable"]
) {
  --site-frame-seam-color: color-mix(in srgb, var(--active-op-color, var(--teal)) 22%, transparent);
  --spw-chassis-highlight:
    inset 0 1px 0 color-mix(in srgb, white 18%, transparent),
    inset 0.18rem 0 0 color-mix(in srgb, var(--active-op-color, var(--teal)) 8%, transparent);
}

:where(.site-frame[data-spw-gradient-boundary="none"])::before {
  opacity: 0.18;
}

:where(html[data-spw-debug-mode="on"]) :where(.site-frame[data-spw-resolved-composition-stability]) {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--active-op-color, var(--teal)) 12%, transparent);
}

:where(html[data-spw-debug-mode="on"]) :where(.site-frame[data-spw-resolved-composition-stability="loose"]) {
  border-style: dashed;
}

:where(.site-frame .frame-panel, .site-frame .frame-card) {
  transition:
    transform var(--duration-fast, 120ms) var(--ease-mechanical, ease),
    border-color var(--duration-base, 180ms) var(--ease-mechanical, ease),
    box-shadow var(--duration-base, 180ms) var(--ease-mechanical, ease);
}

:where(.site-frame .frame-panel:is(:hover, :focus-within), .site-frame .frame-card:is(:hover, :focus-within)) {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--active-op-color, var(--teal)) 22%, var(--line, transparent));
}

@media (max-width: 40rem) {
  :where(.site-frame) {
    --surface-gap: clamp(0.52rem, 1.8vw, 0.76rem);
    --surface-padding: clamp(0.68rem, 2.6vw, 0.88rem);
  }

  :where(.site-frame > .frame-body) {
    gap: clamp(0.68rem, 2.4vw, 0.82rem);
  }

  :where(main) {
    gap: clamp(0.85rem, 2.8vw, 1.15rem);
  }

  :where(.frame-grid--dense) {
    --spw-grid-min-base: 100%;
    --spw-grid-min-mid: 100%;
    --spw-grid-min-narrow: 100%;
    --spw-grid-min-compact: 100%;
    gap: 0.62rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  :where(.site-frame .frame-panel, .site-frame .frame-card) {
    transition: none;
  }

  :where(.site-frame .frame-panel:is(:hover, :focus-within), .site-frame .frame-card:is(:hover, :focus-within)) {
    transform: none;
  }
}
}

