  display: block;
  width: 100%;
  aspect-ratio: 16 / 10;
  object-fit: cover;
  transition:
    transform var(--duration-deliberate, 360ms) var(--ease-mechanical, ease),
    filter var(--duration-deliberate, 360ms) var(--ease-mechanical, ease);
}

:where(.frame-card-media[data-spw-image-shape="square"] img) {
  aspect-ratio: 1 / 1;
}

:where(.frame-card-media[data-spw-image-shape="portrait"] img) {
  aspect-ratio: 4 / 5;
}
}

/* /public/css/systems/surfaces/drift.css */
@layer systems {
/* ==========================================================================
   surfaces/drift.css
   --------------------------------------------------------------------------
   Return-visitor, gratitude, and wonder reward surfaces.
   ========================================================================== */

/* Return-visitor / drift surfaces */
:where(.returner-grid) {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 0.9fr) minmax(0, 1fr);
  gap: var(--spw-shell-panel-gap);
  align-items: start;
}

:where(.returner-card, .returner-ledger) {
  min-width: 0;
  padding: var(--spw-shell-panel-pad);
  border: 1px solid color-mix(in srgb, var(--spw-shell-line-strong) 42%, var(--spw-shell-line));
  border-radius: var(--shape-floating, 14px);
  background:
    linear-gradient(180deg, var(--spw-shell-sheen), transparent 42%),
    var(--spw-shell-panel-bg-strong);
  box-shadow: var(--spw-shell-card-shadow);
}

:where(.returner-card) {
  display: grid;
  gap: 0.72rem;
  align-content: start;
}

:where(.returner-card > :last-child, .returner-ledger > :last-child) {
  margin-block-end: 0;
}

:where(.returner-card--warm) {
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--op-object-color, #c68a22) 8%, var(--spw-shell-sheen)),
      transparent 42%
    ),
    var(--spw-shell-panel-bg-strong);
}

:where(.returner-card-kicker) {
  margin: 0;
  color: var(--ink-soft);
  font-size: var(--text-size-xs, 0.76rem);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

:where(.returner-card > h3, .returner-ledger-title) {
  margin: 0;
}

:where(.returner-card > p, .returner-ledger-item > p) {
  margin: 0;
  color: var(--ink-soft);
}

:where(.returner-chip-row) {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

:where(.returner-ledger) {
  display: grid;
  gap: 0.72rem;
  align-content: start;
}

:where(.returner-ledger-item) {
  display: grid;
  gap: 0.32rem;
  padding-left: 0.85rem;
  border-left: 2px solid color-mix(in srgb, var(--active-op-color, #008080) 28%, transparent);
}

:where(.returner-ledger-item > strong) {
  color: var(--ink);
}

@media (max-width: 960px) {
  :where(.returner-grid) {
    grid-template-columns: 1fr;
  }
}

/* Gratitude / wonder reward surfaces */
:where(.gratitude-grid) {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--spw-shell-panel-gap);
}

:where(.gratitude-card) {
  display: grid;
  gap: 0.72rem;
  min-width: 0;
  min-height: 100%;
  padding: var(--spw-shell-panel-pad);
  border: 1px solid color-mix(in srgb, var(--spw-shell-line-strong) 38%, var(--spw-shell-line));
  border-radius: var(--shape-floating, 14px);
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--op-topic-color, #2f8b6d) 8%, var(--spw-shell-sheen)),
      transparent 44%
    ),
    var(--spw-shell-panel-bg-strong);
  box-shadow: var(--spw-shell-card-shadow);
}

:where(.gratitude-card--reward) {
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--op-object-color, #c68a22) 10%, var(--spw-shell-sheen)),
      transparent 44%
    ),
    var(--spw-shell-panel-bg-strong);
}

:where(.gratitude-kicker) {
  margin: 0;
  color: var(--ink-soft);
  font-size: var(--text-size-xs, 0.76rem);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

:where(.gratitude-card > h3, .gratitude-item > strong) {
  margin: 0;
}

:where(.gratitude-card > p, .gratitude-item > p) {
  margin: 0;
  color: var(--ink-soft);
}

:where(.gratitude-list) {
  display: grid;
  gap: 0.6rem;
}

:where(.gratitude-item) {
  display: grid;
  gap: 0.24rem;
  padding-left: 0.8rem;
  border-left: 2px solid color-mix(in srgb, var(--active-op-color, #008080) 26%, transparent);
}

@media (max-width: 960px) {
  :where(.gratitude-grid) {
    grid-template-columns: 1fr;
  }
}
}

/* /public/css/systems/surfaces/tuning.css */
@layer systems {
/* ==========================================================================
   surfaces/tuning.css
   --------------------------------------------------------------------------
   Climate tuning, vibe widgets, palette probes, and theme choosers.
   ========================================================================== */

:where(.vibe-widget-grid) {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 14rem), 1fr));
  gap: var(--spw-shell-panel-gap);
  align-items: stretch;
}

:where(.vibe-widget-grid--compact) {
  gap: 0.8rem;
}

:where(.vibe-widget, .palette-probe) {
  position: relative;
  display: grid;
  gap: 0.72rem;
  min-inline-size: 0;
  max-inline-size: 100%;
  min-height: 100%;
  padding: 0.95rem 1rem 1rem;
  border: 1px solid color-mix(in srgb, var(--spw-palette-probe-1, var(--active-op-color, #008080)) 18%, var(--spw-shell-line));
  border-radius: calc(var(--shape-surface, 10px) - 1px);
  background:
    linear-gradient(140deg, color-mix(in srgb, var(--spw-palette-probe-1, var(--active-op-color, #008080)) 9%, var(--surface-strong, rgba(255, 255, 255, 0.92))), transparent 62%),
    radial-gradient(circle at top right, color-mix(in srgb, var(--spw-palette-probe-2, var(--op-object-color, #c68a22)) 10%, transparent), transparent 24%),
    var(--spw-shell-panel-bg-strong);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.26),
    0 6px 16px rgba(17, 18, 20, 0.035),
    var(--card-highlight),
    var(--card-shadow);
  overflow: clip;
}

:where(.vibe-widget::before) {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  block-size: 0.18rem;
  background:
    linear-gradient(
      90deg,
      var(--spw-palette-probe-1, var(--active-op-color, #008080)),
      var(--spw-palette-probe-2, var(--op-object-color, #c68a22)),
      var(--spw-palette-probe-3, var(--op-ref-color, #1d57a3)),
      var(--spw-palette-probe-4, var(--op-probe-color, #6a3fb8))
    );
  opacity: 0.42;
}

:where(.vibe-widget > *) {
  min-inline-size: 0;
  max-inline-size: 100%;
  position: relative;
  z-index: 1;
}

:where(.vibe-widget--feature) {
  grid-column: 1 / -1;
}

:where(.vibe-widget-header, .palette-probe-header > header) {
  display: grid;
  gap: 0.3rem;
}

:where(:is(.vibe-widget, .palette-probe)-kicker) {
  margin: 0;
  color: var(--ink-soft);
  font-size: var(--text-size-xs, 0.8rem);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

:where(:is(.vibe-widget, .palette-probe)-title) {
  margin: 0;
  color: var(--ink);
  font-size: clamp(1rem, 1.8vw, 1.18rem);
  line-height: 1.2;
}

:where(:is(.vibe-widget, .palette-probe)-copy) {
  margin: 0;
  color: color-mix(in srgb, var(--ink-soft) 88%, var(--ink) 12%);
  max-inline-size: 70ch;
}

:where(
  .vibe-widget-kicker,
  .vibe-widget-title,
  .vibe-widget-copy,
  .palette-probe-kicker,
  .palette-probe-title,
  .palette-probe-copy
) {
  overflow-wrap: anywhere;
}

:where(:is(.vibe-widget, .palette-probe, .wonder-memory)-actions, .palette-probe-paths) {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: stretch;
}

:where(:is(.vibe-widget, .palette-probe, .wonder-memory)-actions > *, .vibe-widget-meta > *, .palette-probe-paths > *) {
  max-inline-size: 100%;
  min-inline-size: 0;
}

:where(:is(.vibe-widget, .wonder-memory, .palette-probe)-actions :is(.operator-chip, .spec-pill)[data-site-setting-active="true"],
       :is(.vibe-widget, .palette-probe)-actions [data-spw-palette-probe-active="true"]) {
  background:
    linear-gradient(180deg, rgba(255,255,255,0.18), transparent 64%),
    color-mix(in srgb, var(--surface-strong, rgba(255, 255, 255, 0.92)) 90%, var(--spw-palette-probe-1, var(--active-op-color, #008080)) 10%);
  border-color: color-mix(in srgb, var(--spw-palette-probe-1, var(--active-op-color, #008080)) 38%, transparent);
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--spw-palette-probe-1, var(--active-op-color, #008080)) 14%, transparent);
  color: var(--ink);
}

:where(.vibe-widget-meta) {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem 0.6rem;
  align-items: center;
}

:where(:is(.vibe-widget, .palette-probe)-state) {
  color: color-mix(in srgb, var(--spw-palette-probe-1, var(--active-op-color, #008080)) 74%, var(--ink) 26%);
  font-weight: 600;
}

:where(.vibe-widget-status) {
  min-block-size: 1.15rem;
  color: var(--ink-soft);
  font-size: var(--text-size-xs, 0.8rem);
}

:where(.vibe-widget-status[data-status="info"]) {
  color: color-mix(in srgb, var(--spw-palette-probe-3, var(--op-ref-color, #1d57a3)) 68%, var(--ink) 32%);
}

:where(.vibe-widget-status[data-status="success"]) {
  color: color-mix(in srgb, var(--spw-palette-probe-1, var(--active-op-color, #008080)) 72%, var(--ink) 28%);
}

/* Wonder Memory */
:where(.wonder-memory-strip) {
  display: grid;
  gap: 0.65rem;
  margin-block: 0.2rem 0.35rem;
  padding: 0.8rem 0.95rem;
  border: 1px dashed color-mix(in srgb, var(--wonder-accent-color, var(--active-op-color, #008080)) 28%, transparent);
  border-radius: calc(var(--shape-surface, 10px) - 2px);
  background:
    linear-gradient(
      135deg,
      color-mix(in srgb, var(--wonder-accent-color, var(--active-op-color, #008080)) 10%, var(--surface-strong, rgba(255, 255, 255, 0.92))) 0%,
      color-mix(in srgb, var(--surface-strong, rgba(255, 255, 255, 0.92)) 94%, transparent) 58%,
      color-mix(in srgb, var(--delight-color, var(--op-object-color, #c68a22)) 8%, var(--surface-panel-strong, rgba(255, 255, 255, 0.94))) 100%
    );
}

:where(.wonder-memory-actions .operator-chip[data-site-setting-active="true"]) {
  color: var(--wonder-accent-color, var(--active-op-color, #008080));
}

/* Palette Probe */
:where(.palette-probe-header) {
  display: flex;
  justify-content: space-between;
  gap: 0.9rem;
  align-items: flex-start;
  flex-wrap: wrap;
}

:where(:is(.vibe-widget, .wonder-memory, .palette-probe)-actions .operator-chip, .market-card .operator-chip) {
  justify-content: center;
}

:where(.palette-probe-swatches) {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 0.44rem;
  align-items: center;
}

:where(.palette-probe-chip) {
  inline-size: 1.18rem;
  block-size: 1.18rem;
  border-radius: 0.42rem;
  border: 1px solid color-mix(in srgb, var(--spw-palette-probe-1, var(--spw-shell-line)) 16%, var(--spw-shell-line));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--surface-strong, rgba(255, 255, 255, 0.92)) 18%, transparent),
    0 3px 8px rgba(17, 18, 20, 0.04);
}

:where(.palette-probe-chip:nth-child(1)) { background: var(--spw-palette-probe-1, var(--active-op-color, #008080)); }
:where(.palette-probe-chip:nth-child(2)) { background: var(--spw-palette-probe-2, var(--op-object-color, #c68a22)); }
:where(.palette-probe-chip:nth-child(3)) { background: var(--spw-palette-probe-3, var(--op-ref-color, #1d57a3)); }
:where(.palette-probe-chip:nth-child(4)) { background: var(--spw-palette-probe-4, var(--op-probe-color, #6a3fb8)); }

/* Theme Packs */
:where(.theme-pack-chip-row) {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 0.36rem;
  align-items: center;
}

:where(.theme-pack-chip-btn) {
  --theme-pack-preview-light: linear-gradient(135deg, #fff7ec 0%, #f2e4cf 100%);
  --theme-pack-preview-dark: linear-gradient(135deg, #232a30 0%, #11161a 100%);
  appearance: none;
  inline-size: 1.48rem;
  block-size: 1.48rem;
  padding: 0;
  border: 1px solid color-mix(in srgb, var(--line-strong) 30%, var(--spw-shell-line));
  border-radius: var(--shape-control, 0.78rem);
  background:
    var(--theme-pack-preview-light) top / 100% 50% no-repeat,
    var(--theme-pack-preview-dark) bottom / 100% 50% no-repeat;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.28),
    0 4px 12px rgba(17, 18, 20, 0.08);
  cursor: pointer;
  transition:
    transform var(--duration-fast, 140ms) var(--ease-mechanical, ease),
    border-color var(--duration-fast, 140ms) var(--ease-mechanical, ease),
    box-shadow var(--duration-fast, 140ms) var(--ease-mechanical, ease);
}

:where(.theme-pack-chip-btn:is(:hover, :focus-visible)) {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--active-op-color, #008080) 28%, var(--line-strong));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.32),
    0 6px 14px rgba(17, 18, 20, 0.12);
}

:where(.theme-pack-chip-btn[data-site-setting-active="true"]) {
  border-color: color-mix(in srgb, var(--active-op-color, #008080) 54%, transparent);
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--active-op-color, #008080) 18%, transparent),
    0 8px 16px rgba(17, 18, 20, 0.14);
}

:where(.theme-pack-chooser) {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 10.5rem), 1fr));
  gap: 0.7rem;
}

:where(.theme-pack-swatch) {
  --theme-pack-preview-light: linear-gradient(135deg, #fff7ec 0%, #f2e4cf 100%);
  --theme-pack-preview-dark: linear-gradient(135deg, #232a30 0%, #11161a 100%);
  appearance: none;
  display: grid;
  gap: 0.5rem;
  padding: 0.82rem 0.88rem 0.9rem;
  text-align: left;
  border: 1px solid color-mix(in srgb, var(--line-strong) 18%, var(--spw-shell-line));
  border-radius: calc(var(--shape-surface, 10px) - 1px);
  background:
    linear-gradient(160deg, color-mix(in srgb, var(--surface-strong) 88%, transparent), transparent 60%),
    var(--spw-shell-panel-bg-strong);
  box-shadow: var(--card-highlight), var(--card-shadow);
  cursor: pointer;
  transition:
    transform var(--duration-fast, 140ms) var(--ease-mechanical, ease),
    border-color var(--duration-fast, 140ms) var(--ease-mechanical, ease),
    box-shadow var(--duration-fast, 140ms) var(--ease-mechanical, ease),
    background-color var(--duration-fast, 140ms) var(--ease-mechanical, ease);
}

:where(.theme-pack-swatch:is(:hover, :focus-visible)) {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--active-op-color, #008080) 30%, var(--line-strong));
}

:where(.theme-pack-swatch[data-site-setting-active="true"]) {
  border-color: color-mix(in srgb, var(--active-op-color, #008080) 50%, transparent);
  background:
    linear-gradient(160deg, color-mix(in srgb, var(--active-op-color, #008080) 10%, var(--surface-strong)) 0%, transparent 66%),
    var(--spw-shell-panel-bg-strong);
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--active-op-color, #008080) 16%, transparent),
    var(--card-highlight),
    var(--card-shadow);
}

:where(.theme-pack-swatch__header) {
  display: grid;
  gap: 0.18rem;
}

:where(.theme-pack-swatch__label) {
  color: var(--ink);
  font-size: 0.96rem;
  font-weight: 600;
  line-height: 1.16;
}

:where(.theme-pack-swatch__tone) {
  color: var(--ink-soft);
  font-size: var(--text-size-xs, 0.8rem);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

:where(.theme-pack-swatch__palettes) {
  display: grid;
  gap: 0.28rem;
  align-content: end; /* stable alignment of the two mini bars even when header text wraps */
}

:where(.theme-pack-swatch__palette) {
  min-block-size: 0.6rem;
  border: 1px solid color-mix(in srgb, var(--line-strong) 12%, transparent);
  border-radius: 999px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.18);
}

:where(.theme-pack-swatch__palette[data-theme-pack-variant="light"]) {
  background: var(--theme-pack-preview-light);
}

:where(.theme-pack-swatch__palette[data-theme-pack-variant="dark"]) {
  background: var(--theme-pack-preview-dark);
}

:where([data-theme-pack-preview="neutral-paper"]) {
  --theme-pack-preview-light: linear-gradient(135deg, #f7efdc 0%, #efe5ce 100%);
  --theme-pack-preview-dark: linear-gradient(135deg, #1d2429 0%, #0f1418 100%);
}

:where([data-theme-pack-preview="oxide-ledger"]) {
  --theme-pack-preview-light: linear-gradient(135deg, #f6e8d4 0%, #ceb184 100%);
  --theme-pack-preview-dark: linear-gradient(135deg, #382821 0%, #17110d 100%);
}

:where([data-theme-pack-preview="electric-studio"]) {
  --theme-pack-preview-light: linear-gradient(135deg, #e6f4ff 0%, #74b8ff 100%);
  --theme-pack-preview-dark: linear-gradient(135deg, #10182a 0%, #2c45a5 100%);
}

:where([data-theme-pack-preview="ritual-vellum"]) {
  --theme-pack-preview-light: linear-gradient(135deg, #f6ecdd 0%, #caa7c7 100%);
  --theme-pack-preview-dark: linear-gradient(135deg, #261a2d 0%, #5f3358 100%);
}

:where([data-theme-pack-preview="copper-brace"]) {
  --theme-pack-preview-light: linear-gradient(135deg, #fae7d7 0%, #cb7a41 100%);
  --theme-pack-preview-dark: linear-gradient(135deg, #291912 0%, #6c462d 100%);
}

:where([data-theme-pack-preview="glass-console"]) {
  --theme-pack-preview-light: linear-gradient(135deg, #edf5fb 0%, #9bc2de 100%);
  --theme-pack-preview-dark: linear-gradient(135deg, #141d24 0%, #2b4f69 100%);
}

:where(.context-readout) {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 8.5rem), 1fr));
  gap: 0.45rem 0.6rem;
}

:where(.context-readout > div) {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 0.35rem;
  min-width: 0;
}

:where(.context-readout dt, .context-readout dd) {
  margin: 0;
}

:where(.context-readout dt) {
  color: var(--ink-soft);
  font-size: var(--text-size-xs, 0.78rem);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

@media (max-width: 640px) {
  :where(:is(.vibe-widget, .palette-probe)-actions, .palette-probe-paths) {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.42rem;
  }

  :where(:is(.vibe-widget, .palette-probe)-actions > *, .palette-probe-paths > *) {
    width: 100%;
    min-width: 0;
  }

  :where(.palette-probe, .vibe-widget) {
    gap: 0.68rem;
  }
}

/* ==========================================================================
   Compact contextual tuning clusters (low-verbosity, low-friction widgets)
   Used for paletteResonance, wonderMemory, semanticDensity, operatorSaturation,
   themePack, colorMode etc. near demonstrative content. Reuses the existing
   data-site-setting-set + sync system 100%.
   ========================================================================== */

:where(.tuning-strip, .vibe-widget--compact) {
  --tuning-strip-gap: 0.4rem;
  display: flex;
  flex-wrap: wrap;
  gap: var(--tuning-strip-gap);
  align-items: center;
}

:where(.tuning-strip > .operator-chip,
       .vibe-widget--compact .operator-chip) {
  font-size: 0.8rem;
  padding: 0.18rem 0.55rem;
  min-height: 1.6rem; /* comfortable touch target while staying compact */
}

/* Stronger, unmistakable active state for compact clusters.
   Uses the live resonance probe colors so it feels connected to the current
   paletteResonance setting. Wins over generic pressed states in most contexts. */
:where(.tuning-strip, .vibe-widget--compact)
  :is(.operator-chip, .spec-pill)[data-site-setting-active="true"] {
  background:
    linear-gradient(180deg, rgba(255,255,255,0.22), transparent 70%),
    color-mix(in srgb, var(--spw-palette-probe-1, var(--active-op-color, #008080)) 18%, var(--surface-strong, rgba(255,255,255,0.96)));
  border-color: color-mix(in srgb, var(--spw-palette-probe-1, var(--active-op-color, #008080)) 52%, transparent);
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--spw-palette-probe-1, var(--active-op-color, #008080)) 22%, transparent),
    0 1px 3px rgba(0,0,0,0.06);
  color: var(--ink);
  font-weight: 600;
  transform: translateY(-0.5px);
}

:where(.tuning-strip .operator-chip[data-site-setting-active="true"]::after,
       .vibe-widget--compact .operator-chip[data-site-setting-active="true"]::after) {
  content: "";
  display: inline-block;
  width: 0.35em;
  height: 0.35em;
  border-radius: 50%;
  background: var(--spw-palette-probe-1, var(--active-op-color, #008080));
  margin-left: 0.35em;
  vertical-align: middle;
  opacity: 0.9;
}

/* Broad fallback: give every standalone data-site-setting-set operator-chip the strong resonance-colored active treatment.
   This improves visual clarity everywhere with zero markup changes (addresses scattered active styling across surfaces). */
:where(.operator-chip[data-site-setting-active="true"]:not(.tuning-strip *):not(.vibe-widget--compact *)) {
  background:
    linear-gradient(180deg, rgba(255,255,255,0.18), transparent 68%),
    color-mix(in srgb, var(--spw-palette-probe-1, var(--active-op-color, #008080)) 14%, var(--surface-strong, rgba(255,255,255,0.94)));
  border-color: color-mix(in srgb, var(--spw-palette-probe-1, var(--active-op-color, #008080)) 46%, transparent);
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--spw-palette-probe-1, var(--active-op-color, #008080)) 18%, transparent);
  color: var(--ink);
  font-weight: 600;
}

/* Responsive packing: never let compact strips become awkward vertical stacks on narrow screens */
@media (max-width: 520px) {
  :where(.tuning-strip, .vibe-widget--compact) {
    --tuning-strip-gap: 0.32rem;
  }
  :where(.tuning-strip > .operator-chip,
         .vibe-widget--compact .operator-chip) {
    font-size: 0.78rem;
    padding: 0.16rem 0.48rem;
  }
}
}

/* /public/css/systems/surfaces/tuning-discoverability.css */
@layer systems {
/* ==========================================================================
   surfaces/tuning-discoverability.css
   --------------------------------------------------------------------------
   Marginalia and discoverability for embedded extension surfaces: layout,
   material, and gesture controls without rewriting content.
   ========================================================================== */

:where(html[data-spw-tuning-discoverability="ambient"], html[data-spw-tuning-discoverability="revealed"]) {
  --tuning-marginalia-opacity: 0.42;
  --tuning-edge-strength: 0.14;
  --tuning-pulse-color: var(--active-op-color, #008080);
}

:where(html[data-spw-tuning-discoverability="revealed"]) {
  --tuning-marginalia-opacity: 0.88;
  --tuning-edge-strength: 0.28;
}

/* Ambient vellum edge on outermost tunable scopes */
:where(html[data-spw-tuning-discoverability="ambient"], html[data-spw-tuning-discoverability="revealed"])
  :where(
    [data-spw-tuning-surface="true"][data-site-settings-scope],
    [data-spw-tuning-surface="true"][data-spw-affordance="tune"]
  ) {
  position: relative;
  border-inline-start: 2px solid color-mix(
    in srgb,
    var(--tuning-pulse-color) calc(var(--tuning-edge-strength) * 100%),
    transparent
  );
  background-image:
    linear-gradient(
      118deg,
      color-mix(in srgb, var(--tuning-pulse-color) 5%, transparent),
      transparent 42%
    );
  transition:
    border-color 220ms var(--ease-mechanical, ease),
    background-image 260ms var(--ease-mechanical, ease);
}

:where(html[data-spw-tuning-discoverability="revealed"])
  :where(
    [data-spw-tuning-surface="true"][data-site-settings-scope],
    [data-spw-tuning-surface="true"][data-spw-affordance="tune"],
    [data-spw-tuning-surface="true"][data-site-settings-panel],
    [data-spw-tuning-surface="true"].vibe-widget
  ) {
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--tuning-pulse-color) 12%, transparent),
    inset 3.2rem 0 0 -3rem color-mix(in srgb, var(--tuning-pulse-color) 6%, transparent);
}

:where(html[data-spw-tuning-discoverability="ambient"], html[data-spw-tuning-discoverability="revealed"])
  :where([data-spw-tuning-surface="true"]:is(:hover, :focus-within)) {
  border-inline-start-color: color-mix(in srgb, var(--tuning-pulse-color) 38%, transparent);
}

/* Corner marginalia sigils (revealed mode) */
:where(.spw-tuning-marginalia) {
  position: absolute;
  inset-block-start: 0.42rem;
  inset-inline-end: 0.5rem;
  z-index: 2;
  display: inline-flex;
  gap: 0.22rem;
  align-items: center;
  padding: 0.12rem 0.34rem;
  border-radius: 999px;
  border: 1px dashed color-mix(in srgb, var(--tuning-pulse-color) 28%, transparent);
  background: color-mix(in srgb, var(--surface-strong, rgba(255, 255, 255, 0.92)) 88%, var(--tuning-pulse-color) 12%);
  color: color-mix(in srgb, var(--tuning-pulse-color) 72%, var(--ink) 28%);
  font-family: var(--site-mono-font, "JetBrains Mono", monospace);
  font-size: 0.62rem;
  letter-spacing: 0.14em;
  line-height: 1;
  opacity: var(--tuning-marginalia-opacity, 0.5);
  pointer-events: none;
  text-transform: uppercase;
}

:where([data-spw-tuning-pulse="true"]) {
  animation: spw-tuning-pulse 1.1s var(--ease-mechanical, ease);
}

/* Embedded extension handles: component anatomy, not separate settings panels. */
:where([data-spw-embedded-tuning-host="true"]) {
  position: relative;
}

:where(.spw-embedded-tuning-handle) {
  --embedded-tuning-accent: var(--active-op-color, #008080);
  position: absolute;
  z-index: 5;
  inset-block-start: max(0.42rem, var(--component-pad-tight, 0.5rem));
  inset-inline-end: max(0.42rem, var(--component-pad-tight, 0.5rem));
  display: inline-flex;
  align-items: center;
  gap: 0.18rem;
  max-inline-size: min(100%, 22rem);
  padding: 0.12rem;
  border: 1px solid color-mix(in srgb, var(--embedded-tuning-accent) 18%, transparent);
  border-radius: 999px;
  background:
    linear-gradient(180deg, color-mix(in srgb, #fff 18%, transparent), transparent),
    color-mix(in srgb, var(--surface-strong, rgba(255, 255, 255, 0.92)) 88%, var(--embedded-tuning-accent) 12%);
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, #fff 32%, transparent),
    0 0.45rem 1.1rem color-mix(in srgb, var(--shadow-color, #111) 9%, transparent);
  font-family: var(--site-mono-font, "JetBrains Mono", monospace);
  font-size: 0.58rem;
  opacity: 0;
  pointer-events: none;
  transform: translateY(-0.18rem) scale(0.985);
  transform-origin: 100% 0;
  transition:
    opacity 160ms var(--ease-mechanical, ease),
    transform 180ms var(--ease-mechanical, ease),
    border-color 180ms var(--ease-mechanical, ease);
}

:where(.spw-embedded-tuning-handle[data-spw-hypermedia-extension]) {
  border-color: color-mix(in srgb, var(--embedded-tuning-accent) 24%, var(--line, rgba(0, 0, 0, 0.14)));
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--embedded-tuning-accent) 10%, transparent), transparent 64%),
    color-mix(in srgb, var(--surface-strong, rgba(255, 255, 255, 0.92)) 88%, var(--embedded-tuning-accent) 12%);
}

:where([data-spw-embedded-tuning-host="true"]:is(:hover, :focus-within) > .spw-embedded-tuning-handle),
:where(html[data-spw-tuning-discoverability="revealed"] .spw-embedded-tuning-handle),
:where(html[data-spw-cognitive-handles="on"] .spw-embedded-tuning-handle) {
  opacity: 0.96;
  pointer-events: auto;
  transform: translateY(0) scale(1);
}

:where(html[data-spw-tuning-discoverability="ambient"] .spw-embedded-tuning-handle) {
  opacity: 0.16;
}

:where(html[data-spw-tuning-discoverability="ambient"] [data-spw-embedded-tuning-host="true"]:is(:hover, :focus-within) > .spw-embedded-tuning-handle) {
  opacity: 0.9;
}

:where(.spw-embedded-tuning-handle__label) {
  padding-inline: 0.4rem 0.3rem;
  color: color-mix(in srgb, var(--embedded-tuning-accent) 58%, var(--ink-soft, #667) 42%);
  font-weight: 800;
  letter-spacing: 0.08em;
  line-height: 1;
  text-transform: uppercase;
}

:where(.spw-embedded-tuning-handle__chip) {
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 0.22rem;
  min-block-size: 1.35rem;
  padding: 0.12rem 0.38rem;
  border: 1px solid color-mix(in srgb, var(--embedded-tuning-accent) 18%, var(--line, rgba(0, 0, 0, 0.14)));
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface-strong, #fff) 92%, transparent);
  color: var(--ink-soft, rgba(14, 18, 20, 0.72));
  cursor: pointer;
  font: inherit;
  letter-spacing: 0.04em;
}

:where(.spw-embedded-tuning-handle[data-spw-hypermedia-extension] .spw-embedded-tuning-handle__chip) {
  min-inline-size: 3.2rem;
  justify-content: center;
}

:where(.spw-embedded-tuning-handle__chip:is(:hover, :focus-visible)) {
  border-color: color-mix(in srgb, var(--embedded-tuning-accent) 42%, transparent);
  color: var(--ink, #111);
  outline: none;
  transform: translateY(-0.04rem);
}

:where(.spw-embedded-tuning-handle__chip[data-site-setting-active="true"]) {
  border-color: color-mix(in srgb, var(--embedded-tuning-accent) 54%, transparent);
  background: color-mix(in srgb, var(--embedded-tuning-accent) 16%, var(--surface-strong, #fff));
  color: var(--ink, #111);
  font-weight: 800;
}

:where(.spw-embedded-tuning-handle__chip[data-spw-tuning-dimension="gesture"][data-site-setting-active="true"]) {
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--embedded-tuning-accent) 12%, transparent);
}

@media (max-width: 620px) {
  :where(.spw-embedded-tuning-handle) {
    inset-block-start: auto;
    inset-block-end: max(0.42rem, env(safe-area-inset-bottom));
    inset-inline-end: max(0.42rem, env(safe-area-inset-right));
    max-inline-size: calc(100% - 0.84rem);
  }

  :where(.spw-embedded-tuning-handle__label) {
    display: none;
  }

  :where(.spw-embedded-tuning-handle__chip) {
    min-block-size: 1.55rem;
    padding-inline: 0.42rem;
  }
}

@keyframes spw-tuning-pulse {
  0%, 100% {
    box-shadow: inset 0 0 0 0 transparent;
  }
  38% {
    box-shadow:
      inset 0 0 0 1px color-mix(in srgb, var(--tuning-pulse-color) 34%, transparent),
      0 0 0 6px color-mix(in srgb, var(--tuning-pulse-color) 12%, transparent);
  }
}

/* Shell lexicon strip: hypermedia extension vocabulary in the header menu */
:where(.spw-tuning-lexicon-strip) {
  display: grid;
  gap: 0.38rem;
  inline-size: 100%;
  padding: 0.48rem 0.55rem 0.55rem;
  border-block-start: 1px solid color-mix(in srgb, var(--spw-shell-chrome-accent-local, var(--active-op-color)) 14%, transparent);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--surface-strong) 92%, var(--active-op-color) 8%), transparent 72%);
}

:where(.spw-shell-tools-disclosure:not([open]) .spw-tuning-lexicon-strip) {
  display: none;
}

:where(.spw-tuning-lexicon-strip__kicker) {
  margin: 0;
  color: var(--ink-soft);
  font-family: var(--site-mono-font, "JetBrains Mono", monospace);
  font-size: 0.56rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

:where(.spw-tuning-lexicon-strip__chips) {
  display: flex;
  flex-wrap: wrap;
  gap: 0.34rem;
}

:where(.spw-tuning-lexicon-chip) {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
  min-block-size: 1.45rem;
  padding: 0.14rem 0.42rem;
  border: 1px solid color-mix(in srgb, var(--active-op-color) 18%, var(--line));
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface-strong) 90%, var(--active-op-color) 10%);
  color: var(--ink);
  font-size: 0.62rem;
  line-height: 1.1;
  text-decoration: none;
  white-space: nowrap;
}

:where(.spw-tuning-lexicon-chip__sigil) {
  opacity: 0.78;
}

:where(.spw-tuning-lexicon-strip__meta) {
  margin: 0;
  color: var(--ink-soft);
  font-size: 0.62rem;
  line-height: 1.35;
}

:where(.spw-tuning-lexicon-strip__actions) {
  display: flex;
  flex-wrap: wrap;
  gap: 0.34rem;
  align-items: center;
}

:where(.spw-tuning-lexicon-strip__actions .spw-shell-utility-button) {
  min-block-size: 1.5rem;
  padding-inline: 0.5rem;
  font-size: 0.58rem;
}

/* Settings route vocabulary atlas */
:where(body[data-spw-surface="settings"] .spw-tuning-vocabulary) {
  display: grid;
  gap: 0.65rem;
  margin-block: 0.85rem 0.2rem;
}

:where(body[data-spw-surface="settings"] .spw-tuning-vocabulary__grid) {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 13rem), 1fr));
  gap: 0.55rem;
}

:where(body[data-spw-surface="settings"] .spw-tuning-vocabulary-card) {
  display: grid;
  gap: 0.28rem;
  padding: 0.72rem 0.82rem;
  border: 1px solid color-mix(in srgb, var(--active-op-color) 14%, var(--line));
  border-radius: calc(var(--shape-surface, 10px) - 2px);
  background:
    linear-gradient(145deg, color-mix(in srgb, var(--active-op-color) 6%, var(--surface-strong)), transparent 58%),
    var(--surface-strong);
}

:where(body[data-spw-surface="settings"] .spw-tuning-vocabulary-card__topline) {
  display: flex;
  align-items: baseline;
  gap: 0.35rem;
}

:where(body[data-spw-surface="settings"] .spw-tuning-vocabulary-card__sigil) {
  font-size: 0.82rem;
  opacity: 0.82;
}

:where(body[data-spw-surface="settings"] .spw-tuning-vocabulary-card strong) {
  font-size: 0.92rem;
}

:where(body[data-spw-surface="settings"] .spw-tuning-vocabulary-card p) {
  margin: 0;
  color: var(--ink-soft);
  font-size: 0.78rem;
  line-height: 1.35;
}

:where(body[data-spw-surface="settings"] .spw-tuning-vocabulary-card__relation) {
  color: color-mix(in srgb, var(--active-op-color) 58%, var(--ink-soft) 42%);
  font-family: var(--site-mono-font, "JetBrains Mono", monospace);
  font-size: 0.62rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
}

/* /public/css/systems/surfaces/learnability-ledger.css */
@layer systems {
/* ==========================================================================
   surfaces/learnability-ledger.css
   --------------------------------------------------------------------------
   Metacognitive posture, feature learnability, layout-contract alignment,
   and gesture resonance — accounting for how the visitor relates to Spw
   features without rewriting authored content.
   ========================================================================== */

:where(html[data-spw-learnability-ledger="active"]) {
  --learnability-resonance-color: var(--active-op-color, #008080);
}

/* Footer posture accounting */
.site-footer__page-architecture-meta[data-spw-learnability-posture] {
  color: var(--ink-muted, rgba(14, 18, 20, 0.58));
  font-size: var(--text-size-2xs, 0.72rem);
  line-height: 1.45;
}

.site-footer__page-architecture-meta [data-spw-learnability-stance-label] {
  color: var(--ink, rgba(14, 18, 20, 0.92));
}

html[data-spw-learnability-resonance] .site-footer__page-architecture-meta[data-spw-learnability-posture] {
  color: color-mix(in srgb, var(--learnability-resonance-color) 42%, var(--ink-muted, rgba(14, 18, 20, 0.58)));
}

/* Layout contract alignment (developmental indicators) */
html[data-spw-developmental-indicators="on"] :where([data-spw-layout-contract="implicit"]) {
  outline: 1px dotted color-mix(in srgb, var(--op-probe-color, #4a2180) 24%, transparent);
  outline-offset: 3px;
}

html[data-spw-developmental-indicators="on"] :where([data-spw-layout-contract="slotted"]) {
  box-shadow: inset 3px 0 0 color-mix(in srgb, var(--active-op-color) 10%, transparent);
}

html[data-spw-developmental-indicators="on"] :where([data-spw-layout-contract="feature-gestural"]) {
  box-shadow: inset 3px 0 0 color-mix(in srgb, var(--op-action-color) 14%, transparent);
}

/* Feature tier discoverability */
html[data-spw-metacognitive-stance="composer"] :where([data-spw-learnability-tier="interactive"]),
html[data-spw-metacognitive-stance="composer"] :where([data-spw-learnability-tier="gestural"]) {
  --spw-perspective-salience: max(var(--spw-perspective-salience, 0), 0.32);
}

html[data-spw-metacognitive-stance="explorer"] :where([data-spw-learnability-tier="named"]) {
  --spw-perspective-salience: max(var(--spw-perspective-salience, 0), 0.24);
}

html[data-spw-metacognitive-stance="integrator"] :where([data-spw-layout-contract="slotted"]) {
  border-inline-start: 2px solid color-mix(in srgb, var(--op-ref-color) 18%, transparent);
}

html[data-spw-metacognitive-stance="overflow"] :where([data-spw-feature]) {
  --spw-perspective-salience: max(var(--spw-perspective-salience, 0), 0.28);
}

html[data-spw-developmental-indicators="on"] :where([data-spw-feature]) {
  box-shadow:
    var(--spw-local-shadow, none),
    0 0 0 calc(1px * var(--spw-perspective-salience, 0))
    color-mix(in srgb, var(--spw-perspective-salience-color, var(--active-op-color)) 36%, transparent);
}

html[data-spw-developmental-indicators="on"] :where([data-spw-feature]:is(:hover, :focus-within)) {
  --spw-perspective-salience: max(var(--spw-perspective-salience, 0), 0.62);
}

/* Process-attention resonance with gesture anatomy */
html[data-spw-learnability-process="compose"] :where([data-spw-gesture-hint])::after,
html[data-spw-learnability-process="trace"] :where([data-spw-gesture-hint])::after {
  border-color: color-mix(in srgb, var(--op-action-color) 34%, transparent);
}

html[data-spw-learnability-process="scan"] :where(.spw-tuning-marginalia) {
  opacity: max(var(--tuning-marginalia-opacity, 0.5), 0.72);
}

html[data-spw-learnability-resonance] :where(
  [data-spw-feature="cauldron"],
  [data-spw-tuning-surface="true"],
  [data-spw-gesture-hint]
) {
  animation: learnability-resonance-pulse 1.1s ease-out 1;
}

@keyframes learnability-resonance-pulse {
  0% {
    box-shadow: 0 0 0 0 color-mix(in srgb, var(--learnability-resonance-color) 24%, transparent);
  }
  70% {
    box-shadow: 0 0 0 5px color-mix(in srgb, var(--learnability-resonance-color) 8%, transparent);
  }
  100% {
    box-shadow: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  html[data-spw-learnability-resonance] :where(
    [data-spw-feature="cauldron"],
    [data-spw-tuning-surface="true"],
    [data-spw-gesture-hint]
  ) {
    animation: none;
  }
}
}

/* /public/css/systems/surfaces/palette-depth.css */
@layer systems {
/* ==========================================================================
   surfaces/palette-depth.css
   --------------------------------------------------------------------------
   Palette depth layers: shadow, wash, glow, and atmospheric probes that make
   theme packs and resonance bias feel like layered metaphysical material.
   ========================================================================== */

:root {
  --palette-depth-strength: 1;
  --spw-palette-depth-shadow: color-mix(
    in srgb,
    var(--spw-palette-probe-1, var(--active-op-color)) calc(58% * var(--palette-depth-strength)),
    #101418 calc(42% * var(--palette-depth-strength))
  );
  --spw-palette-depth-mid: color-mix(
    in srgb,
    var(--spw-palette-probe-2, var(--op-object-color)) calc(44% * var(--palette-depth-strength)),
    var(--surface-strong) calc(56% * var(--palette-depth-strength))
  );
  --spw-palette-depth-highlight: color-mix(
    in srgb,
    var(--spw-palette-probe-1, var(--active-op-color)) calc(24% * var(--palette-depth-strength)),
    #fff calc(76% * var(--palette-depth-strength))
  );
  --spw-palette-depth-wash: color-mix(
    in srgb,
    var(--spw-palette-probe-1, var(--active-op-color)) calc(9% * var(--palette-depth-strength)),
    transparent
  );
  --spw-palette-depth-glow: color-mix(
    in srgb,
    var(--spw-palette-probe-4, var(--op-probe-color)) calc(18% * var(--palette-depth-strength)),
    transparent
  );
  --spw-palette-depth-field: color-mix(
    in srgb,
    var(--spw-palette-probe-3, var(--op-ref-color)) calc(12% * var(--palette-depth-strength)),
    var(--surface-strong) calc(88% * var(--palette-depth-strength))
  );
}

html[data-spw-color-tuner="soft"] {
  --palette-depth-strength: 0.72;
  --pigment-lighting-guard: 0.22;
}

html[data-spw-color-tuner="guarded"],
html[data-spw-high-contrast="on"] {
  --palette-depth-strength: 1.18;
  --pigment-lighting-guard: 0.52;
}

/* Resonance-specific depth bias */
html[data-spw-palette-resonance="craft"] {
  --spw-palette-depth-mid: color-mix(in srgb, var(--spw-palette-probe-2) 52%, var(--spw-palette-probe-3) 48%);
  --spw-palette-depth-wash: color-mix(in srgb, var(--spw-palette-probe-2) 11%, transparent);
}

html[data-spw-palette-resonance="software"] {
  --spw-palette-depth-glow: color-mix(in srgb, var(--spw-palette-probe-3) 22%, transparent);
  --spw-palette-depth-field: color-mix(in srgb, var(--spw-palette-probe-1) 10%, var(--surface-strong) 90%);
}

html[data-spw-palette-resonance="math"] {
  --spw-palette-depth-highlight: color-mix(in srgb, var(--spw-palette-probe-4) 20%, #fff 80%);
  --spw-palette-depth-shadow: color-mix(in srgb, var(--spw-palette-probe-3) 48%, #0d1218 52%);
}

/* Theme pack atmospheric depth */
html[data-spw-theme-pack="ritual-vellum"] {
  --spw-palette-depth-wash: color-mix(in srgb, var(--spw-palette-probe-4) 14%, transparent);
  --spw-palette-depth-field: color-mix(in srgb, var(--spw-palette-probe-2) 8%, var(--surface-strong) 92%);
}

html[data-spw-theme-pack="oxide-ledger"],
html[data-spw-theme-pack="copper-brace"] {
  --spw-palette-depth-mid: color-mix(in srgb, var(--spw-palette-probe-2) 58%, var(--spw-palette-probe-1) 42%);
  --spw-palette-depth-shadow: color-mix(in srgb, var(--spw-palette-probe-2) 36%, #1a100c 64%);
}

html[data-spw-theme-pack="electric-studio"],
html[data-spw-theme-pack="glass-console"] {
  --spw-palette-depth-glow: color-mix(in srgb, var(--spw-palette-probe-3) 26%, transparent);
  --spw-palette-depth-highlight: color-mix(in srgb, var(--spw-palette-probe-1) 18%, #fff 82%);
}

/* Apply depth to tuning surfaces and palette probes */
:where(.vibe-widget, .palette-probe) {
  background:
    radial-gradient(circle at 84% 8%, var(--spw-palette-depth-glow), transparent 38%),
    linear-gradient(
      155deg,
      var(--spw-palette-depth-wash),
      transparent 48%,
      color-mix(in srgb, var(--spw-palette-depth-field) 72%, transparent) 100%
    ),
    var(--spw-shell-panel-bg-strong, var(--surface-strong));
  box-shadow:
    inset 0 1px 0 var(--spw-palette-depth-highlight),
    inset 0 -1px 0 color-mix(in srgb, var(--spw-palette-depth-shadow) 22%, transparent),
    var(--card-highlight, none),
    var(--card-shadow, none);
}

:where(.palette-probe-chip--depth-shadow) {
  background: var(--spw-palette-depth-shadow);
}

:where(.palette-probe-chip--depth-highlight) {
  background: var(--spw-palette-depth-highlight);
}

:where(.palette-probe-chip--depth-glow) {
  background: var(--spw-palette-depth-glow);
}

:where(.palette-probe-swatches--depth) {
  gap: 0.34rem;
  margin-block-start: 0.12rem;
  padding: 0.28rem 0.34rem;
  border: 1px dashed color-mix(in srgb, var(--spw-palette-probe-3) 16%, transparent);
  border-radius: 0.55rem;
  background: color-mix(in srgb, var(--spw-palette-depth-field) 42%, transparent);
}

:where(.palette-probe-swatches--depth)::before {
  content: "depth";
  display: inline-flex;
  align-items: center;
  margin-inline-end: 0.18rem;
  color: var(--ink-soft);
  font-family: var(--site-mono-font, "JetBrains Mono", monospace);
  font-size: 0.52rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

:where(.palette-probe-chip--depth-shadow, .palette-probe-chip--depth-highlight, .palette-probe-chip--depth-glow) {
  inline-size: 1.02rem;
  block-size: 1.02rem;
  border-radius: 999px;
}

:where(.palette-probe-swatches) {
  position: relative;
}

:where(.palette-probe-swatches)::after {
  content: "";
  position: absolute;
  inset: -0.18rem;
  border-radius: 0.55rem;
  background: radial-gradient(circle at 30% 20%, var(--spw-palette-depth-glow), transparent 62%);
  opacity: 0.55;
  pointer-events: none;
  z-index: 0;
}

:where(.palette-probe-chip) {
  position: relative;
  z-index: 1;
  transition:
    transform var(--spw-microinteraction-pulse-duration, 280ms) var(--ease-settle, ease),
    box-shadow var(--spw-microinteraction-pulse-duration, 280ms) var(--ease-settle, ease),
    border-color var(--duration-fast, 140ms) var(--ease-mechanical, ease),
    filter var(--duration-fast, 140ms) var(--ease-mechanical, ease);
}

:where(.palette-probe-chip:not([class*="--depth"]):is(:hover, :focus-visible)) {
  transform: translateY(-1px) scale(1.04);
}

:where(.palette-probe-swatches:not(.palette-probe-swatches--depth) .palette-probe-chip:nth-child(1):is(:hover, :focus-visible)) {
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 28%, transparent),
    0 0 0 1px color-mix(in srgb, var(--spw-palette-probe-1) 28%, transparent),
    0 0 10px color-mix(in srgb, var(--spw-palette-probe-1) 24%, transparent);
}

:where(.palette-probe-swatches:not(.palette-probe-swatches--depth) .palette-probe-chip:nth-child(2):is(:hover, :focus-visible)) {
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 28%, transparent),
    0 0 0 1px color-mix(in srgb, var(--spw-palette-probe-2) 28%, transparent),
    0 0 10px color-mix(in srgb, var(--spw-palette-probe-2) 24%, transparent);
}

:where(.palette-probe-swatches:not(.palette-probe-swatches--depth) .palette-probe-chip:nth-child(3):is(:hover, :focus-visible)) {
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 28%, transparent),
    0 0 0 1px color-mix(in srgb, var(--spw-palette-probe-3) 28%, transparent),
    0 0 10px color-mix(in srgb, var(--spw-palette-probe-3) 24%, transparent);
}

:where(.palette-probe-swatches:not(.palette-probe-swatches--depth) .palette-probe-chip:nth-child(4):is(:hover, :focus-visible)) {
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 28%, transparent),
    0 0 0 1px color-mix(in srgb, var(--spw-palette-probe-4) 28%, transparent),
    0 0 10px color-mix(in srgb, var(--spw-palette-probe-4) 24%, transparent);
}

:where(.spw-shell-resonance-utility .palette-probe-chip--shell:is(:hover, :focus-visible)) {
  transform: scale(1.12);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.28),
    0 0 0 1px color-mix(in srgb, var(--spw-palette-treat-accent, var(--spw-palette-probe-1)) 24%, transparent),
    0 2px 6px color-mix(in srgb, var(--spw-palette-depth-shadow) 18%, transparent);
}

/* Shell theme utility depth */
:where(.spw-shell-theme-utility) {
  display: inline-flex;
  align-items: center;
  gap: 0.18rem;
  padding: 0.1rem;
  border: 1px solid color-mix(in srgb, var(--spw-palette-probe-1) 14%, var(--spw-shell-line));
  border-radius: 999px;
  background:
    linear-gradient(180deg, var(--spw-palette-depth-highlight), transparent 58%),
    color-mix(in srgb, var(--surface-strong) 88%, var(--spw-palette-depth-wash) 12%);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--spw-palette-depth-highlight) 40%, transparent);
}

:where(.spw-shell-theme-utility .theme-pack-chip-btn) {
  inline-size: 1.22rem;
  block-size: 1.22rem;
  border-radius: 999px;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.22),
    0 2px 5px color-mix(in srgb, var(--spw-palette-depth-shadow) 18%, transparent);
}

:where(.spw-shell-theme-utility .theme-pack-chip-btn[data-site-setting-active="true"]) {
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--spw-palette-probe-1) 34%, transparent),
    0 0 0 2px var(--spw-palette-depth-glow);
}

/* Live resonance swatches beside the cycle control */
:where(.spw-shell-resonance-utility) {
  display: inline-flex;
  align-items: center;
  gap: 0.1rem;
  padding: 0.1rem 0.14rem;
  border: 1px solid color-mix(in srgb, var(--spw-palette-probe-1) 12%, var(--spw-shell-line));
  border-radius: 999px;
  background:
    radial-gradient(circle at 80% 12%, var(--spw-palette-depth-glow), transparent 58%),
    color-mix(in srgb, var(--surface-strong) 90%, var(--spw-palette-depth-wash) 10%);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--spw-palette-depth-highlight) 34%, transparent);
}

:where(.spw-shell-resonance-utility .palette-probe-chip--shell) {
  inline-size: 0.68rem;
  block-size: 0.68rem;
  border-radius: 999px;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.2),
    0 1px 3px color-mix(in srgb, var(--spw-palette-depth-shadow) 14%, transparent);
}

:where(.spw-shell-resonance-utility .palette-probe-chip--shell:nth-child(1)) {
  background: var(--spw-palette-probe-1, var(--active-op-color, #008080));
}

:where(.spw-shell-resonance-utility .palette-probe-chip--shell:nth-child(2)) {
  background: var(--spw-palette-probe-2, var(--op-object-color, #c68a22));
}

:where(.spw-shell-resonance-utility .palette-probe-chip--shell:nth-child(3)) {
  background: var(--spw-palette-probe-3, var(--op-ref-color, #1d57a3));
}

:where(.spw-shell-resonance-utility .palette-probe-chip--shell:nth-child(4)) {
  background: var(--spw-palette-probe-4, var(--op-probe-color, #6a3fb8));
}
}

/* /public/css/systems/palette-treat.css */
@layer systems {
/* ==========================================================================
   palette-treat.css
   --------------------------------------------------------------------------
   Discoverable palette treats: probe-chip splashes and operator resonance echo.
   ========================================================================== */

:root {
  --spw-palette-treat-strength: 0;
  --spw-palette-treat-accent: var(--spw-palette-probe-1, var(--active-op-color, #008080));
  --spw-palette-treat-ring: transparent;
  /* Session-depth gain: escalates the sprinkle the deeper the reader is into a
     rich, settled session. Written from palette-treat-discovery.js via
     data-spw-palette-treat-depth (0..4). 1 = first-visit baseline. */
  --spw-palette-treat-depth-gain: 1;
}

/* These live-state overrides target the root element, so they must out-specify
   the :root defaults above — otherwise :root (specificity 0,1,0) wins and the
   sprinkle strength/accent stay pinned to their resting values. :root[attr]
   (0,2,0) clears that bar; :where(html[attr]) does NOT (it is specificity 0),
   so do not "simplify" these back to :where — it silently disables the treat. */
:root[data-spw-palette-treat-depth="1"] { --spw-palette-treat-depth-gain: 1.12; }
:root[data-spw-palette-treat-depth="2"] { --spw-palette-treat-depth-gain: 1.26; }
:root[data-spw-palette-treat-depth="3"] { --spw-palette-treat-depth-gain: 1.42; }
:root[data-spw-palette-treat-depth="4"] { --spw-palette-treat-depth-gain: 1.6; }

:root[data-spw-palette-treat-active="on"] {
  --spw-palette-treat-strength: calc(
    var(--spw-freshness-weight, 0.62)
    * var(--spw-microinteraction-pulse-intensity, 1)
    * var(--spw-palette-treat-depth-gain, 1)
  );
  --palette-depth-strength: calc(var(--palette-depth-strength, 1) * (1 + (var(--spw-palette-treat-strength) * 0.1)));
}

:root[data-spw-palette-treat-probe="1"] {
  --spw-palette-treat-accent: var(--spw-palette-probe-1, var(--active-op-color, #008080));
}

:root[data-spw-palette-treat-probe="2"] {
  --spw-palette-treat-accent: var(--spw-palette-probe-2, var(--op-object-color, #c68a22));
}

:root[data-spw-palette-treat-probe="3"] {
  --spw-palette-treat-accent: var(--spw-palette-probe-3, var(--op-ref-color, #1d57a3));
}

:root[data-spw-palette-treat-probe="4"] {
  --spw-palette-treat-accent: var(--spw-palette-probe-4, var(--op-probe-color, #6a3fb8));
}

:where(html[data-spw-palette-treat-active="on"]) :where(.palette-probe, .spw-shell-resonance-utility) {
  border-color: color-mix(
    in srgb,
    var(--spw-palette-treat-accent) calc(18% + (var(--spw-palette-treat-strength) * 14%)),
    var(--spw-shell-line, var(--line))
  );
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--spw-palette-depth-highlight, #fff) 42%, transparent),
    0 0 calc(18px * var(--spw-palette-treat-strength))
      color-mix(in srgb, var(--spw-palette-treat-accent) 16%, transparent);
}

:where(html[data-spw-palette-treat-active="on"]) :where(.palette-probe-swatches:not(.palette-probe-swatches--depth))::after {
  opacity: calc(0.58 + (var(--spw-palette-treat-strength) * 0.42));
  background: radial-gradient(
    circle at 34% 22%,
    color-mix(in srgb, var(--spw-palette-treat-accent) 46%, transparent),
    transparent 64%
  );
}

/* Keyboard navigability + arrow-reward focus spend */
:where(.palette-probe-chip:focus-visible) {
  outline: 2px solid color-mix(in srgb, var(--spw-palette-treat-accent, var(--spw-palette-probe-1)) 68%, transparent);
  outline-offset: 3px;
  z-index: 3;
}

:where(.palette-probe-chip[aria-checked="true"]:focus-visible) {
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 30%, transparent),
    0 0 0 2px color-mix(in srgb, var(--spw-palette-treat-accent, var(--spw-palette-probe-1)) 34%, transparent),
    0 0 12px color-mix(in srgb, var(--spw-palette-treat-accent, var(--spw-palette-probe-1)) 22%, transparent);
}

:where(html[data-spw-palette-splash="arrow-reward"]) {
  --spw-salience-weight: max(var(--spw-salience-weight, 0.34), calc(0.52 + (var(--spw-freshness-weight, 0.62) * 0.18)));
}

:where(html[data-spw-palette-splash="arrow-reward"]) :where(
  .palette-probe-chip[data-spw-palette-treat="true"],
  .palette-probe-chip[aria-checked="true"]
) {
  animation: spw-palette-treat-spark var(--spw-microinteraction-pulse-duration, 280ms) var(--ease-settle, ease);
}

:where(html[data-spw-palette-probe-rail="ready"]) :where(.palette-probe-chip[aria-checked="true"]) {
  transform: scale(1.06);
  border-color: color-mix(in srgb, var(--spw-palette-probe-1) 34%, var(--spw-shell-line, var(--line)));
}

:where(.palette-probe-actions[role="toolbar"] .operator-chip:focus-visible),
:where(.vibe-widget-actions[role="toolbar"] .operator-chip:focus-visible) {
  outline: 2px solid color-mix(in srgb, var(--spw-palette-probe-1) 52%, transparent);
  outline-offset: 2px;
}

:where(.palette-probe-chip[data-spw-palette-treat="true"]) {
  --spw-palette-treat-ring: color-mix(
    in srgb,
    var(--spw-palette-treat-accent, var(--spw-palette-probe-1)) calc(34% + (var(--spw-palette-treat-strength, 0.62) * 22%)),
    transparent
  );
  transform: scale(calc(1 + (0.14 * var(--spw-palette-treat-strength, 0.62))));
  border-color: color-mix(in srgb, var(--spw-palette-treat-accent) 42%, var(--spw-shell-line, var(--line)));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 34%, transparent),
    0 0 0 2px var(--spw-palette-treat-ring),
    0 0 calc(14px * var(--spw-palette-treat-strength, 0.62)) var(--spw-palette-treat-ring),
    0 4px 10px color-mix(in srgb, var(--spw-palette-depth-shadow, #101418) 12%, transparent);
  z-index: 2;
}

:where(html[data-spw-palette-treat-active="on"]) :where(
  .palette-probe-swatches:not(.palette-probe-swatches--depth) .palette-probe-chip:not([data-spw-palette-treat="true"]),
  .spw-shell-resonance-utility .palette-probe-chip:not([data-spw-palette-treat="true"])
) {
  opacity: calc(0.82 + (var(--spw-palette-treat-strength, 0.62) * 0.08));
  filter: saturate(0.9);
}

:where(html[data-spw-palette-splash="discovery"]) :where(
  .palette-probe-chip[data-spw-palette-treat="true"],
  .palette-probe-chip--depth-glow
) {
  animation: spw-palette-treat-spark var(--spw-microinteraction-pulse-duration, 280ms) var(--ease-settle, ease);
}

@keyframes spw-palette-treat-spark {
  0% { filter: saturate(1) brightness(1); }
  42% { filter: saturate(1.22) brightness(1.08); }
  100% { filter: saturate(1) brightness(1); }
}

/* Beat-aware idle resonance on probe chips */
:where(html[data-spw-playing="on"][data-spw-beat="1"]) :where(
  .palette-probe-swatches:not(.palette-probe-swatches--depth) .palette-probe-chip:nth-child(1),
  .spw-shell-resonance-utility .palette-probe-chip:nth-child(1)
) {
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 24%, transparent),
    0 0 0 1px color-mix(in srgb, var(--spw-palette-probe-1) 22%, transparent);
}

:where(html[data-spw-playing="on"][data-spw-beat="5"]) :where(
  .palette-probe-swatches:not(.palette-probe-swatches--depth) .palette-probe-chip:nth-child(2),
  .spw-shell-resonance-utility .palette-probe-chip:nth-child(2)
) {
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 24%, transparent),
    0 0 0 1px color-mix(in srgb, var(--spw-palette-probe-2) 22%, transparent);
}

:where(html[data-spw-playing="on"][data-spw-beat="9"]) :where(
  .palette-probe-swatches:not(.palette-probe-swatches--depth) .palette-probe-chip:nth-child(3),
  .spw-shell-resonance-utility .palette-probe-chip:nth-child(3)
) {
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 24%, transparent),
    0 0 0 1px color-mix(in srgb, var(--spw-palette-probe-3) 22%, transparent);
}

:where(html[data-spw-playing="on"][data-spw-beat="13"]) :where(
  .palette-probe-swatches:not(.palette-probe-swatches--depth) .palette-probe-chip:nth-child(4),
  .spw-shell-resonance-utility .palette-probe-chip:nth-child(4)
) {
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 24%, transparent),
    0 0 0 1px color-mix(in srgb, var(--spw-palette-probe-4) 22%, transparent);
}

/* Operator echo during active treat */
:where(html[data-spw-palette-treat-probe="1"]) :where([data-spw-operator="frame"], [data-spw-operator="surface"]) {
  --spw-resonance: calc(var(--spw-palette-treat-strength, 0.62) * 0.72);
}

:where(html[data-spw-palette-treat-probe="2"]) :where([data-spw-operator="object"], [data-spw-operator="topic"]) {
  --spw-resonance: calc(var(--spw-palette-treat-strength, 0.62) * 0.72);
}

:where(html[data-spw-palette-treat-probe="3"]) :where([data-spw-operator="ref"], [data-spw-operator="stream"]) {
  --spw-resonance: calc(var(--spw-palette-treat-strength, 0.62) * 0.72);
}

:where(html[data-spw-palette-treat-probe="4"]) :where([data-spw-operator="probe"], [data-spw-operator="action"]) {
  --spw-resonance: calc(var(--spw-palette-treat-strength, 0.62) * 0.72);
}

:where(html[data-spw-reduce-motion="on"][data-spw-palette-treat-active="on"]) {
  --spw-palette-treat-strength: 0;
}

:where(html[data-spw-reduce-motion="on"]) :where(.palette-probe-chip[data-spw-palette-treat="true"]) {
  animation: none;
  transform: none;
}
}

/* /public/css/systems/spw-key-events.css */
@layer systems {
/* ==========================================================================
   spw-key-events.css
   --------------------------------------------------------------------------
   Potentiation threads, scene-context depth, and staged information reveals.
   ========================================================================== */

:root {
  --spw-key-potential-strength: 0;
  --spw-scene-context-strength: 0;
  --spw-reveal-phase-weight: 0;
  --spw-reveal-duration: var(--spw-wonder-duration-deliberate, 420ms);
  --spw-reveal-duration-fast: var(--spw-wonder-duration-fast, 120ms);
  --spw-reveal-ease: var(--spw-wonder-ease-settle, cubic-bezier(0.22, 1, 0.36, 1));
  --spw-reveal-stagger-step: var(--spw-medium-reveal-stagger-step, 72ms);
  --spw-reveal-frame-strength: 0;
}

:where(html[data-spw-key-selection="potentiated"]) {
  --spw-key-potential-strength: calc(0.42 + (var(--spw-freshness-weight, 0.5) * 0.2));
}

:where(html[data-spw-key-selection="actualized"]) {
  --spw-key-potential-strength: calc(0.62 + (var(--spw-freshness-weight, 0.5) * 0.28));
}

:where(html[data-spw-scene-depth]) {
  --spw-scene-context-strength: calc(0.18 + (min(3, var(--spw-scene-depth, 0)) * 0.12));
}

:where(html[data-spw-reveal-phase="framing"]) {
  --spw-reveal-frame-strength: calc(0.28 + (var(--spw-reveal-phase-weight, 0.35) * 0.4));
}

:where(html[data-spw-reveal-phase="revealing"]) {
  --spw-reveal-frame-strength: calc(0.52 + (var(--spw-reveal-phase-weight, 0.72) * 0.35));
}

:where(html[data-spw-reveal-phase="revealed"]) {
  --spw-reveal-frame-strength: calc(0.68 + (var(--spw-reveal-phase-weight, 1) * 0.22));
}

:where(html[data-spw-reveal-phase="settling"]) {
  --spw-reveal-frame-strength: calc(0.22 + (var(--spw-reveal-phase-weight, 0.28) * 0.3));
}

:where(html[data-spw-information-reveal="on"]) {
  --spw-microinteraction-pulse-intensity: calc(1 + (var(--spw-reveal-phase-weight, 0) * 0.18));
}

:where([data-spw-selection-state="potentiated"]) {
  outline: 1px solid color-mix(
    in srgb,
    var(--op-ref-color, #1d57a3) calc(24% + (var(--spw-key-potential-strength) * 22%)),
    transparent
  );
  outline-offset: 3px;
  box-shadow:
    0 0 0 calc(1px * var(--spw-key-potential-strength))
    color-mix(in srgb, var(--op-ref-color, #1d57a3) 18%, transparent);
  transition:
    outline-color var(--spw-reveal-duration-fast) var(--spw-reveal-ease),
    box-shadow var(--spw-reveal-duration) var(--spw-reveal-ease),
    outline-offset var(--spw-reveal-duration-fast) var(--spw-reveal-ease);
}

:where([data-spw-selection-state="actualized"]) {
  outline: 1px solid color-mix(
    in srgb,
    var(--op-frame-color, #008080) calc(34% + (var(--spw-key-potential-strength) * 24%)),
    transparent
  );
  outline-offset: 4px;
  transition:
    outline-color var(--spw-reveal-duration) var(--spw-reveal-ease),
    outline-offset var(--spw-reveal-duration) var(--spw-reveal-ease);
}

:where([data-spw-reveal-frame="arming"]) {
  transform: translateY(1px) scale(0.998);
  transition:
    transform var(--spw-reveal-duration) var(--spw-reveal-ease),
    box-shadow var(--spw-reveal-duration) var(--spw-reveal-ease);
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--op-ref-color, #1d57a3) calc(12% + (var(--spw-reveal-frame-strength) * 18%)), transparent),
    0 10px 24px color-mix(in srgb, var(--shadow, #000) 6%, transparent);
}

:where([data-spw-reveal-frame="open"]),
:where([data-spw-scene-state="entered"]) {
  position: relative;
  transition:
    transform var(--spw-reveal-duration) var(--spw-reveal-ease),
    box-shadow var(--spw-reveal-duration) var(--spw-reveal-ease);
  --spw-local-shadow:
    0 0 0 1px color-mix(in srgb, var(--op-frame-color, #008080) calc(18% + (var(--spw-reveal-frame-strength) * 20%)), transparent),
    0 14px 34px color-mix(in srgb, var(--shadow, #000) calc(8% + (var(--spw-scene-context-strength) * 10%)), transparent);
}

:where([data-spw-reveal-frame="open"])::before,
:where([data-spw-scene-state="entered"])::before {
  content: "";
  position: absolute;
  inset: -0.42rem;
  border-radius: calc(var(--component-radius, 12px) + 0.35rem);
  border: 1px solid color-mix(
    in srgb,
    var(--op-frame-color, #008080) calc(16% + (var(--spw-reveal-frame-strength) * 28%)),
    transparent
  );
  pointer-events: none;
  opacity: calc(0.35 + (var(--spw-reveal-frame-strength) * 0.55));
  animation: spw-reveal-frame-breathe var(--spw-reveal-duration) var(--spw-reveal-ease) both;
}

:where([data-spw-reveal-frame="closing"]) {
  opacity: 0.92;
  transform: translateY(2px) scale(0.996);
  transition:
    opacity var(--spw-reveal-duration-fast) var(--spw-reveal-ease),
    transform var(--spw-reveal-duration) var(--spw-reveal-ease);
}

:where(html[data-spw-scene-depth]) :where(main, body) {
  background-image: radial-gradient(
    120% 80% at 50% 0%,
    color-mix(in srgb, var(--op-frame-color, #008080) calc(var(--spw-scene-context-strength) * 8%), transparent),
    transparent 68%
  );
  transition: background-image var(--spw-reveal-duration) var(--spw-reveal-ease);
}

:where(html[data-spw-reveal-phase="revealing"], html[data-spw-reveal-phase="revealed"]) :where(main, body) {
  background-image:
    radial-gradient(
      118% 82% at 50% -4%,
      color-mix(
        in srgb,
        var(--op-probe-color, #6a3fb8) calc(4% + (var(--spw-reveal-phase-weight, 0) * 10%)),
        transparent
      ),
      transparent 70%
    ),
    radial-gradient(
      120% 80% at 50% 0%,
      color-mix(in srgb, var(--op-frame-color, #008080) calc(var(--spw-scene-context-strength) * 10%), transparent),
      transparent 68%
    );
}

:where([data-spw-scene-state="entered"] .spw-scene-bed__lane),
:where([data-spw-scene-state="entered"] [data-spw-scene-lane]),
:where([data-spw-reveal-frame="open"] .spw-scene-bed__lane),
:where([data-spw-reveal-frame="open"] [data-spw-scene-lane]) {
  border-inline-start: 2px solid color-mix(
    in srgb,
    var(--op-probe-color, #6a3fb8) calc(20% + (var(--spw-scene-context-strength) * 30%)),
    transparent
  );
  padding-inline-start: 0.55rem;
  opacity: 0;
  transform: translateY(6px);
  animation: spw-reveal-lane-rise var(--spw-reveal-duration) var(--spw-reveal-ease) forwards;
}

:where([data-spw-scene-state="entered"] .spw-scene-bed__lane:nth-child(1)),
:where([data-spw-scene-state="entered"] [data-spw-scene-lane]:nth-child(1)),
:where([data-spw-reveal-frame="open"] .spw-scene-bed__lane:nth-child(1)),
:where([data-spw-reveal-frame="open"] [data-spw-scene-lane]:nth-child(1)) {
  animation-delay: calc(var(--spw-reveal-stagger-step) * 0);
}

:where([data-spw-scene-state="entered"] .spw-scene-bed__lane:nth-child(2)),
:where([data-spw-scene-state="entered"] [data-spw-scene-lane]:nth-child(2)),
:where([data-spw-reveal-frame="open"] .spw-scene-bed__lane:nth-child(2)),
:where([data-spw-reveal-frame="open"] [data-spw-scene-lane]:nth-child(2)) {
  animation-delay: calc(var(--spw-reveal-stagger-step) * 1);
}

:where([data-spw-scene-state="entered"] .spw-scene-bed__lane:nth-child(3)),
:where([data-spw-scene-state="entered"] [data-spw-scene-lane]:nth-child(3)),
:where([data-spw-reveal-frame="open"] .spw-scene-bed__lane:nth-child(3)),
:where([data-spw-reveal-frame="open"] [data-spw-scene-lane]:nth-child(3)) {
  animation-delay: calc(var(--spw-reveal-stagger-step) * 2);
}

:where(.spw-wonder-block[data-spw-reveal-source="scene-enter"]),
:where(.spw-wonder-block[data-spw-reveal-source="preview"]) {
  transform-origin: top center;
  transition:
    opacity var(--spw-reveal-duration) var(--spw-reveal-ease),
    transform var(--spw-reveal-duration) var(--spw-reveal-ease),
    box-shadow var(--spw-reveal-duration) var(--spw-reveal-ease),
    border-color var(--spw-reveal-duration) var(--spw-reveal-ease);
}

:where(.spw-wonder-block[data-spw-reveal-source="scene-enter"][data-spw-wonder-block-state="thinking"]),
:where(.spw-wonder-block[data-spw-reveal-source="preview"][data-spw-wonder-block-state="thinking"]) {
  opacity: 0.78;
  transform: translateY(8px) scale(0.992);
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--wonder-accent-color, var(--op-probe-color, #6a3fb8)) 18%, transparent),
    0 8px 20px color-mix(in srgb, var(--shadow, #000) 5%, transparent);
}

:where(.spw-wonder-block[data-spw-reveal-source="scene-enter"][data-spw-wonder-block-state="thinking"]) .wonder-body,
:where(.spw-wonder-block[data-spw-reveal-source="preview"][data-spw-wonder-block-state="thinking"]) .wonder-body {
  opacity: 0.62;
  filter: blur(0.3px);
  transition: opacity var(--spw-reveal-duration-fast) var(--spw-reveal-ease);
}

:where(.spw-wonder-block[data-spw-reveal-source="scene-enter"][data-spw-wonder-block-state="revealed"]),
:where(.spw-wonder-block[data-spw-reveal-source="scene-enter"][data-spw-wonder-block-state="expanded"]),
:where(.spw-wonder-block[data-spw-reveal-source="preview"][data-spw-wonder-block-state="revealed"]),
:where(.spw-wonder-block[data-spw-reveal-source="preview"][data-spw-wonder-block-state="expanded"]) {
  opacity: 1;
  transform: translateY(0) scale(1);
  animation: spw-reveal-wonder-settle var(--spw-reveal-duration) var(--spw-reveal-ease) both;
}

:where(.spw-wonder-block[data-spw-reveal-source="scene-enter"][data-spw-wonder-block-state="revealed"]) .wonder-body,
:where(.spw-wonder-block[data-spw-reveal-source="scene-enter"][data-spw-wonder-block-state="expanded"]) .wonder-body,
:where(.spw-wonder-block[data-spw-reveal-source="preview"][data-spw-wonder-block-state="revealed"]) .wonder-body,
:where(.spw-wonder-block[data-spw-reveal-source="preview"][data-spw-wonder-block-state="expanded"]) .wonder-body {
  opacity: 1;
  filter: none;
  animation: spw-reveal-body-unveil calc(var(--spw-reveal-duration) * 1.1) var(--spw-reveal-ease) both;
}

@keyframes spw-reveal-frame-breathe {
  from {
    opacity: 0;
    transform: scale(0.985);
  }
  to {
    opacity: calc(0.35 + (var(--spw-reveal-frame-strength) * 0.55));
    transform: scale(1);
  }
}

@keyframes spw-reveal-lane-rise {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes spw-reveal-wonder-settle {
  from {
    opacity: 0.7;
    transform: translateY(10px) scale(0.988);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes spw-reveal-body-unveil {
  from {
    opacity: 0.45;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  :where([data-spw-selection-state="potentiated"], [data-spw-selection-state="actualized"]) {
    transition: none;
  }

  :where([data-spw-reveal-frame="arming"], [data-spw-reveal-frame="open"], [data-spw-reveal-frame="closing"]) {
    transform: none;
    transition: none;
  }

  :where([data-spw-scene-state="entered"] .spw-scene-bed__lane),
  :where([data-spw-scene-state="entered"] [data-spw-scene-lane]),
  :where(.spw-wonder-block[data-spw-reveal-source="scene-enter"]) {
    animation: none;
    opacity: 1;
    transform: none;
  }
}
}

/* /public/css/systems/interactive-medium.css */
@layer systems {
/* ==========================================================================
   interactive-medium.css
   --------------------------------------------------------------------------
   Device-aware modulation for entertainment / interactive routes.
   Imported last in the systems layer so module-added styles (scene-interaction,
   spw-key-events, palette-treat) spend shared tokens without fighting layout.
   ========================================================================== */

:root {
  --spw-medium-touch-min: 2.75rem;
  --spw-medium-lane-pad: 0.55rem;
  --spw-medium-layout-gap-scale: 1;
  --spw-medium-reveal-stagger-step: 72ms;
  --spw-medium-accent-weight: 1;
  --spw-medium-hover-lift: 1px;
  --spw-medium-scene-coupling: 0.42;
  --spw-module-style-modulator: 1;
  --spw-medium-lane-active-boost: 0.55;
  --spw-medium-outline-offset: 3px;
}

/* --------------------------------------------------------------------------
   Device specificity — pointer, hover, viewport tier
   -------------------------------------------------------------------------- */

:where(html[data-spw-pointer-mode="coarse"]) {
  --spw-medium-touch-min: 3.15rem;
  --spw-medium-lane-pad: 0.72rem;
  --spw-medium-hover-lift: 0px;
  --spw-medium-outline-offset: 4px;
  --spw-medium-reveal-stagger-step: 58ms;
}

:where(html[data-spw-hover-mode="touch"]) {
  --spw-medium-hover-lift: 0px;
}

:where(html[data-spw-viewport-tier="compact"], html[data-spw-viewport-tier="narrow"]) {
  --spw-medium-layout-gap-scale: 0.92;
  --spw-medium-touch-min: max(var(--spw-medium-touch-min, 2.75rem), 3rem);
}

:where(html[data-spw-viewport-tier="wide"]) {
  --spw-medium-layout-gap-scale: 1.06;
  --spw-medium-accent-weight: 1.04;
}

/* --------------------------------------------------------------------------
   Interaction posture — entertainment utility tuning
   -------------------------------------------------------------------------- */

:where(html[data-spw-interaction-posture="touch-field"]) {
  --spw-medium-touch-min: 3.35rem;
  --spw-medium-lane-pad: 0.78rem;
  --spw-medium-layout-gap-scale: 0.9;
  --spw-medium-reveal-stagger-step: 52ms;
  --spw-module-style-modulator: 1.12;
}

:where(html[data-spw-interaction-posture="touch-tablet"]) {
  --spw-medium-touch-min: 3.05rem;
  --spw-medium-lane-pad: 0.68rem;
  --spw-module-style-modulator: 1.06;
}

:where(html[data-spw-interaction-posture="pointer-rich"]) {
  --spw-medium-hover-lift: 2px;
  --spw-medium-accent-weight: 1.08;
  --spw-medium-scene-coupling: 0.48;
}

/* --------------------------------------------------------------------------
   Medium register — route / entertainment targeting
   -------------------------------------------------------------------------- */

:where(html[data-spw-medium-register="scene"]) {
  --spw-medium-accent-weight: 1.12;
  --spw-medium-scene-coupling: 0.58;
  --spw-medium-lane-active-boost: 0.68;
  --spw-module-style-modulator: 1.1;
  --spw-variant-selection-weight: max(var(--spw-variant-selection-weight, 0), 0.48);
}

:where(html[data-spw-medium-register="play"]) {
  --spw-medium-accent-weight: 1.08;
  --spw-medium-scene-coupling: 0.52;
  --spw-medium-lane-active-boost: 0.62;
  --spw-module-style-modulator: 1.08;
}

:where(html[data-spw-medium-register="workshop"], html[data-spw-medium-register="lab"]) {
  --spw-medium-accent-weight: 1.04;
  --spw-module-style-modulator: 1.04;
}

:where(html[data-spw-medium-register="reading"]) {
  --spw-medium-accent-weight: 0.96;
  --spw-module-style-modulator: 0.94;
}

:where(html[data-spw-interactive-medium-ready="true"]) {
  --spw-medium-lane-active-boost: calc(0.48 + (var(--spw-medium-intensity, 0.5) * 0.28));
  --spw-module-style-modulator: calc(0.88 + (var(--spw-medium-intensity, 0.5) * 0.24));
}

/* --------------------------------------------------------------------------
   Display variants — packing + density parity on interactive hosts
   -------------------------------------------------------------------------- */

:where(html[data-spw-pack-tier="compact"], html[data-spw-component-density="dense"]) :where(
  .spw-scene-bed[data-spw-scene-interactive],
  .spw-scene-bed[data-spw-scene-posture]
) {
  --spw-medium-lane-pad: max(0.62rem, calc(var(--spw-pack-pad-active, 0.65rem) * 0.92));
  --spw-medium-layout-gap-scale: 0.88;
}

:where(html[data-spw-pack-tier="roomy"], html[data-spw-component-density="roomy"]) :where(
  .spw-scene-bed[data-spw-scene-interactive],
  .spw-scene-bed[data-spw-scene-posture]
) {
  --spw-medium-lane-pad: calc(var(--spw-pack-pad-active, 1.15rem) * 0.72);
  --spw-medium-layout-gap-scale: 1.08;
}

/* --------------------------------------------------------------------------
   Container queries — scene bed layout variants inside route measure
   -------------------------------------------------------------------------- */

:where(.spw-scene-bed[data-spw-scene-interactive], .spw-scene-bed[data-spw-scene-posture]) {
  container-type: inline-size;
  container-name: spw-scene-bed;
}

@supports (container-type: inline-size) {
  @container spw-scene-bed (max-width: 32rem) {
    :where(.spw-scene-bed__layout) {
      gap: calc(0.72rem * var(--spw-medium-layout-gap-scale, 1));
    }

    :where(.spw-scene-bed__stage) {
      grid-template-columns: 1fr;
      min-block-size: calc(var(--spw-medium-touch-min, 2.75rem) * 3.2);
    }

    :where(.spw-scene-bed__lane) {
      min-block-size: var(--spw-medium-touch-min, 2.75rem);
      padding: var(--spw-medium-lane-pad, 0.55rem);
    }
  }

  @container spw-scene-bed (min-width: 32.01rem) {
    :where(.spw-scene-bed__layout:has(.spw-scene-bed__figure)) {
      gap: calc(0.85rem * var(--spw-medium-layout-gap-scale, 1));
    }
  }
}

/* --------------------------------------------------------------------------
   Module style impact — spend tokens on later-loaded interaction systems
   -------------------------------------------------------------------------- */

:where(html[data-spw-medium-register="scene"], html[data-spw-medium-register="play"]) :where(
  .spw-scene-bed[data-spw-scene-interactive]
) {
  --spw-scene-lane-active-strength: var(--spw-medium-lane-active-boost, 0.55);
  --spw-scene-image-coupling: var(--spw-medium-scene-coupling, 0.42);
}

:where(html[data-spw-medium-register="scene"]) :where(
  [data-spw-selection-state="potentiated"],
  [data-spw-selection-state="actualized"]
) {
  outline-offset: calc(var(--spw-medium-outline-offset, 3px) * var(--spw-module-style-modulator, 1));
}

:where(html[data-spw-reveal-phase="revealing"], html[data-spw-reveal-phase="revealed"]) :where(
  [data-spw-scene-state="entered"],
  [data-spw-reveal-frame="open"]
) {
  --spw-reveal-stagger-step: var(--spw-medium-reveal-stagger-step, 72ms);
}
}

/* /public/css/systems/coloring-depth.css */
@layer systems {
/* ==========================================================================
   systems/coloring-depth.css
   --------------------------------------------------------------------------
   Coloring depth: operator-accent routing for copy layers and composition tiers.

   Ladders (see .spw/conventions/coloring-depth.spw)
   - copy-depth     : data-spw-copy-depth → --spw-copy-depth-accent
   - composition    : data-spw-composition-tier → --spw-composition-depth-accent
   - palette-depth  : owned by surfaces/palette-depth.css (material probes)

   Spend rule: copy-depth accents label optional prose layers; they do not replace
   semantic-accent on ordinary reading surfaces.
   ========================================================================== */

:root {
  --spw-copy-depth-accent: var(--active-op-color, var(--component-accent, #008080));
  --spw-copy-depth-line-mix: 18%;
  --spw-copy-depth-bg-mix: 4%;
  --spw-composition-depth-accent: var(--active-op-color, var(--component-accent, #008080));
}

/* --------------------------------------------------------------------------
   Copy-depth accent ladder
   -------------------------------------------------------------------------- */

:where([data-spw-copy-depth="entry"]) {
  --spw-copy-depth-accent: var(--op-frame-color, var(--active-op-color, var(--component-accent)));
  --spw-copy-depth-line-mix: 20%;
  --spw-copy-depth-bg-mix: 5%;
}

:where([data-spw-copy-depth="normal"]) {
  --spw-copy-depth-accent: var(--op-ref-color, var(--active-op-color, var(--component-accent)));
  --spw-copy-depth-line-mix: 22%;
  --spw-copy-depth-bg-mix: 4%;
}

:where([data-spw-copy-depth="rich"]) {
  --spw-copy-depth-accent: var(--op-probe-color, var(--active-op-color, var(--component-accent)));
  --spw-copy-depth-line-mix: 28%;
  --spw-copy-depth-bg-mix: 5%;
}

:where([data-spw-copy-depth="dense"]) {
  --spw-copy-depth-accent: var(--op-stream-color, var(--active-op-color, var(--component-accent)));
  --spw-copy-depth-line-mix: 30%;
  --spw-copy-depth-bg-mix: 6%;
}

:where([data-spw-copy-depth="technical"]) {
  --spw-copy-depth-accent: var(--op-action-color, var(--active-op-color, var(--component-accent)));
  --spw-copy-depth-line-mix: 26%;
  --spw-copy-depth-bg-mix: 5%;
}

:where([data-spw-copy-depth="genre"]) {
  --spw-copy-depth-accent: var(--op-object-color, var(--active-op-color, var(--component-accent)));
  --spw-copy-depth-line-mix: 30%;
  --spw-copy-depth-bg-mix: 7%;
}

:where([data-spw-copy-depth]) {
  --spw-debug-layer-owner: "systems";
  --spw-debug-layer-color: #2a7a6f;
  --spw-copy-depth-line: color-mix(
    in srgb,
    var(--spw-copy-depth-accent) calc(var(--spw-copy-depth-line-mix) * 1),
    var(--line, rgba(14, 18, 20, 0.14))
  );
  --spw-copy-depth-bg: color-mix(
    in srgb,
    var(--component-surface-strong, var(--surface-strong, #fff))
      calc(100% - var(--spw-copy-depth-bg-mix)),
    var(--spw-copy-depth-accent) var(--spw-copy-depth-bg-mix)
  );
  display: none;
  margin-block: 0.75rem;
  padding: 0.72rem 0.85rem;
  border: 1px solid var(--spw-copy-depth-line);
  border-radius: var(--component-radius-loose);
  background: var(--spw-copy-depth-bg);
  color: color-mix(in srgb, var(--ink-soft, rgba(0, 0, 0, 0.62)) 88%, var(--ink, #111) 12%);
  line-height: 1.5;
}

:where([data-spw-copy-depth])::before {
  display: block;
  margin-block-end: 0.32rem;
  color: color-mix(in srgb, var(--spw-copy-depth-accent) 72%, var(--ink, #111) 28%);
  content: attr(data-spw-copy-label);
  font-family: var(--site-mono-font, "JetBrains Mono", monospace);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

:where(
  html[data-spw-semantic-density="minimal"] [data-spw-copy-depth="entry"],
  html[data-spw-semantic-density="normal"] [data-spw-copy-depth="entry"],
  html[data-spw-semantic-density="normal"] [data-spw-copy-depth="normal"],
  html[data-spw-semantic-density="rich"] [data-spw-copy-depth="entry"],
  html[data-spw-semantic-density="rich"] [data-spw-copy-depth="normal"],
  html[data-spw-semantic-density="rich"] [data-spw-copy-depth="rich"],
  html[data-spw-semantic-density="rich"] [data-spw-copy-depth="dense"],
  html[data-spw-runtime-posture="precision"] [data-spw-copy-depth="technical"],
  body[data-spw-page-modes~="inspect"] [data-spw-copy-depth="technical"],
  html[data-spw-runtime-posture="resonant"] [data-spw-copy-depth="genre"],
  html[data-spw-runtime-posture="theatrical"] [data-spw-copy-depth="genre"]
) {
  display: block;
}

:where([data-spw-copy-depth][data-spw-semantic-expression]) {
  position: relative;
}

:where([data-spw-copy-depth][data-spw-semantic-expression])::after {
  content: attr(data-spw-semantic-expression);
  display: inline-flex;
  margin-block-start: 0.55rem;
  padding: 0.16rem 0.48rem;
  border-radius: var(--component-radius-pill, 999px);
  background: color-mix(in srgb, var(--spw-copy-depth-accent) 10%, transparent);
  color: color-mix(in srgb, var(--ink-soft, #555) 78%, var(--spw-copy-depth-accent) 22%);
  font-family: var(--site-mono-font, "JetBrains Mono", monospace);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.04em;
}

/* --------------------------------------------------------------------------
   Composition-tier depth accents (module-visuals only)
   -------------------------------------------------------------------------- */

:where(html[data-spw-module-visuals="on"] [data-spw-composition-tier="page"]) {
  --spw-composition-depth-accent: var(--op-frame-color, var(--active-op-color));
}

:where(html[data-spw-module-visuals="on"] [data-spw-composition-tier="region"]) {
  --spw-composition-depth-accent: var(--op-ref-color, var(--active-op-color));
}

:where(html[data-spw-module-visuals="on"] [data-spw-composition-tier="feature"]) {
  --spw-composition-depth-accent: var(--op-probe-color, var(--active-op-color));
}

:where(html[data-spw-module-visuals="on"] [data-spw-composition-tier="component"]) {
  --spw-composition-depth-accent: var(--op-object-color, var(--active-op-color));
}

:where(html[data-spw-module-visuals="on"] [data-spw-composition-tier="slot"]) {
  --spw-composition-depth-accent: var(--op-stream-color, var(--active-op-color));
}

:where(html[data-spw-module-visuals="on"] [data-spw-composition-tier="module"]) {
  --spw-composition-depth-accent: var(--op-action-color, var(--active-op-color));
}

:where(html[data-spw-module-visuals="on"] [data-spw-composition-tier="chrome"]) {
  --spw-composition-depth-accent: var(--op-meta-color, var(--ink-soft, #555));
}

:where(html[data-spw-module-visuals="on"] [data-spw-composition-tier="runtime"]) {
  --spw-composition-depth-accent: var(--op-probe-color, var(--active-op-color));
}

:where(html[data-spw-module-visuals="on"] [data-spw-composition-tier]) {
  outline: 1px dashed color-mix(in srgb, var(--spw-composition-depth-accent) 28%, transparent);
  outline-offset: 0.12rem;
}
}

/* /public/css/systems/semantic-copy-lens.css */
@layer systems {
/* ==========================================================================
   systems/semantic-copy-lens.css
   --------------------------------------------------------------------------
   Reads as: lens-sensitive copy and kind diversity for freshness and flow.
   Was: ad-hoc copy-depth notes + duplicate accents in semantic-variants.
   Genome: data-spw-copy-lens, data-spw-active-lens-mode, data-spw-kind hook|lens|metric
   Probe: switch a mode-switch lens; toggle semantic density; observe which
         copy layers appear and how hook/lens/metric rhythm shifts.

   Chunk of the semantic surface (with coloring-depth.css) so copy + lens
   stay a readable chapter instead of growing semantic-variants indefinitely.
   ========================================================================== */

/* --------------------------------------------------------------------------
   Lens-sensitive copy
   Space-separated tokens on data-spw-copy-lens, e.g. "surface default" or
   "syntax artifacts". Hidden until density + active lens allow them.
   -------------------------------------------------------------------------- */

:where([data-spw-copy-lens]) {
  display: none;
  margin-block: 0.55rem;
  padding: 0.65rem 0.8rem;
  border: 1px solid color-mix(
    in srgb,
    var(--spw-copy-depth-accent, var(--active-op-color, #008080)) 22%,
    var(--line, rgba(14, 18, 20, 0.14))
  );
  border-radius: var(--component-radius-loose, 8px);
  background: color-mix(
    in srgb,
    var(--surface-strong, #fff) 94%,
    var(--spw-copy-depth-accent, var(--active-op-color, #008080)) 6%
  );
  color: color-mix(in srgb, var(--ink-soft, rgba(0, 0, 0, 0.62)) 88%, var(--ink, #111) 12%);
  line-height: 1.55;
  animation: none;
}

:where([data-spw-copy-lens])::before {
  display: block;
  margin-block-end: 0.28rem;
  color: color-mix(in srgb, var(--spw-copy-depth-accent, var(--active-op-color)) 70%, var(--ink, #111) 30%);
  content: attr(data-spw-copy-label);
  font-family: var(--site-mono-font, "JetBrains Mono", monospace);
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

/* Always-visible default line when no lens is active */
:where(
  html:not([data-spw-active-lens-mode]) [data-spw-copy-lens~="default"],
  html:not([data-spw-active-lens-mode]) [data-spw-copy-lens~="always"],
  [data-spw-copy-lens~="always"]
) {
  display: block;
}

/* Match document active lens (from lens-modes.js) */
:where(html[data-spw-active-lens-mode="surface"] [data-spw-copy-lens~="surface"]),
:where(html[data-spw-active-lens-mode="syntax"] [data-spw-copy-lens~="syntax"]),
:where(html[data-spw-active-lens-mode="artifacts"] [data-spw-copy-lens~="artifacts"]),
:where(html[data-spw-active-lens-mode="website"] [data-spw-copy-lens~="website"]),
:where(html[data-spw-active-lens-mode="systems"] [data-spw-copy-lens~="systems"]),
:where(html[data-spw-active-lens-mode="learning"] [data-spw-copy-lens~="learning"]),
:where(html[data-spw-active-lens-mode="making"] [data-spw-copy-lens~="making"]),
:where(html[data-spw-active-lens-mode="current"] [data-spw-copy-lens~="current"]),
:where(html[data-spw-active-lens-mode="source"] [data-spw-copy-lens~="source"]),
:where(html[data-spw-active-lens-mode="library"] [data-spw-copy-lens~="library"]),
:where(html[data-spw-active-lens-mode="memory"] [data-spw-copy-lens~="memory"]),
:where(html[data-spw-active-lens-mode="operators"] [data-spw-copy-lens~="operators"]),
:where(html[data-spw-active-lens-mode="principles"] [data-spw-copy-lens~="principles"]),
:where(html[data-spw-active-lens-mode="workbench"] [data-spw-copy-lens~="workbench"]),
:where(html[data-spw-active-lens-mode="read"] [data-spw-copy-lens~="read"]),
:where(html[data-spw-active-lens-mode="inspect"] [data-spw-copy-lens~="inspect"]),
:where(html[data-spw-active-lens-mode="reuse"] [data-spw-copy-lens~="reuse"]),
:where(html[data-spw-active-lens-mode="play"] [data-spw-copy-lens~="play"]) {
  display: block;
  animation: spw-lens-copy-in 420ms var(--ease-smooth, ease);
}

/* Host-scoped lens (frame already set data-spw-lens-mode) */
:where([data-spw-lens-mode="surface"] [data-spw-copy-lens~="surface"]),
:where([data-spw-lens-mode="syntax"] [data-spw-copy-lens~="syntax"]),
:where([data-spw-lens-mode="artifacts"] [data-spw-copy-lens~="artifacts"]),
:where([data-spw-lens-mode="website"] [data-spw-copy-lens~="website"]),
:where([data-spw-lens-mode="read"] [data-spw-copy-lens~="read"]),
:where([data-spw-lens-mode="inspect"] [data-spw-copy-lens~="inspect"]),
:where([data-spw-lens-mode="reuse"] [data-spw-copy-lens~="reuse"]),
:where([data-spw-lens-mode="play"] [data-spw-copy-lens~="play"]) {
  display: block;
  animation: spw-lens-copy-in 420ms var(--ease-smooth, ease);
}

@keyframes spw-lens-copy-in {
  from {
    opacity: 0;
    transform: translateY(0.25rem);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  :where([data-spw-copy-lens]) {
    animation: none !important;
  }
}

/* Freshness: when a lens is active, slightly lift matching copy accent */
:where(html[data-spw-active-lens-mode] [data-spw-copy-lens]) {
  --spw-copy-depth-line-mix: calc(var(--spw-copy-depth-line-mix, 22%) + 4%);
  --spw-copy-depth-bg-mix: calc(var(--spw-copy-depth-bg-mix, 4%) + 2%);
}

/* Flow: stack consecutive lens/copy layers with a quieter gap */
:where([data-spw-copy-lens] + [data-spw-copy-lens]),
:where([data-spw-copy-depth] + [data-spw-copy-lens]),
:where([data-spw-copy-lens] + [data-spw-copy-depth]) {
  margin-block-start: 0.4rem;
}

/* --------------------------------------------------------------------------
   Component kind diversity — distinct cadence for underused kinds
   -------------------------------------------------------------------------- */

:where(main [data-spw-kind="hook"], main [data-spw-component-kind="hook"]) {
  --spw-kind-rhythm: 1.12;
  --spw-variant-accent: var(--op-action-color, var(--active-op-color, #006666));
  margin-block: calc(0.85rem * var(--spw-kind-rhythm, 1));
}

:where(main [data-spw-kind="lens"], main [data-spw-component-kind="lens"]) {
  --spw-kind-rhythm: 0.92;
  --spw-variant-accent: var(--op-probe-color, var(--active-op-color, #7a4fb5));
  padding-block: 0.35rem;
  border-inline-start: 2px solid color-mix(in srgb, var(--spw-variant-accent) 42%, transparent);
  padding-inline-start: 0.75rem;
}

:where(main [data-spw-kind="metric"], main [data-spw-component-kind="metric"]) {
  --spw-kind-rhythm: 0.88;
  --spw-variant-accent: var(--op-stream-color, var(--active-op-color, #2a7a6f));
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.01em;
}

:where(main [data-spw-kind="metric"] .spw-metric-grid),
:where(.spw-metric-grid) {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 8.5rem), 1fr));
  gap: 0.5rem;
  margin-block: 0.55rem;
}

:where(.spw-metric-grid > *) {
  margin: 0;
  padding: 0.55rem 0.65rem;
  border: 1px solid color-mix(in srgb, var(--op-stream-color, #2a7a6f) 22%, var(--line, rgba(14, 18, 20, 0.14)));
  border-radius: var(--shape-component, 6px);
  background: color-mix(in srgb, var(--surface-strong, #fff) 94%, var(--op-stream-color, #2a7a6f) 6%);
}

:where(.spw-metric-grid strong) {
  display: block;
  font-family: var(--site-mono-font, monospace);
  font-size: 0.72rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--op-stream-color, #2a7a6f) 70%, var(--ink, #111));
}

/* Collection fresh pulse when a new kind is discovered */
:where(html[data-spw-collection-fresh] main [data-spw-kind]) {
  transition: box-shadow 480ms var(--ease-smooth, ease);
}

:where(html[data-spw-collection-fresh~="hook"] main [data-spw-kind="hook"]),
:where(html[data-spw-collection-fresh~="lens"] main [data-spw-kind="lens"]),
:where(html[data-spw-collection-fresh~="metric"] main [data-spw-kind="metric"]) {
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--spw-variant-accent, var(--active-op-color)) 28%, transparent),
    0 0 14px color-mix(in srgb, var(--spw-variant-accent, var(--active-op-color)) 12%, transparent);
}
}

/* /public/css/systems/surfaces/reading-layout.css */
@layer systems {
/* ==========================================================================
   surfaces/reading-layout.css
   --------------------------------------------------------------------------
   Reading posture and vertical flow — newspaper-dense desktop columns,
   diverse mobile section rhythm, and attention-architecture coupling.
   Driven by html[data-spw-layout-tuner] and html[data-spw-layout-flow].
   ========================================================================== */

/* Newspaper posture tokens (desktop-first) */
html[data-spw-layout-tuner="newspaper"] {
  --site-line-height: 1.52;
  --site-line-height-tight: 1.28;
  --measure-reading: var(--spw-layout-measure, 54ch);
  --spw-flow-space: 0.72rem;
  --page-stack-gap: clamp(0.75rem, 1.4vw, 1rem);
  --page-section-gap: clamp(0.85rem, 1.5vw, 1.2rem);
  --surface-gap: clamp(0.62rem, 1.1vw, 0.82rem);
  --text-rhythm-drag: 0.34;
  --text-flow-variable: 1.08;
  --spw-grid-min-base: 11.25rem;
  --spw-grid-min-mid: 10.75rem;
  --spw-grid-gap-base: 0.56rem;
  --spw-grid-gap-mid: 0.52rem;
  --semantic-metadata-font-size: 0.52rem;
}

html[data-spw-layout-tuner="newspaper"] main > article {
  gap: var(--page-section-gap);
}

html[data-spw-layout-tuner="newspaper"] :where(p, li, .frame-note, .frame-copy) {
  font-size: clamp(0.94rem, 0.9rem + 0.08vw, 1.02rem);
  line-height: var(--site-line-height, 1.52);
  hyphens: auto;
}

html[data-spw-layout-tuner="newspaper"] :where(h2) {
  font-size: clamp(1.18rem, 1.05rem + 0.35vw, 1.42rem);
  margin-block-end: 0.35rem;
}

html[data-spw-layout-tuner="newspaper"] :where(h3) {
  font-size: clamp(1.02rem, 0.96rem + 0.2vw, 1.16rem);
}

@media (min-width: 64rem) {
  html[data-spw-layout-tuner="newspaper"] :where(.frame-body, .frame-copy, [data-spw-slot="body"]) {
    column-count: 2;
    column-gap: clamp(1rem, 2vw, 1.45rem);
    column-rule: 1px solid color-mix(in srgb, var(--paper-rule, rgba(14, 18, 20, 0.12)) 88%, transparent);
    column-fill: balance;
  }

  html[data-spw-layout-tuner="newspaper"] :where(.frame-body, .frame-copy) > :is(h2, h3, figure, .frame-grid, .site-frame, pre, blockquote) {
    break-inside: avoid;
    column-span: all;
  }

  html[data-spw-layout-tuner="newspaper"] :where(.frame-grid--dense, .frame-grid[data-spw-density="dense"]) {
    grid-template-columns: repeat(auto-fill, minmax(var(--spw-layout-column-min, 11.25rem), 1fr));
    gap: 0.52rem;
  }

  html[data-spw-layout-tuner="newspaper"] :where(.frame-card, .site-frame) {
    --component-pad: 0.68rem;
    --component-gap-tight: 0.34rem;
  }
}

/* Mobile vertical ribbon — alternating section rhythm */
html[data-spw-layout-flow="vertical-ribbon"] main > article {
  gap: clamp(0.9rem, 3.2vw, 1.35rem);
}

@media (max-width: 48rem) {
  html[data-spw-layout-flow="vertical-ribbon"] main > article > :where(.site-frame, section.site-frame) {
    --spw-mobile-rhythm: stack;
  }

  html[data-spw-layout-flow="vertical-ribbon"] main > article > :where(.site-frame, section.site-frame):nth-child(3n + 1) {
    --spw-mobile-rhythm: full-bleed;
    margin-inline: calc(var(--page-gutter-inline, 1rem) * -0.42);
    border-radius: 0;
    border-inline: none;
  }

  html[data-spw-layout-flow="vertical-ribbon"] main > article > :where(.site-frame, section.site-frame):nth-child(3n + 2) {
    --spw-mobile-rhythm: inset;
  }

  html[data-spw-layout-flow="vertical-ribbon"] main > article > :where(.site-frame, section.site-frame):nth-child(3n) {
    --spw-mobile-rhythm: ribbon;
    padding-block: 0.35rem;
    border: none;
    background: transparent;
    box-shadow: none;
  }

  html[data-spw-layout-flow="vertical-ribbon"] main > article > :where(.site-frame, section.site-frame):nth-child(3n)::before {
    opacity: 0.28;
  }

  html[data-spw-layout-flow="vertical-ribbon"] :where(.frame-grid, .frame-grid--dense) {
    grid-template-columns: 1fr;
    gap: 0.78rem;
  }

  html[data-spw-layout-flow="vertical-ribbon"] :where(.frame-card--illustrated .frame-card-media) {
    max-block-size: 10.5rem;
  }
}

/* Attention architecture: active section emphasis */
html[data-spw-page-section-phase="settled"] :where(
  .site-frame[data-spw-section-state="active"],
  section[data-spw-section-state="active"]
) {
  border-color: color-mix(in srgb, var(--active-op-color) 22%, var(--line, transparent));
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--active-op-color) 10%, transparent),
    var(--component-shadow-quiet, var(--card-shadow, none));
}

html[data-spw-page-section-phase="traveling"] :where(
  .site-frame[data-spw-section-state="active"],
  section[data-spw-section-state="active"]
) {
  box-shadow:
    inset 3px 0 0 color-mix(in srgb, var(--active-op-color) 42%, transparent),
    var(--card-shadow, none);
  transition: box-shadow 280ms var(--ease-settle, ease);
}

html[data-spw-reading-groove="on"][data-spw-layout-flow="vertical-ribbon"] :where(
  [data-spw-reading-beat-role="heading"][data-spw-reading-beat="lead"]
) {
  letter-spacing: -0.018em;
  padding-block-start: 0.12rem;
}

/* Section handle alignment with vertical flow */
@media (max-width: 48rem) {
  html[data-spw-layout-flow="vertical-ribbon"] :where(.spw-section-handle-shell) {
    inset-inline: max(0.45rem, env(safe-area-inset-left)) max(0.45rem, env(safe-area-inset-right));
    max-inline-size: calc(100vw - 0.9rem - env(safe-area-inset-left) - env(safe-area-inset-right));
  }
}

@media (prefers-reduced-motion: reduce) {
  html[data-spw-page-section-phase="traveling"] :where(
    .site-frame[data-spw-section-state="active"],
    section[data-spw-section-state="active"]
  ) {
    transition: none;
  }
}
}

/* /public/css/systems/surfaces/philosophy.css */
@layer systems {
/* ==========================================================================
   surfaces/philosophy.css
   --------------------------------------------------------------------------
   Intent lattices, context edges, and semantic contracts.
   ========================================================================== */

:where(body[data-spw-surface="software"]) {
  --spw-philosophy-panel:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--surface-strong, rgba(255, 255, 255, 0.92)) 94%, transparent),
      color-mix(in srgb, var(--surface-panel, rgba(244, 241, 236, 0.96)) 94%, transparent)
    );
  --spw-philosophy-paper:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--surface-strong, rgba(255, 255, 255, 0.96)) 96%, transparent),
      color-mix(in srgb, var(--surface-panel-strong, rgba(246, 244, 240, 0.96)) 96%, transparent)
    );
  --spw-philosophy-line:
    color-mix(in srgb, var(--active-op-color, #008080) 20%, var(--spw-shell-line));
}

:where(.intent-lattice, .context-edges, .semantic-contract-grid) {
  display: grid;
  gap: var(--spw-shell-panel-gap);
  margin-block: var(--space-sm, 0.8rem) var(--space-md, 1rem);
}

:where(.intent-lattice, .semantic-contract-grid) {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr));
}

:where(.semantic-contract-grid) {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 13rem), 1fr));
}

:where(.intent-cluster, .context-edge-card, .semantic-contract-card) {
  display: grid;
  gap: 0.72rem;
  min-width: 0;
  padding: clamp(0.95rem, 1.7vw, 1.15rem);
  border: 1px solid var(--spw-philosophy-line, var(--spw-shell-line));
  border-radius: calc(var(--shape-surface, 10px) - 1px);
  box-shadow: var(--card-highlight), var(--card-shadow);
}

:where(.intent-cluster, .semantic-contract-card) {
  background: var(--spw-philosophy-panel, var(--spw-shell-card-bg-strong));
}

:where(.intent-cluster) {
  --intent-accent: var(--active-op-color, #008080);
  border-color: color-mix(in srgb, var(--intent-accent) 22%, var(--spw-philosophy-line, var(--spw-shell-line)));
}

:where(.intent-cluster[data-spw-intent="orient"])  { --intent-accent: var(--op-frame-color, #178282); }
:where(.intent-cluster[data-spw-intent="inspect"]) { --intent-accent: var(--op-probe-color, #4a2180); }
:where(.intent-cluster[data-spw-intent="commit"])  { --intent-accent: var(--op-action-color, #0c5f5f); }
:where(.intent-cluster[data-spw-intent="project"]) { --intent-accent: var(--op-surface-color, #178282); }

:where(.intent-cluster-kicker) {
  margin: 0;
  color: color-mix(in srgb, var(--intent-accent) 70%, var(--ink-soft));
  font-size: var(--text-size-xs, 0.76rem);
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

:where(.intent-cluster h3, .context-edge-card h3) {
  margin: 0;
  font-size: clamp(1rem, 1.1rem + 0.22vw, 1.18rem);
  text-wrap: balance;
}

:where(.intent-cluster ul, .context-edge-list) {
  display: grid;
  gap: 0.75rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

:where(.intent-cluster li > a, .context-edge-list li > a) {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.8rem;
  min-width: 0;
  color: inherit;
  text-decoration: none;
}

:where(.intent-cluster li > a:is(:hover, :focus-visible),
       .context-edge-list li > a:is(:hover, :focus-visible)) {
  text-decoration: underline;
}

:where(.intent-token, .semantic-contract-token) {
  flex: 0 0 auto;
  padding: 0.12rem 0.42rem;
  border: 1px solid color-mix(in srgb, currentColor 16%, transparent);
  border-radius: 999px;
  color: color-mix(in srgb, currentColor 74%, var(--ink-soft));
  font-family: var(--site-mono-font, "JetBrains Mono", monospace);
  font-size: 0.72rem;
  letter-spacing: 0.08em;
  white-space: nowrap;
}

:where(.intent-link-note, .context-edge-note) {
  display: block;
  margin-top: 0.24rem;
  color: var(--ink-soft);
  font-size: var(--text-size-sm, 0.9rem);
  line-height: 1.5;
}

/* Context Edges */
:where(.context-edges) {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 16rem), 1fr));
  margin-top: var(--space-md, 1rem);
}

:where(.context-edge-card) {
  --edge-accent: var(--active-op-color, #008080);
  border-color: color-mix(in srgb, var(--edge-accent) 24%, var(--spw-philosophy-line, var(--spw-shell-line)));
  background: var(--spw-philosophy-paper, var(--spw-shell-card-bg));
}

:where(.context-edge-card[data-spw-edge="nearby"])     { --edge-accent: var(--op-ref-color, #1d57a3); }
:where(.context-edge-card[data-spw-edge="subsequent"]) { --edge-accent: var(--op-probe-color, #4a2180); }
:where(.context-edge-card[data-spw-edge="projected"])  { --edge-accent: var(--op-surface-color, #178282); }

/* Semantic Contracts */
:where(.semantic-contract-card) {
  border-color: color-mix(in srgb, var(--spw-philosophy-line, var(--spw-shell-line-strong)) 70%, transparent);
}

:where(.semantic-contract-token) {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  width: fit-content;
  max-width: 100%;
  padding: 0.22rem 0.55rem;
  background: color-mix(in srgb, var(--active-op-color, #008080) 6%, var(--surface-strong, rgba(255, 255, 255, 0.72)));
  color: color-mix(in srgb, var(--active-op-color, #008080) 76%, var(--ink) 24%);
  font-size: 0.76rem;
}

:where(.semantic-contract-card strong) {
  color: var(--ink);
  font-size: 1rem;
}

:where(.semantic-contract-card p) {
  margin: 0;
  color: var(--ink-soft);
}
}

/* /public/css/handles/cognitive-handles.css */
@layer handles {
/* ==========================================================================
   cognitive-handles.css
   --------------------------------------------------------------------------
   Purpose:
   - Semantic affordances for depth, phase, relation, and foldable layers.
   - Handles should read as paper creases and Spw braces, not decoration.
   - Tied directly to the operator palette and precision motion grammar.
   ========================================================================== */

/* ==========================================================================
   1. Handle Tokens & Matrix Mapping
   ========================================================================== */

:root {
    /* Dimensional increments */
    --depth-0: 0px;
    --depth-1: 4px;
    --depth-2: 8px;
    --depth-3: 12px;
    --depth-4: 16px;

    /* Semantic mappings to the Operator matrix */
    --handle-entry:    var(--op-frame-color,  #008080);
    --handle-concept:  var(--op-meta-color,   #324a85);
    --handle-instance: var(--op-object-color, #a67c00);
    --handle-relation: var(--op-merge-color,  #277a87);
    --handle-phase:    var(--op-stream-color, #208259);

    /* Phase specific mappings */
    --phase-initiation:     var(--op-action-color, #005959);
    --phase-resistance:     var(--op-pragma-color, #883a3a);
    --phase-transformation: var(--op-merge-color,  #277a87);
    --phase-expression:     var(--op-stream-color, #208259);
    --phase-return:         var(--op-baseline-color, #594d3f);

    /* Material properties */
    --handle-line:        var(--line, rgba(14, 18, 20, 0.14));
    --handle-line-active: var(--active-op-color, #008080);

    /* Motion alignment */
    --handle-duration: var(--duration-fast, 140ms);
    --handle-ease:     var(--ease-mechanical, ease);
}

/* ==========================================================================
   2. Base State & Anchors
   ========================================================================== */

:where(
    [data-cognitive-handle],
    [data-handle-corner],
    [data-dimension],
    [data-nested-container],
    [data-nested-bracket],
    [data-abstraction-level],
    [data-relation-pair],
    [data-phase-dimension],
    [data-scale-handle],
    [data-cognitive-anchor],
    [data-dimensional-link],
    [data-foldable]
) {
    /* Debug / inspection */
    --spw-debug-layer-owner: "handles";
    --spw-debug-layer-color: #1d57a3;

    position: relative;
}

:where(
    [data-cognitive-handle],
    [data-scale-handle],
    [data-foldable],
    [data-cognitive-anchor]
) {
    cursor: pointer;
}

/* Universal Focus */
:where(
    [data-cognitive-handle]:focus-visible,
    [data-scale-handle]:focus-visible,
    [data-foldable]:focus-visible,
    [data-cognitive-anchor]:focus-visible,
    [data-dimensional-link]:focus-visible
) {
    outline: 2px solid var(--handle-line-active);
    outline-offset: 2px;
    border-radius: 2px;
}

/* ==========================================================================
   3. Primary Handle: Left Crease
   ========================================================================== */

:where([data-cognitive-handle]) {
    transition:
        border-color var(--handle-duration) var(--handle-ease),
        background-color var(--handle-duration) var(--handle-ease);
}

:where([data-cognitive-handle])::before {
    content: '';
    position: absolute;
    top: 0;
    bottom: 0;
    left: 0;
    width: 2px;
    border-left: 2px solid var(--handle-line);
    opacity: 0.58;
    pointer-events: none;
    transition:
        border-color var(--handle-duration) var(--handle-ease),
        opacity var(--handle-duration) var(--handle-ease),
        width var(--handle-duration) var(--handle-ease);
}

:where([data-cognitive-handle]:hover::before, [data-cognitive-handle]:focus-within::before) {
    width: 5px;
    border-color: var(--handle-line-active);
    opacity: 0.92;
}

:where([data-cognitive-handle][data-depth="0"])::before { height: 22%; }
:where([data-cognitive-handle][data-depth="1"])::before { height: 42%; }
:where([data-cognitive-handle][data-depth="2"])::before { height: 62%; }
:where([data-cognitive-handle][data-depth="3"])::before { height: 82%; }
:where([data-cognitive-handle][data-depth="4"])::before { height: 100%; }

/* ==========================================================================
   4. Corner Braces
   ========================================================================== */

:where([data-handle-corner])::after {
    content: '';
    position: absolute;
    width: 9px;
    height: 9px;
    border: 2px solid transparent;
    opacity: 0;
    pointer-events: none;
    transition:
        opacity var(--handle-duration) var(--handle-ease),
        border-color var(--handle-duration) var(--handle-ease);
}

:where([data-handle-corner="tl"])::after {
    top: 0;
    left: 0;
    border-top-color: var(--handle-entry);
    border-left-color: var(--handle-entry);
}

:where([data-handle-corner="tr"])::after {
    top: 0;
    right: 0;
    border-top-color: var(--handle-concept);
    border-right-color: var(--handle-concept);
}

:where([data-handle-corner="bl"])::after {
    bottom: 0;
    left: 0;
    border-bottom-color: var(--handle-instance);
    border-left-color: var(--handle-instance);
}

:where([data-handle-corner="br"])::after {
    right: 0;
    bottom: 0;
    border-right-color: var(--handle-relation);
    border-bottom-color: var(--handle-relation);
}

:where([data-handle-corner]:hover::after, [data-handle-corner]:focus-within::after) {
    opacity: 0.82;
}

/* ==========================================================================
   5. Dimensional Creases & Nesting
   ========================================================================== */

:where([data-dimension])::before {
    content: '';
    position: absolute;
    top: 0;
    bottom: 0;
    left: 0;
    width: var(--depth-indicator-width, 2px);
    border-left: var(--depth-indicator-width, 2px) double var(--handle-line);
    opacity: 0;
    pointer-events: none;
    transition:
        border-color var(--handle-duration) var(--handle-ease),
        opacity var(--handle-duration) var(--handle-ease);
}

:where([data-dimension]:hover::before, [data-dimension]:focus-within::before) {
    border-color: var(--handle-line-active);
    opacity: 1;
}

:where([data-dimension="0"])::before { --depth-indicator-width: 1px; }
:where([data-dimension="1"])::before { --depth-indicator-width: 2px; }
:where([data-dimension="2"])::before { --depth-indicator-width: 3px; }
:where([data-dimension="3"])::before { --depth-indicator-width: 4px; }

:where([data-nested-container]) {
    padding-left: calc(var(--nesting-level, 0) * 14px);
    border-left: 1px solid transparent;
    transition:
        border-color var(--handle-duration) var(--handle-ease),
        padding-left var(--handle-duration) var(--handle-ease);
}

:where([data-nested-container][data-nesting-level="1"]) { border-left-color: color-mix(in srgb, var(--active-op-color, #008080) 22%, transparent); }
:where([data-nested-container][data-nesting-level="2"]) { border-left-color: color-mix(in srgb, var(--active-op-color, #008080) 30%, transparent); }
:where([data-nested-container][data-nesting-level="3"]) { border-left-color: color-mix(in srgb, var(--active-op-color, #008080) 38%, transparent); }

:where([data-nested-container]:hover, [data-nested-container]:focus-within) {
    border-left-color: var(--handle-line-active);
}

:where([data-nested-bracket]) {
    display: inline-block;
}

:where([data-nested-bracket])::before,
:where([data-nested-bracket])::after {
    position: absolute;
    color: var(--handle-concept);
    font-weight: 700;
    opacity: 0;
    transition: opacity var(--handle-duration) var(--handle-ease);
}

:where([data-nested-bracket])::before { content: '{'; left: -1em; }
:where([data-nested-bracket])::after  { content: '}'; right: -1em; }

:where([data-nested-bracket]:hover::before, [data-nested-bracket]:hover::after,
       [data-nested-bracket]:focus-within::before, [data-nested-bracket]:focus-within::after) {
    opacity: 0.66;
}

/* ==========================================================================
   6. Abstraction Labels
   ========================================================================== */

:where([data-abstraction-level])::after {
    content: attr(data-abstraction-label);
    position: absolute;
    top: -1.5em;
    right: 0;
    color: var(--ink-soft, rgba(14, 18, 20, 0.68));
    font-size: var(--text-size-xs, 0.75rem);
    font-weight: 600;
    opacity: 0;
    text-transform: uppercase;
    white-space: nowrap;
    transition: opacity var(--handle-duration) var(--handle-ease);
}

:where([data-abstraction-level]:hover::after, [data-abstraction-level]:focus-within::after) {
    opacity: 1;
}

:where([data-abstraction-level="entry"])::after    { color: var(--handle-entry); }
:where([data-abstraction-level="concept"])::after  { color: var(--handle-concept); }
:where([data-abstraction-level="instance"])::after { color: var(--handle-instance); }
:where([data-abstraction-level="relation"])::after { color: var(--handle-relation); }

/* ==========================================================================
   7. Relation & Phase
   ========================================================================== */

:where([data-relation-pair][data-paired="true"]) {
    border-radius: var(--shape-component, 6px);
    background: var(--active-op-bg-soft, rgba(0, 128, 128, 0.05));
    transition: outline-color var(--handle-duration) var(--handle-ease);
}

:where([data-relation-pair][data-paired="true"]:hover, [data-relation-pair][data-paired="true"]:focus-within) {
    outline: 1px solid var(--handle-line-active);
    outline-offset: 2px;
}

:where([data-relation-pair])::before {
    content: '&';
    position: absolute;
    top: 50%;
    left: -1.1em;
    color: var(--handle-relation);
    font-weight: 700;
    opacity: 0;
    transform: translateY(-50%);
    transition: opacity var(--handle-duration) var(--handle-ease);
}

:where([data-relation-pair]:hover::before, [data-relation-pair]:focus-within::before) {
    opacity: 0.72;
}

:where([data-relation-line]) {
    position: absolute;
    opacity: 0;
    pointer-events: none;
    stroke: var(--handle-relation);
    stroke-width: var(--line-thick, 2px);
    transition: opacity var(--handle-duration) var(--handle-ease);
}

:where([data-relation-pair]:hover ~ [data-relation-line], [data-relation-pair]:focus-within ~ [data-relation-line]) {
    opacity: 0.42;
}

:where([data-phase-dimension])::before {
    content: attr(data-phase);
    position: absolute;
    top: 50%;
    right: -1rem;
    color: var(--handle-phase);
    font-family: var(--site-mono-font, 'JetBrains Mono', monospace);
    font-size: var(--text-size-xs, 0.72rem);
    opacity: 0;
    transform: translate(100%, -50%);
    white-space: nowrap;
    transition: opacity var(--handle-duration) var(--handle-ease);
}

:where([data-phase-dimension]:hover::before, [data-phase-dimension]:focus-within::before) {
    opacity: 0.8;
}

:where([data-phase="initiation"])::before     { color: var(--phase-initiation); }
:where([data-phase="resistance"])::before     { color: var(--phase-resistance); }
:where([data-phase="transformation"])::before { color: var(--phase-transformation); }
:where([data-phase="expression"])::before     { color: var(--phase-expression); }
:where([data-phase="return"])::before         { color: var(--phase-return); }

/* ==========================================================================
   8. Scale, Anchors, Portals, Folds
   ========================================================================== */

:where([data-scale-handle])::after {
    content: '#';
    position: absolute;
    top: 50%;
    right: -1em;
    color: var(--handle-line-active);
    font-weight: 700;
    opacity: 0;
    transform: translateY(-50%);
    transition: opacity var(--handle-duration) var(--handle-ease);
}

:where([data-scale-handle]:hover::after, [data-scale-handle]:focus-visible::after) {
    opacity: 0.75;
}

:where([data-dimensional-breadcrumb]) {
    display: flex;
    gap: var(--space-xs, 0.5rem);
    align-items: center;
    margin-bottom: var(--space-md, 1rem);
    color: var(--ink-soft, rgba(14, 18, 20, 0.68));
    font-size: var(--text-size-sm, 0.85rem);
}

:where([data-dimensional-breadcrumb] > span) {
    position: relative;
    padding: 0.25rem 0.5rem;
    border: 1px solid var(--handle-line);
    border-radius: var(--shape-component, 6px);
    background: var(--active-op-bg-soft, rgba(0, 128, 128, 0.06));
    transition:
        border-color var(--handle-duration) var(--handle-ease),
        color var(--handle-duration) var(--handle-ease);
}

:where([data-dimensional-breadcrumb] > span:hover, [data-dimensional-breadcrumb] > span:focus-visible) {
    border-color: var(--handle-line-active);
    color: var(--ink);
}

:where([data-cognitive-anchor])::before {
    content: '#{';
    position: absolute;
    left: -1.55em;
    color: var(--handle-relation);
    font-weight: 700;
    opacity: 0;
    transition: opacity var(--handle-duration) var(--handle-ease);
}

:where([data-cognitive-anchor])::after {
    content: '}';
    color: var(--handle-relation);
    font-weight: 700;
    opacity: 0;
    transition: opacity var(--handle-duration) var(--handle-ease);
}

:where([data-cognitive-anchor]:hover::before, [data-cognitive-anchor]:hover::after,
       [data-cognitive-anchor]:focus-visible::before, [data-cognitive-anchor]:focus-visible::after) {
    opacity: 0.8;
}

:where([data-dimensional-link])::after {
    content: ' ~{}';
    color: var(--handle-concept);
    font-weight: 700;
    opacity: 0;
    transition: opacity var(--handle-duration) var(--handle-ease);
}

:where([data-dimensional-link]:hover::after, [data-dimensional-link]:focus-visible::after) {
    opacity: 0.72;
}

:where([data-foldable])::before {
    content: '{';
    position: absolute;
    top: 50%;
    left: -0.75rem;
    color: var(--handle-line-active);
    font-weight: 700;
    opacity: 0;
    transform: translateY(-50%);
    transition: opacity var(--handle-duration) var(--handle-ease);
}

:where([data-foldable][data-folded="true"])::before {
    content: '}';
}

:where([data-foldable]:hover::before, [data-foldable]:focus-visible::before) {
    opacity: 0.85;
}

/* ==========================================================================
   9. Responsive & Accessibility Adjustments
   ========================================================================== */

@media (max-width: 768px) {
    :where([data-cognitive-handle])::before {
        opacity: 0.72;
        width: 4px;
    }

    :where([data-handle-corner])::after {
        opacity: 0.48;
    }

    :where([data-dimensional-breadcrumb]) {
        gap: var(--space-2xs, 0.25rem);
        font-size: var(--text-size-xs, 0.75rem);
    }

    :where([data-dimensional-breadcrumb] > span) {
        padding: 0.2rem 0.4rem;
    }
}

@media (prefers-reduced-motion: reduce) {
    :where(
        [data-cognitive-handle],
        [data-cognitive-handle]::before,
        [data-handle-corner]::after,
        [data-nested-container],
        [data-nested-bracket]::before,
        [data-nested-bracket]::after,
        [data-abstraction-level]::after,
        [data-relation-pair],
        [data-relation-pair]::before,
        [data-relation-line],
        [data-phase-dimension]::before,
        [data-scale-handle]::after,
        [data-cognitive-anchor]::before,
        [data-cognitive-anchor]::after,
        [data-dimensional-link]::after,
        [data-foldable]::before
    ) {
        transition: none !important;
        animation: none !important;
    }
}
}

