  --handle-shadow-focus:
    0 0 0 1px color-mix(in srgb, var(--active-op-color, var(--teal)) 14%, transparent),
    0 3px 10px rgba(0, 0, 0, 0.025);
  --handle-shadow-latched:
    inset 0 1px 0 rgba(255, 255, 255, 0.34),
