/* ==========================================================================
   4. Frame sigils
   --------------------------------------------------------------------------
   Frame sigils are anchor handles. Hidden by default except in room-sign seams.
   ========================================================================== */

.frame-sigil {
  position: absolute;
  top: 0;
  left: 0;
  display: block;
  width: 0;
  overflow: hidden;
  font-size: 0;
}

.frame-topline .frame-sigil,
.frame-heading .frame-sigil {
  position: static;
  display: inline-flex;
  inline-size: fit-content;
  width: auto;
  max-width: 100%;
  overflow: visible;
  min-height: 1.62rem;
  padding: 0.12rem 0.54rem 0.12rem 0.62rem;
  border: 1px solid color-mix(in srgb, currentColor 16%, transparent);
  border-inline-start-width: 1.5px;
  border-radius: var(--shape-control, 0.78rem);
  background: color-mix(in srgb, var(--surface-strong, #fff) 94%, transparent);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.24);
  color: color-mix(in srgb, var(--ink-soft) 88%, var(--active-op-color, var(--teal)) 12%);
  font-size: var(--text-size-label, 0.76rem);
  line-height: var(--spw-frame-sigil-line-height, 1);
  opacity: 0.82;
  justify-content: flex-start;
  text-align: left;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  transition:
    opacity var(--handle-duration-fast) var(--handle-ease),
    color var(--handle-duration-fast) var(--handle-ease),
    border-color var(--handle-duration-fast) var(--handle-ease);
}

:where(.frame-topline .frame-sigil, .frame-heading .frame-sigil):hover,
:where(.frame-topline .frame-sigil, .frame-heading .frame-sigil):focus-visible {
  opacity: 1;
  color: var(--active-op-color, var(--teal));
  border-color: color-mix(in srgb, var(--active-op-color, var(--teal)) 36%, transparent);
  background: color-mix(in srgb, var(--surface-strong, #fff) 90%, var(--active-op-color, var(--teal)) 10%);
  outline: none;
}

:where(.frame-topline .frame-sigil + .spec-strip, .frame-heading .frame-sigil + .spw-component-meta) {
  align-self: flex-start;
  margin-inline-start: 0.22rem;
}

:where(.frame-topline > [data-spw-slot="meta"], .frame-heading > [data-spw-slot="meta"]) {
  order: 0;
  margin-inline-start: auto;
}

/* Positional grammar seams (prefix / infix / postfix).
   Prefix leads attention forward into the operand; postfix reflects back on
   what was just read. Buttons and copy share the seams: the data-spw-op
   bundle carries position for atoms, data-spw-sigil-position for sigils. */
:where([data-spw-sigil-position="prefix"], [data-spw-op~="position:prefix"]) {
  border-inline-start-width: 2px;
  background-image: linear-gradient(
    to right,
    color-mix(in srgb, var(--active-op-color, var(--teal)) 9%, transparent),
    transparent 38%
  );
}

:where([data-spw-sigil-position="infix"]) {
  border-style: dashed;
  border-color: color-mix(in srgb, currentColor 22%, transparent);
}

:where([data-spw-sigil-position="postfix"], [data-spw-op~="position:postfix"]) {
  border-inline-end-width: 2px;
  background-image: linear-gradient(
    to left,
    color-mix(in srgb, var(--active-op-color, var(--teal)) 9%, transparent),
    transparent 38%
  );
}

/* ── Operational disposition physics ──────────────────────────────────────
   Containers determine what a sigil's payload does (spatial physics):
   charge      - the vessel accumulates; sigils pull inward   (cauldron host)
   discharge   - composed state releases outward              (cast, reset)
   reference   - a name is minted that points at state        (checkpoint)
   dereference - a name resolves back into substance          (restore, decompose)
   Paint-only by the impact gradient; no layout, no timing changes. */
:where([data-spw-op-disposition="charge"]) :where(.frame-sigil, .operator-chip, .cauldron-ingredient) {
  box-shadow: inset 0 0 0.55em color-mix(in srgb, var(--active-op-color, var(--teal)) 12%, transparent);
}

:where(.operator-chip[data-spw-op-disposition="discharge"], [data-spw-op-disposition="discharge"] .frame-sigil) {
  box-shadow: 0 0 0.6em color-mix(in srgb, var(--active-op-color, var(--teal)) 14%, transparent);
}

:where(.operator-chip[data-spw-op-disposition="reference"]) {
  text-decoration-line: underline;
  text-decoration-style: dotted;
  text-decoration-color: color-mix(in srgb, var(--active-op-color, var(--teal)) 44%, transparent);
  text-underline-offset: var(--handle-underline-offset, 0.16em);
}

:where(.operator-chip[data-spw-op-disposition="dereference"]) {
  text-decoration-line: underline;
  text-decoration-style: solid;
  text-decoration-thickness: var(--handle-underline-thickness, 1.5px);
  text-decoration-color: color-mix(in srgb, var(--active-op-color, var(--teal)) 56%, transparent);
  text-underline-offset: var(--handle-underline-offset, 0.16em);
}

/* Flavor axis (drift resolution, 2026-07-03): data-spw-operator agrees with
   the visible sigil; the destination's genre keeps its color through a
   flavor: token in the op bundle. One map, alias register, paint-only. */
:where([data-spw-op~="flavor:stream"]) { --active-op-color: var(--op-stream-color); }
:where([data-spw-op~="flavor:wonder"]) { --active-op-color: var(--op-wonder-color, var(--op-probe-color)); }
:where([data-spw-op~="flavor:integrate"]) { --active-op-color: var(--op-integration-color, var(--op-object-color)); }
:where([data-spw-op~="flavor:surface"]) { --active-op-color: var(--op-surface-color, var(--op-concept-color)); }
:where([data-spw-op~="flavor:action"]) { --active-op-color: var(--op-action-color); }
:where([data-spw-op~="flavor:route"]) { --active-op-color: var(--op-route-color, var(--op-frame-color)); }

/* Sigil anatomy (hydrated): raw HTML keeps fused text; the sigil-anatomy
   module wraps sigil and operand in distinct spans with spacing preserved,
   so these rules are enhancement-only and cause no shift at hydration.
   The sigil is the grammar voice; the operand keeps the reading voice. */
:where([data-spw-sigil-anatomy="hydrated"]) .spw-sigil {
  font-family: var(--handle-meta-font, var(--site-mono-font, monospace));
  font-weight: 650;
  color: color-mix(in srgb, var(--active-op-color, var(--teal)) 78%, currentColor);
}

:where([data-spw-sigil-anatomy="hydrated"]) .spw-operand {
  font-weight: inherit;
}

/* Sigils in copy are references: an inline semantic carrier inside prose
   points at something primeable, so it wears the reference seam by default
   (dotted; dereferencing resolves it solid elsewhere). Reading stays calm -
   the seam is quieter than link styling and never changes layout. */
:where(p, li, dd, figcaption, .frame-note)
  :where(a, span, strong, em, i, code, kbd, mark, small, time):where([data-spw-charge-key], [data-spw-inline-form], [data-spw-operator]):not(.operator-chip, .frame-sigil) {
  text-decoration-line: underline;
  text-decoration-style: dotted;
  text-decoration-color: color-mix(in srgb, var(--active-op-color, var(--teal)) 30%, transparent);
  text-decoration-thickness: 1px;
  text-underline-offset: var(--handle-underline-offset, 0.16em);
}

:where([data-spw-fixity-tier="volatile"]) {
  --spw-fixity-alpha: 0.72;
}

/* ==========================================================================
   5. Operator chips, spec pills, and component tags
   ========================================================================== */

.operator-chip {
  --operator-chip-border-width: 1px;
  --operator-chip-border-style: solid;
  --operator-chip-bg: color-mix(in oklab, var(--surface-strong, #fff) 92%, var(--active-op-color, var(--teal)) 8%);
