:where([data-spw-selection="focused"]) {
  --handle-line: color-mix(in srgb, var(--active-op-color, var(--teal)) 54%, transparent);
}

:where(
  .operator-chip[aria-current="page"],
  [data-spw-selection="active"],
  [data-spw-selection="selected"]
