/* --------------------------------------------------------------------------
   Mode-switch clusters (handles layer — outranks routes)
   --------------------------------------------------------------------------
   Layout and chrome live here so routes never need !important escapes.
   Routes set palette via --mode-switch-*-intent and opt into chrome/track:

     data-spw-lens-chrome="silent"  — AT keeps aria-label; visual label chip off
     data-spw-lens-track="row"      — full-width equal-share flex track (no 2×2)

   Progressive enhancement: labeled chrome only when aria-label is present;
   silent/row are pure attribute contracts (no JS).
   -------------------------------------------------------------------------- */

/* Cluster A — track layout (flex-first; grid only as a narrow 4+ fallback) */
.mode-switch {
  --spw-lens-cascade-color: var(--active-op-color, var(--teal));
  --spw-lens-track-bg: color-mix(in srgb, var(--surface-strong, rgba(255, 255, 255, 0.9)) 88%, var(--spw-lens-cascade-color) 12%);
  --spw-lens-track-border: color-mix(in srgb, var(--spw-lens-cascade-color) 20%, var(--line, rgba(14, 18, 20, 0.14)) 80%);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: calc(var(--spw-control-gap, 0.24rem) + 0.1rem);
  min-width: 0;
  padding: 0.16rem;
  border: 1px solid var(--spw-lens-track-border);
  border-radius: var(--shape-control, 0.68rem);
  background: var(--spw-lens-track-bg);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--surface-strong, #fff) 44%, transparent),
    0 0 0 1px color-mix(in srgb, var(--spw-lens-cascade-color) 7%, transparent);
  isolation: isolate;
}

/* Cluster B — labeled chrome (default when aria-label is authored) */
.mode-switch[aria-label]::before {
  content: attr(aria-label);
  flex: 0 0 auto;
  max-inline-size: min(100%, 22ch);
  overflow: hidden;
  padding: 0.14rem 0.42rem;
  border: 1px solid color-mix(in srgb, var(--active-op-color, var(--teal)) 14%, transparent);
  border-radius: 999px;
  box-shadow: var(--spw-chassis-highlight, inset 0 1px 0 rgba(255, 255, 255, 0.2));
  color: color-mix(in srgb, var(--ink-soft, rgba(14, 18, 20, 0.72)) 82%, var(--active-op-color, var(--teal)) 18%);
  font-family: var(--handle-meta-font, var(--site-mono-font, monospace));
  font-size: 0.62rem;
  font-weight: 750;
  letter-spacing: 0.08em;
  line-height: 1.2;
  text-overflow: ellipsis;
  text-transform: uppercase;
  text-wrap: balance;
  white-space: nowrap;
}

.mode-switch[data-spw-lens-feedback]::after {
  content: attr(data-spw-lens-feedback);
  flex: 1 1 9rem;
  min-inline-size: 0;
  max-inline-size: min(100%, 24ch);
  overflow: hidden;
  padding: 0.14rem 0.42rem;
  border-radius: 999px;
  color: color-mix(in srgb, var(--ink-muted, rgba(14, 18, 20, 0.64)) 78%, var(--spw-lens-cascade-color) 22%);
  font-family: var(--handle-meta-font, var(--site-mono-font, monospace));
  font-size: 0.6rem;
  font-weight: 700;
  letter-spacing: 0;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Cluster C — silent chrome (specificity must beat Cluster B) */
.mode-switch[data-spw-lens-chrome~="silent"]::before,
.mode-switch[data-spw-lens-chrome~="silent"][aria-label]::before,
.mode-switch[data-spw-lens-chrome~="silent"]::after,
.mode-switch[data-spw-lens-chrome~="silent"][data-spw-lens-feedback]::after {
  content: none;
  display: none;
}

/* Cluster D — dedicated full-row track (composition hub, standalone lens rows) */
.mode-switch[data-spw-lens-track="row"] {
  display: flex;
  flex-flow: row nowrap;
  align-items: stretch;
  width: 100%;
  max-inline-size: 100%;
  min-inline-size: 0;
  margin: 0;
  box-sizing: border-box;
  grid-template-columns: none;
}

.mode-switch[data-spw-lens-track="row"] > .frame-sigil {
  flex: 1 1 0;
  min-inline-size: 0;
  max-inline-size: none;
  padding-inline: 0.55rem;
  white-space: nowrap;
  overflow: visible;
  text-overflow: clip;
  justify-content: center;
  text-align: center;
}

/* Cluster E — tablet / narrow shells: flex equal-share, not 2×2 masonry.
   A rigid 2×2 grid clipped 3-button lenses (read|inspect|reuse). */
@media (max-width: 56rem) {
  .mode-switch[aria-label]:not([data-spw-lens-track="row"]) {
    display: flex;
    flex-flow: row wrap;
    align-items: stretch;
    width: 100%;
    max-inline-size: 100%;
    min-inline-size: 0;
    box-sizing: border-box;
    gap: calc(var(--spw-control-gap, 0.24rem) + 0.14rem);
  }

  .mode-switch[data-spw-lens-feedback]:not([data-spw-lens-chrome~="silent"])::after {
    flex: 1 1 100%;
    max-inline-size: 100%;
  }

  .mode-switch[aria-label]:not([data-spw-lens-chrome~="silent"])::before {
    flex: 1 1 100%;
    width: 100%;
    max-inline-size: none;
    overflow: visible;
    text-overflow: clip;
    white-space: normal;
    text-wrap: balance;
  }

  .mode-switch:not([data-spw-lens-track="row"]) .frame-sigil {
    flex: 1 1 0;
    inline-size: auto;
    width: auto;
    min-inline-size: min(100%, 4.25rem);
    font-size: clamp(0.72rem, 2.7vw, calc(var(--text-size-chip, 0.84rem) - 0.04rem));
    padding-inline: calc(var(--spw-control-padding-inline, 0.72rem) - 0.2rem);
    white-space: nowrap;
    justify-content: center;
    text-align: center;
  }

  /* Inside a frame topline: occupy a full second row so chips don't steal width. */
  .frame-topline > .mode-switch,
  .frame-heading > .mode-switch {
    flex: 1 1 100%;
    width: 100%;
    margin-inline-start: 0;
  }
}

/* Cluster F — phone density; 2×2 only for labeled multi-option tracks (not row) */
@media (max-width: 32rem) {
  .mode-switch .frame-sigil {
    min-inline-size: 0;
    min-block-size: max(2.15rem, var(--touch-target-compact, 2.15rem));
    padding-inline: 0.4rem;
    font-size: clamp(0.68rem, 3.2vw, 0.8rem);
  }

  .mode-switch[data-spw-lens-track="row"] > .frame-sigil {
    font-size: clamp(0.72rem, 2.8vw, 0.84rem);
    padding-inline: 0.4rem;
  }

  /* 4+ lens options: 2×2 only when the track is narrow and not a forced row. */
  .mode-switch[aria-label]:has(> .frame-sigil:nth-child(4)):not([data-spw-lens-track="row"]) {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .mode-switch[aria-label]:has(> .frame-sigil:nth-child(4)):not([data-spw-lens-track="row"])::before,
  .mode-switch[aria-label]:has(> .frame-sigil:nth-child(4)):not([data-spw-lens-track="row"])[data-spw-lens-feedback]::after {
    grid-column: 1 / -1;
  }
}

/* Progressive: honor container width when the parent establishes a container. */
@supports (container-type: inline-size) {
  @container (max-width: 38rem) {
    .mode-switch[aria-label]:not([data-spw-lens-track="row"]) {
      display: flex;
