    ),
    repeating-linear-gradient(
      180deg,
      color-mix(in srgb, var(--spw-image-accent) 12%, rgba(255, 255, 255, 0.03)) 0 var(--spw-image-pixel-line),
      transparent var(--spw-image-pixel-line) var(--spw-image-pixel-cell)
    ),
    radial-gradient(
