  [data-spw-surface],
  [data-spw-feature],
  [data-spw-module],
  [data-spw-module-evaluates],
  [data-spw-slot],
  [data-spw-kind],
  [data-spw-component-id],
  [data-spw-semantic-owner],
  [data-spw-layout-owner],
  [data-spw-floating-chrome="true"]
) {
  --spw-css-debug-color: var(--active-op-color, var(--teal, #008080));
